fn map_credential_storage_error(error: StorageError) -> ControlError {
    match error {
        StorageError::DuplicateCredentialIdentity => ControlError::CredentialDuplicate,
        other => ControlError::storage(other),
    }
}

fn map_identity_storage_error(error: StorageError) -> ControlError {
    match error {
        StorageError::DuplicateIdentity => ControlError::IdentityDuplicate,
        other => ControlError::storage(other),
    }
}

#[derive(Clone, Default)]
struct RunnerHub {
    inner: Arc<RunnerHubInner>,
}

#[derive(Default)]
struct RunnerHubInner {
    next_generation: AtomicU64,
    connections: Mutex<HashMap<String, HubConnection>>,
    tasks: Mutex<HashMap<String, RunnerTaskSubscription>>,
    pings: Mutex<HashMap<String, oneshot::Sender<()>>>,
    session_gates: Mutex<HashMap<String, std::sync::Weak<Mutex<()>>>>,
}

struct RunnerCancellation {
    sender: mpsc::WeakSender<Vec<u8>>,
    frame: Vec<u8>,
    terminal: Arc<AtomicBool>,
}

impl Drop for RunnerCancellation {
    fn drop(&mut self) {
        if !self.terminal.load(Ordering::Acquire) {
            // Best effort if the channel is full or disconnected. The signed
            // execution deadline independently limits work at the Runner.
            if let Some(sender) = self.sender.upgrade() {
                let _ = sender.try_send(std::mem::take(&mut self.frame));
            }
        }
    }
}

struct HubConnection {
    generation: u64,
    sender: mpsc::Sender<Vec<u8>>,
}

#[derive(Clone)]
struct RunnerTaskSubscription {
    terminal: Arc<AtomicBool>,
    runner_id: String,
    generation: u64,
    sender: mpsc::Sender<RunnerToControl>,
}

struct ReservedRunnerDispatch {
    runner_id: String,
    generation: u64,
    sender: mpsc::Sender<Vec<u8>>,
    permit: mpsc::OwnedPermit<Vec<u8>>,
}

#[derive(Debug)]
struct RunnerDispatchFailure {
    error: ControlError,
    excluded_runner_id: Option<String>,
}

impl From<ControlError> for RunnerDispatchFailure {
    fn from(error: ControlError) -> Self {
        Self {
            error,
            excluded_runner_id: None,
        }
    }
}

impl RunnerDispatchFailure {
    fn unavailable(runner_id: Option<String>) -> Self {
        Self {
            error: ControlError::Routing(RoutingError::NoRunnerReady),
            excluded_runner_id: runner_id,
        }
    }
}

impl RunnerHub {
    async fn session_gate(&self, runner_id: &str) -> Arc<Mutex<()>> {
        let mut gates = self.inner.session_gates.lock().await;
        gates.retain(|_, gate| gate.strong_count() > 0);
        if let Some(gate) = gates.get(runner_id).and_then(std::sync::Weak::upgrade) {
            return gate;
        }
        let gate = Arc::new(Mutex::new(()));
        gates.insert(runner_id.to_owned(), Arc::downgrade(&gate));
        gate
    }
    async fn is_current_connection(&self, runner_id: &str, generation: u64) -> bool {
        self.inner
            .connections
            .lock()
            .await
            .get(runner_id)
            .is_some_and(|connection| connection.generation == generation)
    }
    async fn register(&self, runner_id: &str) -> (u64, mpsc::Receiver<Vec<u8>>) {
        let generation = self
            .inner
            .next_generation
            .fetch_add(1, Ordering::Relaxed)
            .saturating_add(1);
        let (sender, receiver) = mpsc::channel(128);
        self.inner
            .connections
            .lock()
            .await
            .insert(runner_id.to_owned(), HubConnection { generation, sender });
        (generation, receiver)
    }

    async fn unregister(&self, runner_id: &str, generation: u64) {
        let mut connections = self.inner.connections.lock().await;
        if connections
            .get(runner_id)
            .is_some_and(|connection| connection.generation == generation)
        {
            connections.remove(runner_id);
        }
        drop(connections);
        self.inner
            .tasks
            .lock()
            .await
            .retain(|_, task| task.runner_id != runner_id || task.generation != generation);
    }

    async fn disconnect(&self, runner_id: &str) {
        self.inner.connections.lock().await.remove(runner_id);
    }

    async fn ping(&self, runner_id: &str) -> Result<(), ControlError> {
        let sender = self
            .inner
            .connections
            .lock()
            .await
            .get(runner_id)
            .map(|connection| connection.sender.clone())
            .ok_or(ControlError::Routing(RoutingError::NoRunnerReady))?;
        let nonce = format!(
            "ping_{}",
            self.inner
                .next_generation
                .fetch_add(1, Ordering::Relaxed)
                .saturating_add(1)
        );
        let encoded =
            encode_control_frame(&ControlToRunner::Ping(aster_runner_protocol::PingFrame {
                nonce: nonce.clone(),
            }))
            .map_err(ControlError::RunnerTicket)?;
        let (completion, receiver) = oneshot::channel();
        self.inner
            .pings
            .lock()
            .await
            .insert(nonce.clone(), completion);
        if !matches!(
            lifecycle::run_execution(std::time::Duration::from_secs(5), sender.send(encoded)).await,
            Ok(Ok(()))
        ) {
            self.inner.pings.lock().await.remove(&nonce);
            return Err(ControlError::Routing(RoutingError::NoRunnerReady));
        }
        let result = tokio::time::timeout(std::time::Duration::from_secs(5), receiver).await;
        self.inner.pings.lock().await.remove(&nonce);
        match result {
            Ok(Ok(())) => Ok(()),
            _ => Err(ControlError::Routing(RoutingError::NoRunnerReady)),
        }
    }

    async fn pong(&self, nonce: &str) {
        if let Some(completion) = self.inner.pings.lock().await.remove(nonce) {
            let _ = completion.send(());
        }
    }

    async fn online_count(&self) -> usize {
        self.inner.connections.lock().await.len()
    }

    async fn online_ids(&self) -> Vec<String> {
        self.inner
            .connections
            .lock()
            .await
            .keys()
            .cloned()
            .collect()
    }

    async fn dispatch(
        &self,
        runner_id: &str,
        task_id: &str,
        encoded: Vec<u8>,
    ) -> Result<(mpsc::Receiver<RunnerToControl>, RunnerCancellation), ControlError> {
        let slot = self
            .reserve_dispatch(runner_id)
            .await
            .map_err(|failure| failure.error)?;
        self.dispatch_reserved(slot, task_id, encoded)
            .await
            .map_err(|failure| failure.error)
    }

    async fn reserve_dispatch(
        &self,
        runner_id: &str,
    ) -> Result<ReservedRunnerDispatch, RunnerDispatchFailure> {
        let (sender, generation) = self
            .inner
            .connections
            .lock()
            .await
            .get(runner_id)
            .map(|connection| (connection.sender.clone(), connection.generation))
            .ok_or_else(|| RunnerDispatchFailure::unavailable(Some(runner_id.to_owned())))?;
        let permit = lifecycle::run_execution(
            std::time::Duration::from_secs(
                aster_runner_protocol::TASK_TICKET_LIFETIME_SECONDS as u64,
            ),
            sender.clone().reserve_owned(),
        )
        .await;
        let permit = match permit {
            Ok(Ok(permit)) => permit,
            _ => {
                let connections = self.inner.connections.lock().await;
                let reconnected = connections.get(runner_id).is_some_and(|connection| {
                    connection.generation != generation && !connection.sender.is_closed()
                });
                return Err(RunnerDispatchFailure::unavailable(
                    (!reconnected).then(|| runner_id.to_owned()),
                ));
            }
        };
        Ok(ReservedRunnerDispatch {
            runner_id: runner_id.to_owned(),
            generation,
            sender,
            permit,
        })
    }

    async fn dispatch_reserved(
        &self,
        slot: ReservedRunnerDispatch,
        task_id: &str,
        encoded: Vec<u8>,
    ) -> Result<(mpsc::Receiver<RunnerToControl>, RunnerCancellation), RunnerDispatchFailure> {
        let connections = self.inner.connections.lock().await;
        if slot.sender.is_closed()
            || !connections.get(&slot.runner_id).is_some_and(|connection| {
                connection.generation == slot.generation
                    && connection.sender.same_channel(&slot.sender)
            })
        {
            let reconnected = connections.get(&slot.runner_id).is_some_and(|connection| {
                connection.generation != slot.generation && !connection.sender.is_closed()
            });
            return Err(RunnerDispatchFailure::unavailable(
                (!reconnected).then_some(slot.runner_id),
            ));
        }
        let (events, receiver) = mpsc::channel(1024);
        let terminal = Arc::new(AtomicBool::new(false));
        let cancellation = RunnerCancellation {
            sender: slot.sender.downgrade(),
            frame: encode_control_frame(&ControlToRunner::CancelTask(
                aster_runner_protocol::TaskLifecycle {
                    task_id: task_id.to_owned(),
                },
            ))
            .map_err(ControlError::RunnerTicket)?,
            terminal: terminal.clone(),
        };
        self.inner.tasks.lock().await.insert(
            task_id.to_owned(),
            RunnerTaskSubscription {
                runner_id: slot.runner_id.clone(),
                generation: slot.generation,
                sender: events,
                terminal,
            },
        );
        slot.permit.send(encoded);
        drop(connections);
        let hub = self.clone();
        let cleanup_task_id = task_id.to_owned();
        tokio::spawn(async move {
            tokio::time::sleep(std::time::Duration::from_secs(600)).await;
            hub.inner.tasks.lock().await.remove(&cleanup_task_id);
        });
        Ok((receiver, cancellation))
    }

    async fn publish_from(&self, runner_id: &str, generation: u64, frame: RunnerToControl) {
        // Use the same connections -> tasks lock order as dispatch. A replaced
        // channel cannot publish into a task owned by the new connection, nor
        // can another authenticated Runner publish an observed task ID.
        let connections = self.inner.connections.lock().await;
        if connections
            .get(runner_id)
            .is_none_or(|connection| connection.generation != generation)
        {
            return;
        }
        let Some((task_id, terminal)) = runner_event_task(&frame) else {
            return;
        };
        let task_id = task_id.to_owned();
        let mut tasks = self.inner.tasks.lock().await;
        let Some(task) = tasks.get(&task_id) else {
            return;
        };
        if task.runner_id != runner_id || task.generation != generation {
            return;
        }
        if terminal {
            task.terminal.store(true, Ordering::Release);
        }
        let failed = task.sender.try_send(frame).is_err();
        if terminal || failed {
            tasks.remove(&task_id);
        }
    }

    #[cfg(test)]
    async fn publish(&self, frame: RunnerToControl) {
        let Some((task_id, _)) = runner_event_task(&frame) else {
            return;
        };
        let task = self.inner.tasks.lock().await.get(task_id).cloned();
        if let Some(task) = task {
            self.publish_from(&task.runner_id, task.generation, frame)
                .await;
        }
    }
}

fn runner_event_task(frame: &RunnerToControl) -> Option<(&str, bool)> {
    match frame {
        RunnerToControl::TaskAccepted(value) | RunnerToControl::UpstreamStarted(value) => {
            Some((&value.task_id, false))
        }
        RunnerToControl::TaskResponseStarted(value) => Some((&value.task_id, false)),
        RunnerToControl::TaskChunk(value) => Some((&value.task_id, false)),
        RunnerToControl::TaskFinished(value) => Some((&value.task_id, true)),
        RunnerToControl::CredentialRefreshed(value) => Some((&value.task_id, true)),
        RunnerToControl::TaskFailed(value) => Some((&value.task_id, true)),
        RunnerToControl::Hello(_) | RunnerToControl::Heartbeat(_) | RunnerToControl::Pong(_) => {
            None
        }
    }
}

