#[derive(Clone)]
pub struct RunnerTaskIssuer {
    key_id: Arc<str>,
    signing_key: Arc<SigningKey>,
}

impl RunnerTaskIssuer {
    pub fn new(key_id: impl Into<Arc<str>>, signing_key: SigningKey) -> Self {
        Self {
            key_id: key_id.into(),
            signing_key: Arc::new(signing_key),
        }
    }

    fn public_keys(&self) -> Result<RunnerTaskPublicKeysDocument, ControlError> {
        let public_key = self
            .signing_key
            .verifying_key()
            .to_public_key_der()
            .map_err(|_| ControlError::DataIntegrityInvalid)?;
        Ok(RunnerTaskPublicKeysDocument {
            schema: "aster.runner-task-keys.v1",
            keys: vec![RunnerTaskPublicKeyEntry {
                key_id: self.key_id.to_string(),
                public_key_spki: URL_SAFE_NO_PAD.encode(public_key.as_bytes()),
            }],
        })
    }
}

