#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct FrozenBillingContext {
    selected_price: BillingSelectedPrice,
    settlement_currency: BillingCurrency,
    usd_to_cny: Option<BillingExchangeRate>,
    selected_at: String,
    reference_nanos: i64,
}

impl FrozenBillingContext {
    fn convert(&self, source: BillingMoney) -> Result<BillingMoney, ControlError> {
        if source.currency == self.settlement_currency {
            return Ok(source);
        }
        let rate = self
            .usd_to_cny
            .ok_or(ControlError::BillingPriceUnavailable)?;
        if source.currency == BillingCurrency::Usd
            && self.settlement_currency == BillingCurrency::Cny
        {
            rate.convert(source)
        } else if source.currency == BillingCurrency::Cny
            && self.settlement_currency == BillingCurrency::Usd
        {
            rate.convert_reverse(source)
        } else {
            return Err(ControlError::BillingPriceUnavailable);
        }
        .map_err(|_| ControlError::BillingCalculationInvalid)
    }
}

