pub struct BootstrapLocalRunnerIdentity {
    pub runner_id: String,
    pub credential: Zeroizing<String>,
}

impl BootstrapLocalRunnerIdentity {
    pub fn generate() -> Result<Self, ControlError> {
        Ok(Self {
            runner_id: random_identifier("runner")?,
            credential: Zeroizing::new(format!("arr_{}", random_url_secret(48)?)),
        })
    }

    pub fn validate(&self) -> Result<(), ControlError> {
        let id = self
            .runner_id
            .strip_prefix("runner_")
            .ok_or(ControlError::RunnerInputInvalid)?;
        let credential = self
            .credential
            .strip_prefix("arr_")
            .ok_or(ControlError::RunnerInputInvalid)?;
        if id.len() != 32
            || !id
                .bytes()
                .all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase())
            || credential.len() != 64
            || !credential
                .bytes()
                .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'-' | b'_'))
        {
            return Err(ControlError::RunnerInputInvalid);
        }
        Ok(())
    }
}

pub fn generate_bootstrap_local_runner_identity()
-> Result<BootstrapLocalRunnerIdentity, ControlError> {
    BootstrapLocalRunnerIdentity::generate()
}

