    fn balance_integrity_hmac(&self, balance: &UserBalanceRecord) -> Result<String, ControlError> {
        let value = serde_json::to_vec(&BalanceIntegrityPayload {
            identity_id: &balance.identity_id,
            balance_tokens: balance.balance_tokens,
            reserved_tokens: balance.reserved_tokens,
            granted_tokens: balance.granted_tokens,
            consumed_tokens: balance.consumed_tokens,
            request_count: balance.request_count,
            raw_tokens: balance.raw_tokens,
            billed_tokens: balance.billed_tokens,
            uncached_input: balance.uncached_input,
            cached_input: balance.cached_input,
            cache_write: balance.cache_write,
            output_tokens: balance.output_tokens,
            last_ledger_hmac: &balance.last_ledger_hmac,
        })
        .map_err(|_| ControlError::DataIntegrityInvalid)?;
        self.auth_core()?
            .security_state_integrity_hmac(SecurityStateIntegrityInput {
                key: QUOTA_BALANCE_INTEGRITY_KEY,
                value: &value,
                revision: balance.revision,
            })
            .map_err(ControlError::Auth)
    }

