    fn verify_quota_ledger(
        &self,
        identity_id: &str,
        balance: &UserBalanceRecord,
        entries: &[QuotaLedgerEntry],
    ) -> Result<(), ControlError> {
        if entries.is_empty() {
            return if balance.last_ledger_hmac.is_empty() {
                Ok(())
            } else {
                Err(ControlError::DataIntegrityInvalid)
            };
        }
        // Index links once instead of rescanning the full history at every hop.
        // Duplicate predecessors are forks; duplicate digests are replayed nodes.
        let mut successors = HashMap::with_capacity(entries.len());
        let mut digests = HashSet::with_capacity(entries.len());
        for entry in entries {
            if successors
                .insert(entry.previous_entry_hmac.as_str(), entry)
                .is_some()
                || !digests.insert(entry.integrity_hmac.as_str())
            {
                return Err(ControlError::DataIntegrityInvalid);
            }
        }
        let mut previous_hmac = "";
        for _ in 0..entries.len() {
            let entry = successors
                .remove(previous_hmac)
                .ok_or(ControlError::DataIntegrityInvalid)?;
            if entry.identity_id != identity_id || !valid_signed_ledger_shape(entry) {
                return Err(ControlError::DataIntegrityInvalid);
            }
            let expected_hmac = self.ledger_integrity_hmac(entry)?;
            let prior_schema_hmac = self.previous_ledger_integrity_hmac(entry)?;
            let legacy_hmac = self.legacy_ledger_integrity_hmac(entry)?;
            let current_schema_valid =
                constant_time_string_eq(&expected_hmac, &entry.integrity_hmac);
            let previous_schema_valid = entry.client_request_id.is_none()
                && constant_time_string_eq(&prior_schema_hmac, &entry.integrity_hmac);
            let legacy_schema_valid = entry.client_request_id.is_none()
                && entry.requested_model.is_none()
                && entry.processing_tier.is_none()
                && entry.reasoning_effort.is_none()
                && constant_time_string_eq(&legacy_hmac, &entry.integrity_hmac);
            if !current_schema_valid && !previous_schema_valid && !legacy_schema_valid {
                return Err(ControlError::DataIntegrityInvalid);
            }
            previous_hmac = &entry.integrity_hmac;
        }
        if previous_hmac != balance.last_ledger_hmac {
            return Err(ControlError::DataIntegrityInvalid);
        }
        Ok(())
    }

    async fn verified_quota_snapshot(
        &self,
        identity_id: &str,
    ) -> Result<QuotaStateSnapshot, ControlError> {
        let snapshot = self
            .credential_storage()?
            .quota_state_snapshot(identity_id)
            .await?
            .ok_or(ControlError::DataIntegrityInvalid)?;
        let balance = &snapshot.balance;
        if balance.identity_id != identity_id
            || balance.balance_tokens < 0
            || balance.reserved_tokens < 0
            || balance.reserved_tokens > balance.balance_tokens
            || balance.granted_tokens < 0
            || balance.consumed_tokens < 0
            || balance.request_count < 0
            || balance.raw_tokens < 0
            || balance.billed_tokens < 0
            || balance.uncached_input < 0
            || balance.cached_input < 0
            || balance.cache_write < 0
            || balance.output_tokens < 0
        {
            return Err(ControlError::DataIntegrityInvalid);
        }
        let expected_balance_hmac = self.balance_integrity_hmac(balance)?;
        if !constant_time_string_eq(&expected_balance_hmac, &balance.integrity_hmac) {
            return Err(ControlError::DataIntegrityInvalid);
        }
        self.verify_quota_ledger(identity_id, balance, &snapshot.ledger_entries)?;
        let mut reserved_total = 0_i64;
        for reservation in &snapshot.active_reservations {
            if reservation.identity_id != identity_id
                || reservation.status != "active"
                || reservation.reserved_tokens <= 0
                || reservation.settled_at.is_some()
            {
                return Err(ControlError::DataIntegrityInvalid);
            }
            reserved_total = reserved_total
                .checked_add(reservation.reserved_tokens)
                .ok_or(ControlError::DataIntegrityInvalid)?;
            let expected_hmac = self.reservation_integrity_hmac(reservation)?;
            if !constant_time_string_eq(&expected_hmac, &reservation.integrity_hmac) {
                return Err(ControlError::DataIntegrityInvalid);
            }
        }
        if reserved_total != balance.reserved_tokens {
            return Err(ControlError::DataIntegrityInvalid);
        }
        Ok(snapshot)
    }

