    #[allow(clippy::too_many_arguments)]
    async fn commit_credential_refresh_inner(
        &self,
        credential_id: &str,
        expected_revision: u32,
        lease_token: &str,
        stable_secret: &[u8],
        plaintext_payload: &[u8],
        expires_at: &str,
        audit: bool,
        actor: Option<&IdentityRecord>,
    ) -> Result<(), ControlError> {
        if let Some(actor) = actor {
            validate_admin_actor(self, actor).await?;
            authorize_non_consuming_operation(self, BusinessOperationId::UpstreamRefresh)?;
        }
        let storage = self.credential_storage()?;
        let record = storage
            .credential_instance_by_id(credential_id)
            .await?
            .ok_or(ControlError::CredentialNotFound)?;
        if record.credential_revision != expected_revision {
            let _ = storage
                .release_credential_refresh_lease(
                    credential_id,
                    &sha256_hex(lease_token.as_bytes()),
                )
                .await;
            return Err(ControlError::CredentialRefreshConflict);
        }
        let provider = storage
            .upstream_account_provider(&record.account_id)
            .await?
            .ok_or(ControlError::UpstreamAccountNotFound)?;
        let vault = self.credential_vault()?;
        let next_revision = expected_revision
            .checked_add(1)
            .ok_or(ControlError::CredentialRefreshConflict)?;
        let material = vault
            .encrypt(
                &CredentialContext {
                    credential_id,
                    account_id: &record.account_id,
                    revision: next_revision,
                },
                plaintext_payload,
            )
            .map_err(ControlError::CredentialVault)?;
        let credential_identity_hmac = vault
            .credential_identity_hmac(&provider, stable_secret)
            .map_err(ControlError::CredentialVault)?;
        let refreshed_at =
            format_database_time((self.now)()).map_err(|_| ControlError::TimeConversionFailed)?;
        let lease_token_hash = sha256_hex(lease_token.as_bytes());
        let update = CredentialRefreshUpdate {
            credential_identity_hmac,
            encrypted_payload: material.encrypted_payload,
            payload_nonce: material.payload_nonce,
            wrapped_data_key: material.wrapped_data_key,
            wrap_nonce: material.wrap_nonce,
            expires_at: expires_at.to_owned(),
            refreshed_at: refreshed_at.clone(),
        };
        if audit {
            for _ in 0..AUDIT_APPEND_RETRIES {
                let (expected_audit_sequence, expected_audit_hmac, audit_event) = self
                    .prepare_audit_event(
                        actor,
                        "upstream_credential.refresh",
                        "upstream_credential",
                        Some(credential_id),
                        "succeeded",
                    )
                    .await?;
                if let Some(actor) = actor {
                    validate_admin_actor(self, actor).await?;
                    authorize_non_consuming_operation(self, BusinessOperationId::UpstreamRefresh)?;
                }
                match storage
                    .update_credential_after_refresh_and_audit(
                        credential_id,
                        expected_revision,
                        &lease_token_hash,
                        &refreshed_at,
                        &update,
                        expected_audit_sequence,
                        &expected_audit_hmac,
                        &audit_event,
                    )
                    .await?
                {
                    MutationWithAuditOutcome::Mutation(true) => return Ok(()),
                    MutationWithAuditOutcome::Mutation(false) => {
                        return Err(ControlError::CredentialRefreshLeaseInvalid);
                    }
                    MutationWithAuditOutcome::AuditConflict => continue,
                }
            }
            return Err(ControlError::DataIntegrityInvalid);
        }
        #[cfg(test)]
        {
            if storage
                .update_credential_after_refresh(
                    credential_id,
                    expected_revision,
                    &lease_token_hash,
                    &refreshed_at,
                    &update,
                )
                .await?
            {
                Ok(())
            } else {
                Err(ControlError::CredentialRefreshLeaseInvalid)
            }
        }
        #[cfg(not(test))]
        {
            Err(ControlError::DataIntegrityInvalid)
        }
    }

    async fn refresh_openai_credential_via_runner_inner(
        &self,
        credential_id: &str,
        actor: Option<&IdentityRecord>,
    ) -> Result<(), ControlError> {
        if let Some(actor) = actor {
            validate_admin_actor(self, actor).await?;
            authorize_non_consuming_operation(self, BusinessOperationId::UpstreamRefresh)?;
        } else {
            authorize_non_consuming_feature(self, "runner")?;
        }
        let lease = self.begin_credential_refresh(credential_id).await?;
        let outcome = self.run_openai_credential_refresh(&lease, actor).await;
        if outcome.is_err() {
            let _ = self
                .cancel_credential_refresh(credential_id, lease.lease_token.as_str())
                .await;
        }
        outcome
    }

    async fn run_openai_credential_refresh(
        &self,
        lease: &CredentialRefreshLease,
        actor: Option<&IdentityRecord>,
    ) -> Result<(), ControlError> {
        let current = decode_openai_credential(&lease.credential.plaintext_payload)?;
        if current.provider != "openai" || current.refresh_token.is_empty() {
            return Err(ControlError::CredentialInvalid);
        }
        let form = Zeroizing::new(format!(
            "grant_type=refresh_token&client_id={}&refresh_token={}",
            form_component(OPENAI_OAUTH_CLIENT_ID),
            form_component(&current.refresh_token),
        ));
        let task = CredentialRefreshTask {
            credential_id: lease.credential.id.clone(),
            expected_revision: lease.credential.credential_revision,
            request: UpstreamHttpRequest {
                method: "POST".to_owned(),
                url: OPENAI_TOKEN_ENDPOINT.to_owned(),
                headers: vec![
                    UpstreamRequestHeader {
                        name: "content-type".to_owned(),
                        value: "application/x-www-form-urlencoded".to_owned(),
                    },
                    UpstreamRequestHeader {
                        name: "accept".to_owned(),
                        value: "application/json".to_owned(),
                    },
                    UpstreamRequestHeader {
                        name: "user-agent".to_owned(),
                        value: "aster-runner-oauth/0.1".to_owned(),
                    },
                ],
                body_base64url: encode_base64url(form.as_bytes()),
            },
        };
        let payload =
            Zeroizing::new(serde_json::to_vec(&task).map_err(|_| ControlError::CredentialInvalid)?);
        let preferred_runner = self
            .credential_storage()?
            .upstream_account_by_id(&lease.credential.account_id)
            .await?
            .and_then(|account| account.last_success_runner_id);
        let binding = RunnerTaskBinding::credential(
            "openai",
            &lease.credential.id,
            lease.credential.credential_revision,
            "auth.openai.com",
        );
        let result = self
            .execute_credential_refresh_task(
                preferred_runner.as_deref(),
                &binding,
                RunnerTaskAuthorization::RefreshCredential { actor, lease },
                payload.as_slice(),
            )
            .await?;
        self.commit_openai_refresh_result_with_audit(lease, current, result, actor)
            .await
    }

    async fn execute_credential_refresh_task(
        &self,
        preferred_runner_id: Option<&str>,
        binding: &RunnerTaskBinding,
        authorization: RunnerTaskAuthorization<'_>,
        payload: &[u8],
    ) -> Result<CredentialRefreshResult, ControlError> {
        let mut excluded = HashSet::new();
        for attempt in 0..2 {
            let dispatched = self
                .dispatch_runner_task_excluding(
                    preferred_runner_id,
                    binding,
                    authorization,
                    payload,
                    &excluded,
                )
                .await;
            let mut handle = match dispatched {
                Ok(handle) => handle,
                // No ticket was enqueued. Re-select the live connection, including
                // a new generation of the same Runner, without excluding its ID.
                Err(failure)
                    if matches!(
                        failure.error,
                        ControlError::Routing(RoutingError::NoRunnerReady)
                    ) && attempt == 0 =>
                {
                    if let Some(runner_id) = failure.excluded_runner_id {
                        excluded.insert(runner_id);
                    }
                    continue;
                }
                Err(failure) => return Err(failure.error),
            };
            let expected_task_id = handle.task_id.clone();
            let runner_id = handle.runner_id.clone();
            let outcome = lifecycle::run_execution(CREDENTIAL_REFRESH_TASK_TIMEOUT, async {
                let mut accepted = false;
                let mut upstream_started = false;
                while let Some(frame) = handle.recv().await {
                    match frame {
                        RunnerToControl::TaskAccepted(frame)
                            if frame.task_id == expected_task_id && !accepted =>
                        {
                            accepted = true;
                        }
                        RunnerToControl::UpstreamStarted(frame)
                            if frame.task_id == expected_task_id
                                && accepted
                                && !upstream_started =>
                        {
                            upstream_started = true;
                        }
                        RunnerToControl::CredentialRefreshed(result)
                            if result.task_id == expected_task_id
                                && accepted
                                && upstream_started =>
                        {
                            return Ok(result);
                        }
                        RunnerToControl::TaskFailed(frame) if frame.task_id == expected_task_id => {
                            return Err(frame.retryable_before_upstream && !upstream_started);
                        }
                        _ => return Err(false),
                    }
                }
                Err(false)
            })
            .await;
            match outcome {
                Ok(Ok(result)) => return Ok(result),
                Ok(Err(true)) if attempt == 0 => {
                    excluded.insert(runner_id);
                }
                Ok(Err(_)) => return Err(ControlError::CredentialInvalid),
                Err(_) => return Err(ControlError::CredentialRefreshLeaseInvalid),
            }
        }
        Err(ControlError::Routing(RoutingError::NoRunnerReady))
    }

    #[cfg(test)]
    pub async fn sync_openai_models(&self, account_id: &str) -> Result<usize, ControlError> {
        self.sync_openai_models_inner(account_id, None).await
    }

    async fn sync_openai_models_with_audit(
        &self,
        account_id: &str,
        actor: &IdentityRecord,
    ) -> Result<usize, ControlError> {
        self.sync_openai_models_inner(account_id, Some(actor)).await
    }

    async fn sync_openai_models_inner(
        &self,
        account_id: &str,
        actor: Option<&IdentityRecord>,
    ) -> Result<usize, ControlError> {
        if let Some(actor) = actor {
            validate_admin_actor(self, actor).await?;
        }
        authorize_non_consuming_operation(self, BusinessOperationId::UpstreamSync)?;
        let storage = self.credential_storage()?;
        let account = storage
            .upstream_account_by_id(account_id)
            .await?
            .filter(|account| account.provider == "openai" && account.status == "active")
            .ok_or(ControlError::UpstreamAccountNotFound)?;
        let mut credentials = storage.credential_instances_for_account(account_id).await?;
        credentials.retain(|credential| credential.status == "active");
        credentials.sort_by(|left, right| {
            right
                .expires_at
                .cmp(&left.expires_at)
                .then_with(|| right.updated_at.cmp(&left.updated_at))
        });
        for record in credentials {
            let mut refreshed = false;
            for _ in 0..2 {
                let decrypted = match self.decrypt_credential_instance(&record.id).await {
                    Ok(value) => value,
                    Err(error) if recoverable_credential_candidate_error(&error) => break,
                    Err(error) => return Err(error),
                };
                let credential = match decode_openai_credential(&decrypted.plaintext_payload) {
                    Ok(value) if value.account_id == account.subject_id => value,
                    _ => break,
                };
                let expires_at = match OffsetDateTime::parse(&credential.expires_at, &Rfc3339) {
                    Ok(value) => value,
                    Err(_) => break,
                };
                if expires_at <= (self.now)() + time::Duration::minutes(2) && !refreshed {
                    match self
                        .refresh_openai_credential_via_runner_inner(&record.id, actor)
                        .await
                    {
                        Ok(()) => {
                            refreshed = true;
                            continue;
                        }
                        Err(error) if recoverable_credential_candidate_error(&error) => break,
                        Err(error) => return Err(error),
                    }
                }
                let response = self
                    .execute_runner_http_request_with_command(
                        account.last_success_runner_id.as_deref(),
                        &RunnerTaskBinding::credential(
                            "openai",
                            &record.id,
                            decrypted.credential_revision,
                            "chatgpt.com",
                        ),
                        RunnerTaskAuthorization::DiscoverModels {
                            actor,
                            credential: &decrypted,
                        },
                        &UpstreamHttpRequest {
                            method: "GET".to_owned(),
                            url: OPENAI_CODEX_MODELS_ENDPOINT.to_owned(),
                            headers: vec![
                                UpstreamRequestHeader {
                                    name: "authorization".to_owned(),
                                    value: format!("Bearer {}", credential.access_token),
                                },
                                UpstreamRequestHeader {
                                    name: "chatgpt-account-id".to_owned(),
                                    value: credential.account_id.clone(),
                                },
                                UpstreamRequestHeader {
                                    name: "accept".to_owned(),
                                    value: "application/json".to_owned(),
                                },
                                UpstreamRequestHeader {
                                    name: "originator".to_owned(),
                                    value: "Aster Team".to_owned(),
                                },
                                UpstreamRequestHeader {
                                    name: "user-agent".to_owned(),
                                    value: "Aster Team/0.1".to_owned(),
                                },
                            ],
                            body_base64url: String::new(),
                        },
                    )
                    .await;
                let response = match response {
                    Ok(response) => response,
                    Err(error)
                        if matches!(&error, ControlError::Routing(_))
                            || error.is_license_failure()
                            || error.is_identity_failure() =>
                    {
                        return Err(error);
                    }
                    Err(_) => break,
                };
                if matches!(response.status, 401 | 403) && !refreshed {
                    match self
                        .refresh_openai_credential_via_runner_inner(&record.id, actor)
                        .await
                    {
                        Ok(()) => {
                            refreshed = true;
                            continue;
                        }
                        Err(error) if recoverable_credential_candidate_error(&error) => break,
                        Err(error) => return Err(error),
                    }
                }
                if !(200..300).contains(&response.status) {
                    break;
                }
                let discovered = parse_openai_models(&response.body)?;
                let discovered_at = format_database_time((self.now)())
                    .map_err(|_| ControlError::TimeConversionFailed)?;
                if let Some(actor) = actor {
                    let mut committed = false;
                    for _ in 0..AUDIT_APPEND_RETRIES {
                        let (expected_audit_sequence, expected_audit_hmac, audit_event) = self
                            .prepare_audit_event(
                                Some(actor),
                                "upstream_model.sync",
                                "upstream_account",
                                Some(account_id),
                                "succeeded",
                            )
                            .await?;
                        validate_admin_actor(self, actor).await?;
                        authorize_non_consuming_operation(self, BusinessOperationId::UpstreamSync)?;
                        match storage
                            .replace_account_models_and_record_success_and_audit(
                                account_id,
                                &discovered,
                                &discovered_at,
                                &response.runner_id,
                                expected_audit_sequence,
                                &expected_audit_hmac,
                                &audit_event,
                            )
                            .await?
                        {
                            AuditedMutationOutcome::Applied => {
                                committed = true;
                                break;
                            }
                            AuditedMutationOutcome::MutationConflict => {
                                return Err(ControlError::UpstreamAccountNotFound);
                            }
                            AuditedMutationOutcome::AuditConflict => continue,
                        }
                    }
                    if !committed {
                        return Err(ControlError::DataIntegrityInvalid);
                    }
                } else {
                    #[cfg(test)]
                    {
                        storage
                            .replace_account_models(account_id, &discovered, &discovered_at)
                            .await?;
                        storage
                            .update_account_last_success_runner(
                                account_id,
                                &response.runner_id,
                                &discovered_at,
                            )
                            .await?;
                    }
                    #[cfg(not(test))]
                    {
                        return Err(ControlError::DataIntegrityInvalid);
                    }
                }
                self.invalidate_gateway_model_variants()?;
                return Ok(discovered.len());
            }
        }
        Err(ControlError::ModelSyncFailed)
    }

