struct GatewayError {
    inner: ControlError,
    anthropic: bool,
    request_id: Option<String>,
}

impl GatewayError {
    const fn new(inner: ControlError, anthropic: bool) -> Self {
        Self {
            inner,
            anthropic,
            request_id: None,
        }
    }

    fn with_request_id(inner: ControlError, anthropic: bool, request_id: &str) -> Self {
        Self {
            inner,
            anthropic,
            request_id: Some(request_id.to_owned()),
        }
    }
}

impl IntoResponse for GatewayError {
    fn into_response(self) -> Response {
        let descriptor = self.inner.descriptor();
        let status = self.inner.status();
        let request_id = self.request_id;
        let message = request_id.as_ref().map_or_else(
            || self.inner.safe_message(),
            |request_id| format!("{} (request ID: {request_id})", self.inner.safe_message()),
        );
        let body = if self.anthropic {
            json!({
                "type": "error",
                "error": {
                    "type": anthropic_error_type(status),
                    "message": message,
                    "number": descriptor.number,
                },
                "request_id": request_id,
            })
        } else {
            json!({
                "error": {
                    "message": message,
                    "type": openai_error_type(status),
                    "param": null,
                    "code": descriptor.code,
                    "number": descriptor.number,
                },
                "request_id": request_id,
            })
        };
        let mut response = (status, Json(body)).into_response();
        if let Ok(value) = descriptor.number.to_string().parse() {
            response.headers_mut().insert("X-Aster-Error-Number", value);
        }
        response.headers_mut().insert(
            axum::http::header::CACHE_CONTROL,
            HeaderValue::from_static("no-store"),
        );
        if let Some(request_id) = request_id
            && let Ok(value) = HeaderValue::from_str(&request_id)
        {
            response.headers_mut().insert("X-Aster-Request-ID", value);
        }
        response
    }
}

