#[derive(Clone, Debug, Serialize)]
struct AsterctlArtifactView {
    id: String,
    version: String,
    os: &'static str,
    arch: &'static str,
    display_name: &'static str,
    file_name: String,
    size_bytes: u64,
    sha256: String,
    recommended: bool,
    published_at: String,
    download_url: String,
}

struct InstalledAsterctlArtifact {
    view: AsterctlArtifactView,
    file: File,
}

fn load_installed_asterctl_artifact(
    layout: &InstallLayout,
    trusted_keys: &TrustedReleaseKeys,
) -> Result<Option<InstalledAsterctlArtifact>, ControlError> {
    let current = layout.current();
    if !current.exists() {
        return Ok(None);
    }
    let release_root = current
        .canonicalize()
        .map_err(|_| ControlError::DataIntegrityInvalid)?;
    let releases_root = layout
        .releases()
        .canonicalize()
        .map_err(|_| ControlError::DataIntegrityInvalid)?;
    if !release_root.starts_with(&releases_root) {
        return Err(ControlError::DataIntegrityInvalid);
    }
    load_asterctl_from_release_root(&release_root, trusted_keys)
}

fn load_asterctl_from_release_root(
    release_root: &Path,
    trusted_keys: &TrustedReleaseKeys,
) -> Result<Option<InstalledAsterctlArtifact>, ControlError> {
    const ASTERCTL_RELATIVE_PATH: &str = "client-tools/asterctl/windows-x86_64/asterctl.exe";
    const MAX_ASTERCTL_BYTES: u64 = 64 * 1024 * 1024;

    let manifest = std::fs::read(release_root.join(RELEASE_MANIFEST_FILE))
        .map_err(|_| ControlError::DataIntegrityInvalid)?;
    let release =
        verify_release(&manifest, trusted_keys).map_err(|_| ControlError::DataIntegrityInvalid)?;
    let Some(expected) = release
        .claims()
        .files
        .iter()
        .find(|file| file.path == ASTERCTL_RELATIVE_PATH)
    else {
        return Ok(None);
    };
    if expected.size == 0 || expected.size > MAX_ASTERCTL_BYTES {
        return Err(ControlError::DataIntegrityInvalid);
    }
    let path = release_root.join(ASTERCTL_RELATIVE_PATH);
    let metadata =
        std::fs::symlink_metadata(&path).map_err(|_| ControlError::DataIntegrityInvalid)?;
    if !metadata.is_file() || metadata.file_type().is_symlink() || metadata.len() != expected.size {
        return Err(ControlError::DataIntegrityInvalid);
    }
    let mut file = File::open(&path).map_err(|_| ControlError::DataIntegrityInvalid)?;
    let mut hasher = Sha256::new();
    let mut bytes_read = 0_u64;
    let mut buffer = [0_u8; 64 * 1024];
    let mut first_chunk = true;
    loop {
        let count = file
            .read(&mut buffer)
            .map_err(|_| ControlError::DataIntegrityInvalid)?;
        if count == 0 {
            break;
        }
        if first_chunk {
            if count < 2 || buffer[..2] != *b"MZ" {
                return Err(ControlError::DataIntegrityInvalid);
            }
            first_chunk = false;
        }
        bytes_read = bytes_read
            .checked_add(count as u64)
            .ok_or(ControlError::DataIntegrityInvalid)?;
        if bytes_read > MAX_ASTERCTL_BYTES {
            return Err(ControlError::DataIntegrityInvalid);
        }
        hasher.update(&buffer[..count]);
    }
    if bytes_read != expected.size || hex_encode(&hasher.finalize()) != expected.sha256 {
        return Err(ControlError::DataIntegrityInvalid);
    }
    file.rewind()
        .map_err(|_| ControlError::DataIntegrityInvalid)?;
    let version = release.claims().version.clone();
    let id = format!("asterctl-{version}-windows-x86_64");
    Ok(Some(InstalledAsterctlArtifact {
        view: AsterctlArtifactView {
            download_url: format!("/api/member/asterctl/artifacts/{id}/download"),
            id,
            version: version.clone(),
            os: "windows",
            arch: "x86_64",
            display_name: "Windows x64",
            file_name: "asterctl.exe".to_owned(),
            size_bytes: expected.size,
            sha256: expected.sha256.clone(),
            recommended: true,
            published_at: release.claims().created_at.clone(),
        },
        file,
    }))
}

fn load_development_asterctl_artifact() -> Result<Option<InstalledAsterctlArtifact>, ControlError> {
    if !cfg!(debug_assertions) {
        return Ok(None);
    }
    let Some(path) = std::env::var_os("ASTER_DEV_ASTERCTL_WINDOWS_X64").map(PathBuf::from) else {
        return Ok(None);
    };
    const MAX_ASTERCTL_BYTES: u64 = 64 * 1024 * 1024;
    let metadata =
        std::fs::symlink_metadata(&path).map_err(|_| ControlError::DataIntegrityInvalid)?;
    if !metadata.is_file()
        || metadata.file_type().is_symlink()
        || metadata.len() == 0
        || metadata.len() > MAX_ASTERCTL_BYTES
    {
        return Err(ControlError::DataIntegrityInvalid);
    }
    let mut file = File::open(&path).map_err(|_| ControlError::DataIntegrityInvalid)?;
    let mut hasher = Sha256::new();
    let mut magic = [0_u8; 2];
    file.read_exact(&mut magic)
        .map_err(|_| ControlError::DataIntegrityInvalid)?;
    if magic != *b"MZ" {
        return Err(ControlError::DataIntegrityInvalid);
    }
    file.rewind()
        .map_err(|_| ControlError::DataIntegrityInvalid)?;
    let mut buffer = [0_u8; 64 * 1024];
    loop {
        let count = file
            .read(&mut buffer)
            .map_err(|_| ControlError::DataIntegrityInvalid)?;
        if count == 0 {
            break;
        }
        hasher.update(&buffer[..count]);
    }
    let sha256 = hex_encode(&hasher.finalize());
    file.rewind()
        .map_err(|_| ControlError::DataIntegrityInvalid)?;
    let version = env!("CARGO_PKG_VERSION").to_owned();
    let id = format!("asterctl-{version}-windows-x86_64");
    Ok(Some(InstalledAsterctlArtifact {
        view: AsterctlArtifactView {
            download_url: format!("/api/member/asterctl/artifacts/{id}/download"),
            id,
            version: version.clone(),
            os: "windows",
            arch: "x86_64",
            display_name: "Windows x64",
            file_name: "asterctl.exe".to_owned(),
            size_bytes: metadata.len(),
            sha256,
            recommended: true,
            published_at: "1970-01-01T00:00:00.000Z".to_owned(),
        },
        file,
    }))
}

