async fn update_admin_model(
    State(state): State<ControlState>,
    headers: HeaderMap,
    AxumPath(model_id): AxumPath<String>,
    request: Result<Json<UpdateModelRequest>, JsonRejection>,
) -> Result<Json<Value>, ControlError> {
    let admin = require_admin_ready(&state, &headers).await?;
    authorize_non_consuming_feature(&state, "gateway")?;
    if !valid_resource_identifier(&model_id, "model_") {
        return Err(ControlError::UpstreamModelInputInvalid);
    }
    let Json(request) = request.map_err(|_| ControlError::UpstreamModelInputInvalid)?;
    let storage = state.credential_storage()?;
    let mut updated = false;
    for _ in 0..AUDIT_APPEND_RETRIES {
        let (expected_audit_sequence, expected_audit_hmac, audit_event) = state
            .prepare_audit_event(
                Some(&admin),
                "model.update",
                "model",
                Some(&model_id),
                "succeeded",
            )
            .await?;
        match storage
            .update_model_enabled_and_audit(
                &model_id,
                request.enabled,
                expected_audit_sequence,
                &expected_audit_hmac,
                &audit_event,
            )
            .await?
        {
            AuditedMutationOutcome::Applied => {
                updated = true;
                break;
            }
            AuditedMutationOutcome::MutationConflict => {
                return Err(ControlError::UpstreamModelNotFound);
            }
            AuditedMutationOutcome::AuditConflict => continue,
        }
    }
    if !updated {
        return Err(ControlError::DataIntegrityInvalid);
    }
    state.invalidate_gateway_model_variants()?;
    Ok(Json(json!({
        "ok": true,
        "model_id": model_id,
        "enabled": request.enabled,
    })))
}

async fn admin_quota_requests(
    State(state): State<ControlState>,
    headers: HeaderMap,
    query: Result<Query<AdminQuotaRequestQuery>, QueryRejection>,
) -> Result<Json<Value>, ControlError> {
    require_admin_ready(&state, &headers).await?;
    authorize_retained_feature(&state, "member")?;
    let Query(query) = query.map_err(|_| ControlError::MemberQuotaRequestInvalid)?;
    let (limit, offset) = validated_page(query.limit, query.offset, 50, 200)
        .ok_or(ControlError::MemberQuotaRequestInvalid)?;
    if query
        .status
        .as_deref()
        .is_some_and(|status| !matches!(status, "pending" | "approved" | "rejected"))
        || query.keyword.as_ref().is_some_and(|value| {
            value.chars().count() > 160 || !valid_optional_human_text(value, 160)
        })
    {
        return Err(ControlError::MemberQuotaRequestInvalid);
    }
    let currency = quota_request_currency(&state).await?;
    let storage = state.credential_storage()?;
    let mut identities = HashMap::new();
    for identity in storage.list_member_identities().await? {
        verify_identity_integrity(state.auth_core()?, &identity)?;
        identities.insert(identity.id.clone(), identity);
    }
    let mut reviewer_emails: HashMap<String, String> = HashMap::new();
    let mut items = Vec::new();
    for request in storage
        .list_quota_requests(None, query.status.as_deref())
        .await?
    {
        verify_quota_request_integrity(state.auth_core()?, &request)?;
        let member = identities
            .get(&request.identity_id)
            .ok_or(ControlError::DataIntegrityInvalid)?;
        let reviewer_email = if let Some(reviewer_id) = request.reviewed_by.as_deref() {
            if let Some(email) = reviewer_emails.get(reviewer_id) {
                Some(email.clone())
            } else {
                let reviewer = storage
                    .identity_by_id(reviewer_id)
                    .await?
                    .ok_or(ControlError::DataIntegrityInvalid)?;
                verify_identity_integrity(state.auth_core()?, &reviewer)?;
                reviewer_emails.insert(reviewer_id.to_owned(), reviewer.email.clone());
                Some(reviewer.email)
            }
        } else {
            None
        };
        items.push(quota_request_view(
            request,
            Some(member),
            reviewer_email,
            currency,
        ));
    }
    let keyword = query
        .keyword
        .as_deref()
        .map(str::trim)
        .unwrap_or_default()
        .to_lowercase();
    if !keyword.is_empty() {
        items.retain(|item| {
            item.user_display_name
                .as_deref()
                .is_some_and(|value| value.to_lowercase().contains(&keyword))
                || item
                    .user_email
                    .as_deref()
                    .is_some_and(|value| value.to_lowercase().contains(&keyword))
                || item.reason.to_lowercase().contains(&keyword)
                || item.review_note.to_lowercase().contains(&keyword)
                || item
                    .reviewer_email
                    .as_deref()
                    .is_some_and(|value| value.to_lowercase().contains(&keyword))
        });
    }
    items.sort_by(|left, right| {
        right
            .created_at
            .cmp(&left.created_at)
            .then_with(|| right.id.cmp(&left.id))
    });
    let total = items.len();
    let items = items
        .into_iter()
        .skip(offset)
        .take(limit)
        .collect::<Vec<_>>();
    Ok(Json(json!({ "items": items, "total": total })))
}

async fn review_member_quota_request(
    State(state): State<ControlState>,
    headers: HeaderMap,
    AxumPath(request_id): AxumPath<String>,
    request: Result<Json<ReviewQuotaRequest>, JsonRejection>,
) -> Result<Json<Value>, ControlError> {
    let admin = require_admin_ready(&state, &headers).await?;
    authorize_non_consuming_feature(&state, "member")?;
    if !valid_resource_identifier(&request_id, "quota_request_") {
        return Err(ControlError::MemberQuotaRequestNotFound);
    }
    let Json(request) = request.map_err(|_| ControlError::MemberQuotaRequestInvalid)?;
    let review_note = request.review_note.trim();
    if !matches!(request.status.as_str(), "approved" | "rejected")
        || !valid_optional_human_text(review_note, 500)
    {
        return Err(ControlError::MemberQuotaRequestInvalid);
    }
    let quota_request = state
        .credential_storage()?
        .quota_request_by_id(&request_id)
        .await?
        .ok_or(ControlError::MemberQuotaRequestNotFound)?;
    state
        .review_quota_request_atomic(&quota_request, &request.status, review_note, &admin)
        .await?;
    Ok(Json(json!({
        "ok": true,
        "request_id": request_id,
        "status": request.status,
    })))
}

async fn admin_vouchers(
    State(state): State<ControlState>,
    headers: HeaderMap,
    query: Result<Query<AdminVoucherQuery>, QueryRejection>,
) -> Result<Json<Value>, ControlError> {
    require_admin_ready(&state, &headers).await?;
    authorize_retained_feature(&state, "member")?;
    let Query(query) = query.map_err(|_| ControlError::VoucherInvalid)?;
    let (limit, offset) =
        validated_page(query.limit, query.offset, 50, 200).ok_or(ControlError::VoucherInvalid)?;
    let keyword = query
        .keyword
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty());
    if keyword.is_some_and(|value| !valid_optional_human_text(value, 160))
        || query
            .status
            .as_deref()
            .is_some_and(|value| !matches!(value, "active" | "redeemed" | "expired"))
        || query
            .delivery
            .as_deref()
            .is_some_and(|value| !matches!(value, "public" | "assigned"))
        || query
            .validity
            .as_deref()
            .is_some_and(|value| !matches!(value, "permanent" | "scheduled"))
    {
        return Err(ControlError::VoucherInvalid);
    }
    let storage = state.credential_storage()?;
    let mut identities = HashMap::new();
    for identity in storage.list_member_identities().await? {
        verify_identity_integrity(state.auth_core()?, &identity)?;
        identities.insert(identity.id.clone(), identity);
    }
    let now = (state.now)();
    let mut items = Vec::new();
    for voucher in storage.list_vouchers().await? {
        verify_voucher_integrity(state.auth_core()?, &voucher)?;
        let deliveries = storage.voucher_deliveries(&voucher.id).await?;
        let redemptions = storage.voucher_redemptions(&voucher.id).await?;
        let delivered_to_emails = deliveries
            .iter()
            .filter_map(|delivery| identities.get(&delivery.identity_id))
            .map(|identity| identity.email.clone())
            .collect::<Vec<_>>()
            .join(", ");
        if deliveries
            .iter()
            .any(|delivery| !identities.contains_key(&delivery.identity_id))
            || redemptions
                .iter()
                .any(|redemption| !identities.contains_key(&redemption.identity_id))
        {
            return Err(ControlError::DataIntegrityInvalid);
        }
        let redeemed_by_emails = redemptions
            .iter()
            .filter_map(|redemption| identities.get(&redemption.identity_id))
            .map(|identity| identity.email.clone())
            .collect::<Vec<_>>()
            .join(", ");
        let last_redeemed_at = redemptions
            .iter()
            .map(|redemption| redemption.created_at.clone())
            .max();
        items.push(admin_voucher_view(
            voucher,
            deliveries.len(),
            delivered_to_emails,
            redeemed_by_emails,
            last_redeemed_at,
            now,
        )?);
    }
    let normalized_keyword = keyword.map(str::to_lowercase);
    items.retain(|item| {
        normalized_keyword.as_ref().is_none_or(|keyword| {
            item.name.to_lowercase().contains(keyword)
                || item.code_prefix.to_lowercase().contains(keyword)
                || item.delivered_to_emails.to_lowercase().contains(keyword)
                || item.redeemed_by_emails.to_lowercase().contains(keyword)
        }) && query
            .status
            .as_deref()
            .is_none_or(|status| item.status == status)
            && query
                .delivery
                .as_deref()
                .is_none_or(|delivery| match delivery {
                    "public" => item.delivery_count == 0,
                    "assigned" => item.delivery_count > 0,
                    _ => false,
                })
            && query
                .validity
                .as_deref()
                .is_none_or(|validity| match validity {
                    "permanent" => item.expires_at.is_none(),
                    "scheduled" => item.expires_at.is_some(),
                    _ => false,
                })
    });
    items.sort_by(|left, right| {
        right
            .created_at
            .cmp(&left.created_at)
            .then_with(|| right.id.cmp(&left.id))
    });
    let total = items.len();
    let items = items
        .into_iter()
        .skip(offset)
        .take(limit)
        .collect::<Vec<_>>();
    Ok(Json(json!({ "items": items, "total": total })))
}

async fn create_vouchers(
    State(state): State<ControlState>,
    headers: HeaderMap,
    request: Result<Json<CreateVouchersRequest>, JsonRejection>,
) -> Result<Response, ControlError> {
    let admin = require_admin_ready(&state, &headers).await?;
    authorize_non_consuming_feature(&state, "member")?;
    let Json(request) = request.map_err(|_| ControlError::VoucherInvalid)?;
    let name = request.name.trim();
    if !(1..=160).contains(&name.chars().count())
        || !valid_optional_human_text(name, 160)
        || !(1..=10_000_000_000).contains(&request.quota_tokens)
        || !(1..=1_000_000).contains(&request.max_redemptions)
        || request
            .valid_days
            .is_some_and(|days| !(1..=3650).contains(&days))
        || request.recipient_user_ids.len() > 500
    {
        return Err(ControlError::VoucherInvalid);
    }
    let recipient_ids = request
        .recipient_user_ids
        .iter()
        .cloned()
        .collect::<BTreeSet<_>>();
    if recipient_ids.len() != request.recipient_user_ids.len()
        || recipient_ids
            .iter()
            .any(|identity_id| !valid_resource_identifier(identity_id, "identity_"))
    {
        return Err(ControlError::VoucherInvalid);
    }
    let storage = state.credential_storage()?;
    let mut recipients = Vec::new();
    for identity_id in recipient_ids {
        let identity = storage
            .identity_by_id(&identity_id)
            .await?
            .filter(|identity| identity.role == "member" && identity.status == "active")
            .ok_or(ControlError::IdentityNotFound)?;
        verify_identity_integrity(state.auth_core()?, &identity)?;
        recipients.push(identity);
    }
    let now = (state.now)();
    let created_at = format_database_time(now).map_err(|_| ControlError::DataIntegrityInvalid)?;
    let expires_at = request
        .valid_days
        .map(|days| format_database_time(now + time::Duration::days(i64::from(days))))
        .transpose()
        .map_err(|_| ControlError::VoucherInvalid)?;
    let target_count = recipients.len().max(1);
    let mut records = Vec::with_capacity(target_count);
    let mut generated = Vec::with_capacity(target_count);
    for index in 0..target_count {
        let recipient = recipients.get(index);
        let code = format!("av_{}", random_url_secret(32)?);
        let mut voucher = VoucherRecord {
            id: random_identifier("voucher")?,
            code_hash: sha256_hex(code.as_bytes()),
            code_prefix: code.chars().take(12).collect(),
            name: name.to_owned(),
            quota_tokens: request.quota_tokens,
            status: "active".to_owned(),
            max_redemptions: if recipient.is_some() {
                1
            } else {
                request.max_redemptions
            },
            redeemed_count: 0,
            expires_at: expires_at.clone(),
            created_by: admin.id.clone(),
            revision: 0,
            integrity_hmac: String::new(),
            created_at: created_at.clone(),
        };
        voucher.integrity_hmac = voucher_integrity_hmac(state.auth_core()?, &voucher)?;
        let delivery = if let Some(identity) = recipient {
            Some(VoucherDeliveryRecord {
                id: random_identifier("voucher_delivery")?,
                voucher_id: voucher.id.clone(),
                identity_id: identity.id.clone(),
                status: "pending".to_owned(),
                delivered_at: created_at.clone(),
                redeemed_at: None,
            })
        } else {
            None
        };
        generated.push(GeneratedVoucherView {
            voucher: admin_voucher_view(
                voucher.clone(),
                usize::from(recipient.is_some()),
                recipient
                    .map(|identity| identity.email.clone())
                    .unwrap_or_default(),
                String::new(),
                None,
                now,
            )?,
            code,
            recipient: recipient.map(|identity| {
                json!({
                    "id": identity.id,
                    "email": identity.email,
                    "display_name": identity.display_name,
                })
            }),
        });
        records.push((voucher, delivery));
    }
    let target_ids = records
        .iter()
        .map(|(voucher, _)| voucher.id.clone())
        .collect::<Vec<_>>();
    let mut inserted = false;
    for _ in 0..AUDIT_APPEND_RETRIES {
        let (expected_audit_sequence, expected_audit_hmac, audit_events) = state
            .prepare_audit_events_for_targets(&admin, "voucher.create", "voucher", &target_ids)
            .await?;
        match storage
            .insert_vouchers_and_audit(
                &records,
                expected_audit_sequence,
                &expected_audit_hmac,
                &audit_events,
            )
            .await?
        {
            AuditedMutationOutcome::Applied => {
                inserted = true;
                break;
            }
            AuditedMutationOutcome::AuditConflict => continue,
            AuditedMutationOutcome::MutationConflict => {
                return Err(ControlError::DataIntegrityInvalid);
            }
        }
    }
    if !inserted {
        return Err(ControlError::DataIntegrityInvalid);
    }
    Ok((StatusCode::CREATED, Json(json!({ "vouchers": generated }))).into_response())
}

async fn delete_voucher(
    State(state): State<ControlState>,
    headers: HeaderMap,
    AxumPath(voucher_id): AxumPath<String>,
) -> Result<Json<Value>, ControlError> {
    let admin = require_admin_ready(&state, &headers).await?;
    authorize_non_consuming_feature(&state, "member")?;
    if !valid_resource_identifier(&voucher_id, "voucher_") {
        return Err(ControlError::VoucherNotFound);
    }
    let storage = state.credential_storage()?;
    let existing = storage
        .list_vouchers()
        .await?
        .into_iter()
        .find(|voucher| voucher.id == voucher_id)
        .ok_or(ControlError::VoucherNotFound)?;
    verify_voucher_integrity(state.auth_core()?, &existing)?;
    if existing.redeemed_count != 0 {
        return Err(ControlError::VoucherDeleteConflict);
    }
    let mut deleted = false;
    for _ in 0..AUDIT_APPEND_RETRIES {
        let (expected_audit_sequence, expected_audit_hmac, audit_event) = state
            .prepare_audit_event(
                Some(&admin),
                "voucher.delete",
                "voucher",
                Some(&voucher_id),
                "succeeded",
            )
            .await?;
        match storage
            .delete_unused_voucher_and_audit(
                &voucher_id,
                expected_audit_sequence,
                &expected_audit_hmac,
                &audit_event,
            )
            .await?
        {
            AuditedMutationOutcome::Applied => {
                deleted = true;
                break;
            }
            AuditedMutationOutcome::MutationConflict => {
                return Err(ControlError::VoucherDeleteConflict);
            }
            AuditedMutationOutcome::AuditConflict => continue,
        }
    }
    if !deleted {
        return Err(ControlError::DataIntegrityInvalid);
    }
    Ok(Json(json!({ "ok": true, "voucher_id": voucher_id })))
}

async fn list_members(
    State(state): State<ControlState>,
    headers: HeaderMap,
) -> Result<Json<Value>, ControlError> {
    require_admin_ready(&state, &headers).await?;
    authorize_retained_feature(&state, "member")?;
    let configuration = state.billing_configuration().await?;
    let money_currency = match configuration.settlement_currency {
        BillingSettlementCurrency::Cny => BillingCurrency::Cny,
        BillingSettlementCurrency::Usd => BillingCurrency::Usd,
    };
    let currency_code = match money_currency {
        BillingCurrency::Cny => "CNY",
        BillingCurrency::Usd => "USD",
    };
    let storage = state.credential_storage()?;
    let mut items = Vec::new();
    for identity in storage.list_member_identities().await? {
        verify_identity_integrity(state.auth_core()?, &identity)?;
        let quota = state.verified_quota_snapshot(&identity.id).await?;
        let money = storage.money_state_snapshot(&identity.id).await?;
        if let Some(snapshot) = money.as_ref() {
            state.verify_money_state_snapshot(snapshot)?;
            if snapshot.balance.currency != currency_code {
                return Err(ControlError::DataIntegrityInvalid);
            }
        }
        items.push(AdminMemberView {
            id: identity.id,
            email: identity.email,
            display_name: identity.display_name,
            status: identity.status,
            password_change_required: identity.password_change_required,
            money_currency: Some(currency_code.to_owned()),
            money_balance: Some(money_decimal(
                money_currency,
                money
                    .as_ref()
                    .map_or(0, |snapshot| snapshot.balance.balance_nanos),
            )),
            money_credited: Some(money_decimal(
                money_currency,
                money
                    .as_ref()
                    .map_or(0, |snapshot| snapshot.balance.credited_nanos),
            )),
            money_debited: Some(money_decimal(
                money_currency,
                money
                    .as_ref()
                    .map_or(0, |snapshot| snapshot.balance.debited_nanos),
            )),
            balance_tokens: quota.balance.balance_tokens,
            granted_tokens: quota.balance.granted_tokens,
            used_tokens: quota.balance.consumed_tokens,
            request_count: quota.balance.request_count,
            raw_tokens: quota.balance.raw_tokens,
            billed_tokens: quota.balance.billed_tokens,
            uncached_input_tokens: quota.balance.uncached_input,
            cached_input_tokens: quota.balance.cached_input,
            cache_write_tokens: quota.balance.cache_write,
            output_tokens: quota.balance.output_tokens,
            created_at: identity.created_at,
        });
    }
    Ok(Json(json!({ "items": items })))
}

