async fn create_members_batch(
    State(state): State<ControlState>,
    headers: HeaderMap,
    request: Result<Json<CreateMembersBatchRequest>, JsonRejection>,
) -> Result<Response, ControlError> {
    let admin = require_admin_ready(&state, &headers).await?;
    let Json(request) = request.map_err(|_| ControlError::IdentityInvalid)?;
    if request.emails.is_empty()
        || request.emails.len() > 50
        || !matches!(request.password_mode.as_str(), "random" | "fixed")
        || (request.password_mode == "fixed"
            && !(12..=1024).contains(&request.fixed_password.len()))
    {
        return Err(ControlError::IdentityInvalid);
    }
    let mut inputs = Vec::with_capacity(request.emails.len());
    let mut presented_passwords = Vec::with_capacity(request.emails.len());
    for raw_email in request.emails {
        let email = normalize_email(&raw_email).ok_or(ControlError::IdentityInvalid)?;
        let display_name: String = email
            .split_once('@')
            .map(|(local, _)| local)
            .unwrap_or_default()
            .chars()
            .take(160)
            .collect();
        if display_name.is_empty() {
            return Err(ControlError::IdentityInvalid);
        }
        let password = if request.password_mode == "random" {
            random_url_secret(32)?
        } else {
            request.fixed_password.clone()
        };
        inputs.push(MemberCreationInput {
            email,
            display_name,
            password: Zeroizing::new(password.as_bytes().to_vec()),
        });
        presented_passwords.push(password);
    }
    let created = state.create_member_identities(&admin, inputs).await?;
    let items: Vec<_> = created
        .into_iter()
        .zip(presented_passwords)
        .map(|(identity, password)| {
            json!({
                "id": identity.id,
                "email": identity.email,
                "display_name": identity.display_name,
                "password": password,
            })
        })
        .collect();
    Ok((StatusCode::CREATED, Json(json!({ "items": items }))).into_response())
}

