async fn grant_member_quota(
    State(state): State<ControlState>,
    headers: HeaderMap,
    AxumPath(identity_id): AxumPath<String>,
    request: Result<Json<GrantMemberQuotaRequest>, JsonRejection>,
) -> Result<Json<Value>, ControlError> {
    let admin = require_admin_ready(&state, &headers).await?;
    authorize_non_consuming_feature(&state, "member")?;
    let Json(request) = request.map_err(|_| ControlError::QuotaAdjustmentInvalid)?;
    let reason = request.reason.trim();
    if !valid_resource_identifier(&identity_id, "identity_")
        || !valid_client_request_id(&request.request_id)
        || !(0..=10_000_000_000).contains(&request.amount_tokens)
        || (request.amount_tokens == 0 && request.image_adjustments.is_empty())
        || request.image_adjustments.len() > 100
        || request.image_adjustments.iter().any(|item| {
            !valid_resource_identifier(&item.model_id, "model_")
                || item.delta_images == 0
                || !(-1_000_000..=1_000_000).contains(&item.delta_images)
                || item.expected_revision < 0
        })
        || !(2..=200).contains(&reason.chars().count())
        || reason.chars().any(char::is_control)
    {
        return Err(ControlError::QuotaAdjustmentInvalid);
    }
    let member = state
        .credential_storage()?
        .identity_by_id(&identity_id)
        .await?
        .filter(|identity| identity.role == "member" && identity.status != "deleted")
        .ok_or(ControlError::IdentityNotFound)?;
    verify_identity_integrity(state.auth_core()?, &member)?;
    let (balance_tokens, granted_tokens) = state
        .grant_member_quotas_with_audit(&admin, &member.id, &request)
        .await?;
    Ok(Json(json!({
        "ok": true,
        "identity_id": member.id,
        "balance_tokens": balance_tokens,
        "granted_tokens": granted_tokens,
    })))
}

async fn list_member_quota_adjustments(
    State(state): State<ControlState>,
    headers: HeaderMap,
    AxumPath(identity_id): AxumPath<String>,
) -> Result<Json<Value>, ControlError> {
    require_admin_ready(&state, &headers).await?;
    authorize_retained_feature(&state, "member")?;
    if !valid_resource_identifier(&identity_id, "identity_") {
        return Err(ControlError::IdentityNotFound);
    }
    let member = state
        .credential_storage()?
        .identity_by_id(&identity_id)
        .await?
        .filter(|identity| identity.role == "member" && identity.status != "deleted")
        .ok_or(ControlError::IdentityNotFound)?;
    verify_identity_integrity(state.auth_core()?, &member)?;
    let snapshot = state.verified_quota_snapshot(&member.id).await?;
    let mut items = Vec::new();
    for entry in snapshot
        .ledger_entries
        .iter()
        .rev()
        .filter(|entry| entry.kind == "grant")
    {
        let Some(reference) = entry.reference_id.strip_prefix("admin_grant:") else {
            continue;
        };
        let Some((admin_id, _request_id)) = reference.split_once(':') else {
            return Err(ControlError::DataIntegrityInvalid);
        };
        let admin_email = state
            .credential_storage()?
            .identity_by_id(admin_id)
            .await?
            .map(|identity| identity.email)
            .unwrap_or_else(|| "deleted-admin".to_owned());
        items.push(json!({
            "id": entry.id,
            "amount_tokens": entry.amount_tokens,
            "reason": entry.description,
            "created_at": entry.created_at,
            "admin_email": admin_email,
        }));
    }
    items.extend(state.admin_image_adjustment_history(&member.id).await?);
    items.sort_by(|left, right| {
        right["created_at"]
            .as_str()
            .cmp(&left["created_at"].as_str())
    });
    Ok(Json(json!({ "items": items })))
}

async fn create_runner_enrollment(
    State(state): State<ControlState>,
    headers: HeaderMap,
    request: Result<Json<CreateRunnerEnrollmentRequest>, JsonRejection>,
) -> Result<Response, ControlError> {
    let admin = require_admin_ready(&state, &headers).await?;
    authorize_non_consuming_feature(&state, "runner")?;
    let Json(request) = request.map_err(|_| ControlError::RunnerInputInvalid)?;
    let runner_name = request.name.trim();
    if !valid_runner_name(runner_name) {
        return Err(ControlError::RunnerInputInvalid);
    }

    let now = (state.now)();
    let created_at = format_database_time(now).map_err(|_| ControlError::TimeConversionFailed)?;
    let expires_at = format_database_time(now + RUNNER_ENROLLMENT_TTL)
        .map_err(|_| ControlError::TimeConversionFailed)?;
    let enrollment_id = random_identifier("enrollment")?;
    let token = format!("aren_{}", random_url_secret(32)?);
    let token_prefix = token.chars().take(16).collect::<String>();
    let enrollment = RunnerEnrollmentRecord {
        id: enrollment_id.clone(),
        token_hash: sha256_hex(token.as_bytes()),
        token_prefix,
        runner_name: runner_name.to_owned(),
        status: "pending".to_owned(),
        expires_at: expires_at.clone(),
        created_by: admin.id.clone(),
        created_at,
    };
    let storage = state.credential_storage()?;
    let mut inserted = false;
    for _ in 0..AUDIT_APPEND_RETRIES {
        let (expected_audit_sequence, expected_audit_hmac, audit_event) = state
            .prepare_audit_event(
                Some(&admin),
                "runner_enrollment.create",
                "runner_enrollment",
                Some(&enrollment_id),
                "succeeded",
            )
            .await?;
        match storage
            .insert_runner_enrollment_and_audit(
                enrollment.clone(),
                expected_audit_sequence,
                &expected_audit_hmac,
                &audit_event,
            )
            .await?
        {
            AuditedMutationOutcome::Applied => {
                inserted = true;
                break;
            }
            AuditedMutationOutcome::AuditConflict => continue,
            AuditedMutationOutcome::MutationConflict => {
                return Err(ControlError::DataIntegrityInvalid);
            }
        }
    }
    if !inserted {
        return Err(ControlError::DataIntegrityInvalid);
    }

    Ok((
        StatusCode::CREATED,
        Json(CreateRunnerEnrollmentResponse {
            enrollment_id,
            runner_name: runner_name.to_owned(),
            token,
            expires_at,
            notice: "注册 Token 仅返回一次，24 小时内有效；Token 创建不占用 Runner 额度，注册成功后才占用。",
        }),
    )
        .into_response())
}

async fn enroll_runner(
    State(state): State<ControlState>,
    request: Result<Json<EnrollRunnerRequest>, JsonRejection>,
) -> Result<Response, ControlError> {
    let license = authorize_non_consuming_feature(&state, "runner")?;
    let runner_limit = resource_quota_limit(license.as_ref().quota(QuotaId::Runners));
    let Json(request) = request.map_err(|_| ControlError::RunnerInputInvalid)?;
    let token = Zeroizing::new(request.token);
    if !valid_runner_secret(token.as_str(), "aren_", 40, 160) {
        return Err(ControlError::RunnerEnrollmentInvalid);
    }
    if request.protocol_version != RUNNER_PROTOCOL_VERSION {
        return Err(ControlError::RunnerProtocol);
    }
    if !valid_runner_version(&request.version)
        || !valid_runner_platform_value(&request.platform)
        || !valid_runner_platform_value(&request.architecture)
        || !(1..=100_000).contains(&request.max_inflight)
    {
        return Err(ControlError::RunnerInputInvalid);
    }
    let task_keys = state
        .task_issuer
        .as_ref()
        .ok_or(ControlError::DataIntegrityInvalid)?
        .public_keys()?;

    let now =
        format_database_time((state.now)()).map_err(|_| ControlError::TimeConversionFailed)?;
    let runner_id = random_identifier("runner")?;
    let credential = format!("arr_{}", random_url_secret(48)?);
    let registration = RunnerRegistrationRecord {
        id: runner_id.clone(),
        credential_hash: sha256_hex(credential.as_bytes()),
        version: request.version,
        protocol_version: request.protocol_version,
        platform: request.platform,
        architecture: request.architecture,
        max_inflight: request.max_inflight,
        created_at: now.clone(),
    };
    let token_hash = sha256_hex(token.as_bytes());
    let storage = state.credential_storage()?;
    let mut registered = false;
    for _ in 0..AUDIT_APPEND_RETRIES {
        let (expected_audit_sequence, expected_audit_hmac, audit_event) = state
            .prepare_audit_event(
                None,
                "runner.register",
                "runner",
                Some(&runner_id),
                "succeeded",
            )
            .await?;
        let _license_commit = state.guard_licensed_mutation(Some(&license), "runner")?;
        let mutation_storage = storage.clone();
        let mutation_input = RunnerEnrollmentConsumeInput {
            token_hash: token_hash.clone(),
            now: now.clone(),
            registration: registration.clone(),
            runner_limit,
            quota: state.verified_runner_quota().await?,
        };
        let registration_lease = runner_upgrade::registration_lease(&state)?;
        match finish_licensed_mutation(
            Arc::clone(&state.mutation_tasks),
            _license_commit,
            async move {
                let _registration_lease = registration_lease;
                mutation_storage
                    .consume_runner_enrollment_and_audit(
                        mutation_input,
                        expected_audit_sequence,
                        &expected_audit_hmac,
                        &audit_event,
                    )
                    .await
            },
        )
        .await?
        {
            MutationWithAuditOutcome::Mutation(RunnerEnrollmentConsumeOutcome::Registered) => {
                registered = true;
                break;
            }
            MutationWithAuditOutcome::Mutation(RunnerEnrollmentConsumeOutcome::LimitReached) => {
                return Err(ControlError::RunnerLimitReached);
            }
            MutationWithAuditOutcome::Mutation(RunnerEnrollmentConsumeOutcome::Invalid) => {
                return Err(ControlError::RunnerEnrollmentInvalid);
            }
            MutationWithAuditOutcome::AuditConflict
            | MutationWithAuditOutcome::Mutation(RunnerEnrollmentConsumeOutcome::QuotaChanged) => {
                continue;
            }
        }
    }
    if !registered {
        return Err(ControlError::DataIntegrityInvalid);
    }

    Ok((
        StatusCode::CREATED,
        Json(EnrollRunnerResponse {
            runner_id,
            credential,
            protocol_version: RUNNER_PROTOCOL_VERSION,
            task_keys,
            notice: "Runner 凭据仅返回一次，请写入 Runner 的受限配置。",
        }),
    )
        .into_response())
}

