async fn update_runner(
    State(state): State<ControlState>,
    headers: HeaderMap,
    AxumPath(runner_id): AxumPath<String>,
    request: Result<Json<UpdateRunnerRequest>, JsonRejection>,
) -> Result<Json<Value>, ControlError> {
    let admin = require_admin_ready(&state, &headers).await?;
    if !valid_resource_identifier(&runner_id, "runner_") {
        return Err(ControlError::RunnerNotFound);
    }
    let Json(request) = request.map_err(|_| ControlError::RunnerInputInvalid)?;
    let license = if request.enabled {
        authorize_non_consuming_feature(&state, "runner")?
    } else {
        authorize_retained_feature(&state, "runner")?
    };
    let updated_at =
        format_database_time((state.now)()).map_err(|_| ControlError::TimeConversionFailed)?;
    let mut updated = false;
    for _ in 0..AUDIT_APPEND_RETRIES {
        let (expected_audit_sequence, expected_audit_hmac, audit_event) = state
            .prepare_audit_event(
                Some(&admin),
                "runner.status.update",
                "runner",
                Some(&runner_id),
                "succeeded",
            )
            .await?;
        validate_admin_actor(&state, &admin).await?;
        let guard = if request.enabled {
            state.guard_licensed_mutation(Some(&license), "runner")?
        } else {
            state.guard_retained_mutation(&license, "runner")?
        };
        let mutation = {
            let storage = state.credential_storage()?.clone();
            let runner_id = runner_id.clone();
            let updated_at = updated_at.clone();
            async move {
                storage
                    .update_runner_enabled_and_audit(
                        &runner_id,
                        request.enabled,
                        &updated_at,
                        expected_audit_sequence,
                        &expected_audit_hmac,
                        &audit_event,
                    )
                    .await
            }
        };
        match finish_licensed_mutation(Arc::clone(&state.mutation_tasks), guard, mutation).await? {
            AuditedMutationOutcome::Applied => {
                updated = true;
                break;
            }
            AuditedMutationOutcome::MutationConflict => {
                return Err(ControlError::RunnerNotFound);
            }
            AuditedMutationOutcome::AuditConflict => continue,
        }
    }
    if !updated {
        return Err(ControlError::DataIntegrityInvalid);
    }
    if !request.enabled {
        state.runner_hub.disconnect(&runner_id).await;
    }
    Ok(Json(json!({
        "ok": true,
        "runner_id": runner_id,
        "enabled": request.enabled,
    })))
}

async fn test_runner(
    State(state): State<ControlState>,
    headers: HeaderMap,
    AxumPath(runner_id): AxumPath<String>,
) -> Result<Json<Value>, ControlError> {
    require_admin_ready(&state, &headers).await?;
    authorize_non_consuming_feature(&state, "runner")?;
    if !valid_resource_identifier(&runner_id, "runner_") {
        return Err(ControlError::RunnerNotFound);
    }
    let runner = state
        .credential_storage()?
        .list_runners()
        .await?
        .into_iter()
        .find(|runner| runner.id == runner_id)
        .ok_or(ControlError::RunnerNotFound)?;
    if !runner.enabled {
        return Err(ControlError::Routing(RoutingError::NoRunnerReady));
    }
    state.runner_hub.ping(&runner.id).await?;
    Ok(Json(json!({ "ok": true, "runner_id": runner.id })))
}

async fn delete_runner(
    State(state): State<ControlState>,
    headers: HeaderMap,
    AxumPath(runner_id): AxumPath<String>,
) -> Result<Json<Value>, ControlError> {
    let admin = require_admin_ready(&state, &headers).await?;
    let license = authorize_retained_feature(&state, "runner")?;
    if !valid_resource_identifier(&runner_id, "runner_") {
        return Err(ControlError::RunnerNotFound);
    }
    let registration_lease = runner_upgrade::registration_lease(&state)?;
    let registration_lease = Arc::new(registration_lease);
    let mut deleted = false;
    for _ in 0..AUDIT_APPEND_RETRIES {
        let (expected_audit_sequence, expected_audit_hmac, audit_event) = state
            .prepare_audit_event(
                Some(&admin),
                "runner.delete",
                "runner",
                Some(&runner_id),
                "succeeded",
            )
            .await?;
        validate_admin_actor(&state, &admin).await?;
        let quota = state.verified_runner_quota().await?;
        if quota.is_upgrade_member(&runner_id) {
            return Err(ControlError::MaintenanceBusy);
        }
        let change = quota
            .delete_runner(&runner_id)
            .map_err(|_| ControlError::RunnerNotFound)?;
        let next_state = state.sign_runner_quota_change(&change)?;
        let guard = state.guard_retained_mutation(&license, "runner")?;
        let mutation = {
            let storage = state.credential_storage()?.clone();
            let registration_lease = Arc::clone(&registration_lease);
            async move {
                let _registration_lease = registration_lease;
                storage
                    .apply_runner_quota_change(
                        runner_quota::QuotaMutation {
                            change,
                            next_state,
                            enrollment: None,
                            registration: None,
                        },
                        None,
                        (expected_audit_sequence, expected_audit_hmac, audit_event),
                    )
                    .await
            }
        };
        match finish_licensed_mutation(Arc::clone(&state.mutation_tasks), guard, mutation).await? {
            aster_storage::runner_quota::RunnerQuotaWriteOutcome::Applied => {
                deleted = true;
                break;
            }
            aster_storage::runner_quota::RunnerQuotaWriteOutcome::Conflict => {
                return Err(ControlError::RunnerNotFound);
            }
            aster_storage::runner_quota::RunnerQuotaWriteOutcome::QuotaChanged
            | aster_storage::runner_quota::RunnerQuotaWriteOutcome::AuditConflict => continue,
            aster_storage::runner_quota::RunnerQuotaWriteOutcome::LimitReached => {
                return Err(ControlError::DataIntegrityInvalid);
            }
        }
    }
    if !deleted {
        return Err(ControlError::DataIntegrityInvalid);
    }
    state.runner_hub.disconnect(&runner_id).await;
    Ok(Json(json!({ "ok": true, "runner_id": runner_id })))
}

async fn list_upstream_accounts(
    State(state): State<ControlState>,
    headers: HeaderMap,
) -> Result<Json<UpstreamAccountListResponse>, ControlError> {
    require_admin_ready(&state, &headers).await?;
    authorize_retained_feature(&state, "gateway")?;
    let storage = state.credential_storage()?;
    let mut items = Vec::new();
    for account in storage.list_upstream_accounts().await? {
        let credentials = storage
            .credential_instances_for_account(&account.id)
            .await?;
        let active_credential_count = credentials
            .iter()
            .filter(|credential| credential.status == "active")
            .count();
        items.push(upstream_account_view(
            account,
            credentials.len(),
            active_credential_count,
        ));
    }
    Ok(Json(UpstreamAccountListResponse { items }))
}

async fn update_upstream_account(
    State(state): State<ControlState>,
    headers: HeaderMap,
    AxumPath(account_id): AxumPath<String>,
    request: Result<Json<UpdateUpstreamAccountRequest>, JsonRejection>,
) -> Result<Json<Value>, ControlError> {
    let admin = require_admin_ready(&state, &headers).await?;
    if !valid_resource_identifier(&account_id, "account_") {
        return Err(ControlError::UpstreamAccountNotFound);
    }
    let Json(request) = request.map_err(|_| ControlError::UpstreamAccountInputInvalid)?;
    let license = if request.enabled {
        authorize_non_consuming_feature(&state, "gateway")?
    } else {
        authorize_retained_feature(&state, "gateway")?
    };
    let status = if request.enabled {
        "active"
    } else {
        "disabled"
    };
    let updated_at =
        format_database_time((state.now)()).map_err(|_| ControlError::TimeConversionFailed)?;
    let mut updated = false;
    for _ in 0..AUDIT_APPEND_RETRIES {
        let (expected_audit_sequence, expected_audit_hmac, audit_event) = state
            .prepare_audit_event(
                Some(&admin),
                "upstream_account.status.update",
                "upstream_account",
                Some(&account_id),
                "succeeded",
            )
            .await?;
        validate_admin_actor(&state, &admin).await?;
        let guard = if request.enabled {
            state.guard_licensed_mutation(Some(&license), "gateway")?
        } else {
            state.guard_retained_mutation(&license, "gateway")?
        };
        let mutation = {
            let storage = state.credential_storage()?.clone();
            let account_id = account_id.clone();
            let updated_at = updated_at.clone();
            async move {
                storage
                    .update_upstream_account_status_and_audit(
                        &account_id,
                        status,
                        &updated_at,
                        expected_audit_sequence,
                        &expected_audit_hmac,
                        &audit_event,
                    )
                    .await
            }
        };
        match finish_licensed_mutation(Arc::clone(&state.mutation_tasks), guard, mutation).await? {
            AuditedMutationOutcome::Applied => {
                updated = true;
                break;
            }
            AuditedMutationOutcome::MutationConflict => {
                return Err(ControlError::UpstreamAccountNotFound);
            }
            AuditedMutationOutcome::AuditConflict => continue,
        }
    }
    if !updated {
        return Err(ControlError::DataIntegrityInvalid);
    }
    Ok(Json(json!({
        "ok": true,
        "account_id": account_id,
        "status": status,
    })))
}

async fn delete_upstream_account(
    State(state): State<ControlState>,
    headers: HeaderMap,
    AxumPath(account_id): AxumPath<String>,
) -> Result<Json<Value>, ControlError> {
    let admin = require_admin_ready(&state, &headers).await?;
    let license = authorize_retained_feature(&state, "gateway")?;
    if !valid_resource_identifier(&account_id, "account_") {
        return Err(ControlError::UpstreamAccountNotFound);
    }
    let storage = state.credential_storage()?;
    if storage.upstream_account_by_id(&account_id).await?.is_none() {
        return Err(ControlError::UpstreamAccountNotFound);
    }
    let deleted_credentials = storage
        .credential_instances_for_account(&account_id)
        .await?
        .len();
    let mut deleted = false;
    for _ in 0..AUDIT_APPEND_RETRIES {
        let (expected_audit_sequence, expected_audit_hmac, audit_event) = state
            .prepare_audit_event(
                Some(&admin),
                "upstream_account.delete",
                "upstream_account",
                Some(&account_id),
                "succeeded",
            )
            .await?;
        validate_admin_actor(&state, &admin).await?;
        let guard = state.guard_retained_mutation(&license, "gateway")?;
        let mutation = {
            let storage = state.credential_storage()?.clone();
            let account_id = account_id.clone();
            async move {
                storage
                    .delete_upstream_account_and_audit(
                        &account_id,
                        expected_audit_sequence,
                        &expected_audit_hmac,
                        &audit_event,
                    )
                    .await
            }
        };
        match finish_licensed_mutation(Arc::clone(&state.mutation_tasks), guard, mutation).await? {
            AuditedMutationOutcome::Applied => {
                deleted = true;
                break;
            }
            AuditedMutationOutcome::MutationConflict => {
                return Err(ControlError::UpstreamAccountNotFound);
            }
            AuditedMutationOutcome::AuditConflict => continue,
        }
    }
    if !deleted {
        return Err(ControlError::DataIntegrityInvalid);
    }
    Ok(Json(json!({
        "ok": true,
        "account_id": account_id,
        "deleted_credentials": deleted_credentials,
    })))
}

