async fn refresh_upstream_credential(
    State(state): State<ControlState>,
    headers: HeaderMap,
    AxumPath((account_id, credential_id)): AxumPath<(String, String)>,
) -> Result<Json<Value>, ControlError> {
    let admin = require_admin_ready(&state, &headers).await?;
    authorize_non_consuming_operation(&state, BusinessOperationId::UpstreamRefresh)?;
    if !valid_resource_identifier(&account_id, "account_")
        || !valid_resource_identifier(&credential_id, "credential_")
    {
        return Err(ControlError::CredentialNotFound);
    }
    let credential = state
        .credential_storage()?
        .credential_instance_by_id(&credential_id)
        .await?
        .filter(|credential| credential.account_id == account_id)
        .ok_or(ControlError::CredentialNotFound)?;
    CredentialBroker::new(&state)
        .refresh_with_actor(&credential.id, &admin)
        .await?;
    let refreshed = state
        .credential_storage()?
        .credential_instance_by_id(&credential.id)
        .await?
        .ok_or(ControlError::CredentialNotFound)?;
    Ok(Json(json!({
        "ok": true,
        "account_id": account_id,
        "credential": upstream_credential_view(refreshed),
    })))
}

