async fn admin_plugin_candidate(
    State(state): State<ControlState>,
    headers: HeaderMap,
    body: Bytes,
) -> Result<(StatusCode, Json<Value>), ControlError> {
    let actor = require_admin_ready(&state, &headers).await?;
    authorize_non_consuming_features(&state, ["gateway"])?;
    let outcome = state.submit_plugin_bundle(&actor, &body).await?;
    let (status, digest, reason) = match outcome {
        aster_plugin_core::CandidateOutcome::Activated { digest } => (StatusCode::OK, digest, None),
        aster_plugin_core::CandidateOutcome::Rejected { digest, reason } => {
            (StatusCode::UNPROCESSABLE_ENTITY, digest, Some(reason))
        }
        aster_plugin_core::CandidateOutcome::Absent
        | aster_plugin_core::CandidateOutcome::Unchanged => {
            return Err(ControlError::DataIntegrityInvalid);
        }
    };
    let audit_outcome = if reason.is_some() {
        "rejected"
    } else {
        "succeeded"
    };
    if let Err(error) = state
        .append_audit_event(
            Some(&actor),
            "plugin.submit",
            "plugin_bundle",
            Some(&digest),
            audit_outcome,
        )
        .await
    {
        warn!(?error, %digest, "plugin submission audit failed");
    }
    Ok((
        status,
        Json(json!({
            "digest": digest,
            "status": audit_outcome,
            "reason": reason,
        })),
    ))
}

async fn admin_plugin_switch_version(
    State(state): State<ControlState>,
    headers: HeaderMap,
    request: Result<Json<plugins::PluginVersionSwitchRequest>, JsonRejection>,
) -> Result<(StatusCode, Json<Value>), ControlError> {
    let actor = require_admin_ready(&state, &headers).await?;
    authorize_non_consuming_features(&state, ["gateway"])?;
    let Json(request) = request.map_err(|_| ControlError::MaintenanceInvalid)?;
    let outcome = state.switch_plugin_version(&actor, request).await?;
    let (status, digest, reason) = match outcome {
        aster_plugin_core::CandidateOutcome::Activated { digest } => (StatusCode::OK, digest, None),
        aster_plugin_core::CandidateOutcome::Rejected { digest, reason } => {
            let status = if reason == "activation revision changed" {
                StatusCode::CONFLICT
            } else {
                StatusCode::UNPROCESSABLE_ENTITY
            };
            (status, digest, Some(reason))
        }
        _ => return Err(ControlError::DataIntegrityInvalid),
    };
    if let Err(error) = state
        .append_audit_event(
            Some(&actor),
            "plugin.version_switch",
            "plugin_bundle",
            Some(&digest),
            if reason.is_some() {
                "rejected"
            } else {
                "succeeded"
            },
        )
        .await
    {
        warn!(?error, %digest, "plugin version switch audit failed");
    }
    Ok((status, Json(json!({ "digest": digest, "reason": reason }))))
}

