async fn start_upstream_enrollment(
    State(state): State<ControlState>,
    headers: HeaderMap,
    AxumPath(provider_id): AxumPath<String>,
) -> Result<Json<EnrollmentTransition>, ControlError> {
    let admin = require_admin_ready(&state, &headers).await?;
    authorize_non_consuming_operation(&state, BusinessOperationId::UpstreamAuthorize)?;
    if provider_id != "openai"
        || providers::ProviderRegistry::production()
            .get(&provider_id)
            .is_none()
    {
        return Err(ControlError::UpstreamAccountInputInvalid);
    }
    let session_id = random_identifier("enrollment")?;
    let oauth_state = Zeroizing::new(random_url_secret(32)?);
    let verifier = Zeroizing::new(random_url_secret(48)?);
    let challenge = encode_base64url(&Sha256::digest(verifier.as_bytes()));
    let now = (state.now)();
    let expires_at = now + OAUTH_SESSION_TTL;
    {
        let mut sessions = state.oauth_sessions.lock().await;
        sessions.retain(|_, session| session.expires_at > now);
        sessions.insert(
            session_id.clone(),
            OAuthLoginSession {
                state_hash: sha256_hex(oauth_state.as_bytes()),
                verifier,
                admin_identity_id: admin.id,
                expires_at,
                exchanging: false,
            },
        );
    }
    let mut authorization_url = url::Url::parse(OPENAI_AUTHORIZE_ENDPOINT)
        .map_err(|_| ControlError::OAuthSessionInvalid)?;
    authorization_url
        .query_pairs_mut()
        .append_pair("response_type", "code")
        .append_pair("client_id", OPENAI_OAUTH_CLIENT_ID)
        .append_pair("redirect_uri", OPENAI_OAUTH_REDIRECT_URI)
        .append_pair("scope", OPENAI_OAUTH_SCOPE)
        .append_pair("code_challenge", &challenge)
        .append_pair("code_challenge_method", "S256")
        .append_pair("id_token_add_organizations", "true")
        .append_pair("codex_cli_simplified_flow", "true")
        .append_pair("state", oauth_state.as_str())
        .append_pair("originator", "codex_cli_rs");
    Ok(Json(EnrollmentTransition::ActionRequired {
        enrollment_id: session_id,
        provider_id,
        action: EnrollmentActionRequired::OpenUrl {
            url: authorization_url.into(),
            expires_at: format_database_time(expires_at)
                .map_err(|_| ControlError::OAuthSessionInvalid)?,
            callback_action: "submit_callback".to_owned(),
        },
    }))
}

async fn advance_upstream_enrollment(
    State(state): State<ControlState>,
    headers: HeaderMap,
    AxumPath(enrollment_id): AxumPath<String>,
    request: Result<Json<EnrollmentActionRequest>, JsonRejection>,
) -> Result<Response, ControlError> {
    let admin = require_admin_ready(&state, &headers).await?;
    let license =
        authorize_non_consuming_operation(&state, BusinessOperationId::UpstreamAuthorize)?;
    let account_limit = resource_quota_limit(license.as_ref().quota(QuotaId::UpstreamAccounts));
    let Json(request) = request.map_err(|_| ControlError::OAuthSessionInvalid)?;
    if !valid_resource_identifier(&enrollment_id, "enrollment_") {
        return Err(ControlError::OAuthSessionInvalid);
    }
    let EnrollmentActionRequest::SubmitCallback { callback_url } = request;
    let callback = parse_openai_oauth_callback(&callback_url)?;
    let code = Zeroizing::new(callback.code);
    let callback_state_hash = sha256_hex(callback.state.as_bytes());
    let now = (state.now)();
    let (verifier, session_expires_at) = {
        let mut sessions = state.oauth_sessions.lock().await;
        sessions.retain(|_, session| session.expires_at > now);
        let session = sessions
            .get_mut(&enrollment_id)
            .ok_or(ControlError::OAuthSessionInvalid)?;
        if session.exchanging {
            return Err(ControlError::OAuthSessionBusy);
        }
        if !constant_time_string_eq(&session.state_hash, &callback_state_hash) {
            return Err(ControlError::OAuthSessionInvalid);
        }
        if session.admin_identity_id != admin.id {
            return Err(ControlError::OAuthSessionInvalid);
        }
        session.exchanging = true;
        (session.verifier.clone(), session.expires_at)
    };

    let form = Zeroizing::new(format!(
        "grant_type=authorization_code&client_id={}&code={}&redirect_uri={}&code_verifier={}",
        form_component(OPENAI_OAUTH_CLIENT_ID),
        form_component(code.as_str()),
        form_component(OPENAI_OAUTH_REDIRECT_URI),
        form_component(verifier.as_str()),
    ));
    let exchange = state
        .execute_runner_http_request_with_command(
            None,
            &RunnerTaskBinding::enrollment("openai", "auth.openai.com"),
            RunnerTaskAuthorization::AuthorizeCredential {
                actor: &admin,
                enrollment_id: &enrollment_id,
                expires_at: session_expires_at,
            },
            &UpstreamHttpRequest {
                method: "POST".to_owned(),
                url: OPENAI_TOKEN_ENDPOINT.to_owned(),
                headers: vec![
                    UpstreamRequestHeader {
                        name: "content-type".to_owned(),
                        value: "application/x-www-form-urlencoded".to_owned(),
                    },
                    UpstreamRequestHeader {
                        name: "accept".to_owned(),
                        value: "application/json".to_owned(),
                    },
                    UpstreamRequestHeader {
                        name: "user-agent".to_owned(),
                        value: "aster-runner-oauth/0.1".to_owned(),
                    },
                ],
                body_base64url: encode_base64url(form.as_bytes()),
            },
        )
        .await;
    let exchange = match exchange {
        Ok(exchange) => exchange,
        Err(error)
            if matches!(&error, ControlError::Routing(RoutingError::NoRunnerReady))
                || error.is_license_failure()
                || error.is_identity_failure() =>
        {
            release_oauth_session_exchange(&state, &enrollment_id).await;
            return Err(error);
        }
        Err(_) => {
            release_oauth_session_exchange(&state, &enrollment_id).await;
            return Err(ControlError::OAuthExchangeFailed);
        }
    };
    if !(200..300).contains(&exchange.status) {
        release_oauth_session_exchange(&state, &enrollment_id).await;
        return Err(ControlError::OAuthExchangeFailed);
    }
    state.oauth_sessions.lock().await.remove(&enrollment_id);
    let response_body = Zeroizing::new(exchange.body);
    let tokens: OpenAiTokenResponse = decode_exact_json(response_body.as_slice())
        .map_err(|_| ControlError::OAuthExchangeFailed)?;
    if tokens.access_token.is_empty()
        || tokens.refresh_token.is_empty()
        || tokens.access_token.len() > 64 * 1024
        || tokens.refresh_token.len() > 64 * 1024
        || tokens.id_token.len() > 64 * 1024
    {
        return Err(ControlError::OAuthExchangeFailed);
    }
    let metadata = token_pair_metadata(&tokens.id_token, &tokens.access_token);
    if metadata.account_id.is_empty() || metadata.account_id.len() > 256 {
        return Err(ControlError::OAuthExchangeFailed);
    }
    let ttl_seconds = if tokens.expires_in > 0 {
        tokens.expires_in.min(31_536_000)
    } else {
        3600
    };
    let expires_at = format_database_time((state.now)() + time::Duration::seconds(ttl_seconds))
        .map_err(|_| ControlError::OAuthExchangeFailed)?;
    let upstream_email = metadata.email.trim();
    let email = if !upstream_email.is_empty()
        && upstream_email.len() <= 320
        && !upstream_email.chars().any(char::is_control)
    {
        upstream_email.to_owned()
    } else {
        format!("{}@openai.local", metadata.account_id)
    };
    let upstream_plan = metadata.plan.trim();
    let plan = if upstream_plan.len() <= 64 && !upstream_plan.chars().any(char::is_control) {
        upstream_plan.to_owned()
    } else {
        String::new()
    };
    let storage = state.credential_storage()?;
    let account_id = match storage
        .upstream_account_by_provider_subject("openai", &metadata.account_id)
        .await?
    {
        Some(account) => account.id,
        None => {
            let id = random_identifier("account")?;
            let created_at = format_database_time((state.now)())
                .map_err(|_| ControlError::TimeConversionFailed)?;
            let account = UpstreamAccountRecord {
                id: id.clone(),
                provider: "openai".to_owned(),
                subject_id: metadata.account_id.clone(),
                email: email.clone(),
                plan: String::new(),
                status: "active".to_owned(),
                last_success_runner_id: None,
                last_verified_at: None,
                created_at: created_at.clone(),
                updated_at: created_at,
            };
            let mut resolved_id = None;
            for _ in 0..AUDIT_APPEND_RETRIES {
                let (expected_audit_sequence, expected_audit_hmac, audit_event) = state
                    .prepare_audit_event(
                        Some(&admin),
                        "upstream_account.create",
                        "upstream_account",
                        Some(&id),
                        "succeeded",
                    )
                    .await?;
                validate_admin_actor(&state, &admin).await?;
                let _license_commit = state.guard_licensed_mutation(Some(&license), "gateway")?;
                let mutation_storage = storage.clone();
                let mutation_account = account.clone();
                match finish_licensed_mutation(
                    Arc::clone(&state.mutation_tasks),
                    _license_commit,
                    async move {
                        mutation_storage
                            .insert_upstream_account_and_audit(
                                &mutation_account,
                                account_limit,
                                expected_audit_sequence,
                                &expected_audit_hmac,
                                &audit_event,
                            )
                            .await
                    },
                )
                .await?
                {
                    MutationWithAuditOutcome::Mutation(ResourceCreateOutcome::Created) => {
                        resolved_id = Some(id.clone());
                        break;
                    }
                    MutationWithAuditOutcome::Mutation(ResourceCreateOutcome::Conflict) => {
                        resolved_id = storage
                            .upstream_account_by_provider_subject("openai", &metadata.account_id)
                            .await?
                            .map(|concurrent| concurrent.id);
                        break;
                    }
                    MutationWithAuditOutcome::Mutation(ResourceCreateOutcome::LimitReached) => {
                        return Err(ControlError::UpstreamAccountLimitReached);
                    }
                    MutationWithAuditOutcome::AuditConflict => continue,
                }
            }
            resolved_id.ok_or(ControlError::DataIntegrityInvalid)?
        }
    };
    let verified_at =
        format_database_time((state.now)()).map_err(|_| ControlError::TimeConversionFailed)?;
    let credential = OpenAiCredentialPayload {
        schema: OPENAI_CREDENTIAL_SCHEMA.to_owned(),
        provider: "openai".to_owned(),
        access_token: tokens.access_token.clone(),
        refresh_token: tokens.refresh_token.clone(),
        id_token: tokens.id_token.clone(),
        expires_at: expires_at.clone(),
        account_id: metadata.account_id,
        email: email.clone(),
        plan: plan.clone(),
    };
    let encoded = Zeroizing::new(
        serde_json::to_vec(&credential).map_err(|_| ControlError::OAuthExchangeFailed)?,
    );
    let credential_instance_id = state
        .create_credential_instance_with_account_metadata_and_audit(
            &admin,
            &account_id,
            &email,
            &plan,
            &verified_at,
            credential.refresh_token.as_bytes(),
            encoded.as_slice(),
            &expires_at,
        )
        .await?;
    Ok((
        StatusCode::CREATED,
        Json(EnrollmentTransition::Completed {
            enrollment_id,
            provider_id: "openai".to_owned(),
            account_id,
            credential_instance_id,
            email,
            plan,
        }),
    )
        .into_response())
}

async fn cancel_upstream_enrollment(
    State(state): State<ControlState>,
    headers: HeaderMap,
    AxumPath(enrollment_id): AxumPath<String>,
) -> Result<Json<Value>, ControlError> {
    let admin = require_admin_ready(&state, &headers).await?;
    let license = authorize_retained_feature(&state, "gateway")?;
    if !valid_resource_identifier(&enrollment_id, "enrollment_") {
        return Err(ControlError::OAuthSessionInvalid);
    }
    validate_admin_actor(&state, &admin).await?;
    let mut sessions = state.oauth_sessions.lock().await;
    let _guard = state.guard_retained_mutation(&license, "gateway")?;
    let removable = sessions
        .get(&enrollment_id)
        .is_some_and(|session| session.admin_identity_id == admin.id && !session.exchanging);
    if !removable || sessions.remove(&enrollment_id).is_none() {
        return Err(ControlError::OAuthSessionInvalid);
    }
    Ok(Json(json!({"ok": true, "enrollment_id": enrollment_id})))
}

async fn release_oauth_session_exchange(state: &ControlState, session_id: &str) {
    let now = (state.now)();
    let mut sessions = state.oauth_sessions.lock().await;
    if let Some(session) = sessions.get_mut(session_id) {
        if session.expires_at > now {
            session.exchanging = false;
        } else {
            sessions.remove(session_id);
        }
    }
}

struct OpenAiOAuthCallback {
    code: String,
    state: String,
}

fn parse_openai_oauth_callback(value: &str) -> Result<OpenAiOAuthCallback, ControlError> {
    let callback = url::Url::parse(value.trim()).map_err(|_| ControlError::OAuthSessionInvalid)?;
    if callback.scheme() != "http"
        || callback.host_str() != Some("localhost")
        || callback.port() != Some(1455)
        || callback.path() != "/auth/callback"
        || !callback.username().is_empty()
        || callback.password().is_some()
        || callback.fragment().is_some()
    {
        return Err(ControlError::OAuthSessionInvalid);
    }
    let mut code = None;
    let mut state = None;
    let mut oauth_error = None;
    for (name, value) in callback.query_pairs() {
        let target = match name.as_ref() {
            "code" => &mut code,
            "state" => &mut state,
            "error" => &mut oauth_error,
            _ => continue,
        };
        if target.replace(value.into_owned()).is_some() {
            return Err(ControlError::OAuthSessionInvalid);
        }
    }
    if oauth_error.is_some() {
        return Err(ControlError::OAuthExchangeFailed);
    }
    let code = code.ok_or(ControlError::OAuthSessionInvalid)?;
    let state = state.ok_or(ControlError::OAuthSessionInvalid)?;
    if code.is_empty() || state.is_empty() || code.len() > 4096 || state.len() > 256 {
        return Err(ControlError::OAuthSessionInvalid);
    }
    Ok(OpenAiOAuthCallback { code, state })
}

