async fn member_vouchers(
    State(state): State<ControlState>,
    headers: HeaderMap,
    query: Result<Query<MemberVoucherQuery>, QueryRejection>,
) -> Result<Json<Value>, ControlError> {
    let identity = require_member_retained_ready(&state, &headers).await?;
    let Query(query) = query.map_err(|_| ControlError::VoucherInvalid)?;
    let (limit, offset) =
        validated_page(query.limit, query.offset, 20, 100).ok_or(ControlError::VoucherInvalid)?;
    if query.availability.as_deref().is_some_and(|availability| {
        !matches!(
            availability,
            "available" | "redeemed" | "expired" | "unavailable"
        )
    }) || query
        .keyword
        .as_ref()
        .is_some_and(|value| value.chars().count() > 160 || !valid_optional_human_text(value, 160))
    {
        return Err(ControlError::VoucherInvalid);
    }
    let now = (state.now)();
    let mut items = state
        .credential_storage()?
        .list_voucher_deliveries_for_identity(&identity.id)
        .await?
        .into_iter()
        .map(|(delivery, voucher)| {
            verify_voucher_integrity(state.auth_core()?, &voucher)?;
            let expired = voucher
                .expires_at
                .as_deref()
                .map(|expires_at| {
                    OffsetDateTime::parse(expires_at, &Rfc3339)
                        .map(|expires_at| expires_at <= now)
                        .map_err(|_| ControlError::DataIntegrityInvalid)
                })
                .transpose()?
                .unwrap_or(false);
            let availability = if delivery.status == "redeemed" {
                "redeemed"
            } else if expired {
                "expired"
            } else if delivery.status == "pending"
                && voucher.status == "active"
                && voucher.redeemed_count < voucher.max_redemptions
            {
                "available"
            } else {
                "unavailable"
            };
            Ok(MemberVoucherDeliveryView {
                delivery_id: delivery.id,
                delivery_status: delivery.status,
                delivered_at: delivery.delivered_at,
                redeemed_at: delivery.redeemed_at,
                id: voucher.id,
                name: voucher.name,
                code_prefix: voucher.code_prefix,
                quota_tokens: voucher.quota_tokens,
                expires_at: voucher.expires_at,
                availability,
            })
        })
        .collect::<Result<Vec<_>, ControlError>>()?;
    items.sort_by(|left, right| {
        right
            .delivered_at
            .cmp(&left.delivered_at)
            .then_with(|| right.delivery_id.cmp(&left.delivery_id))
    });
    let available_count = items
        .iter()
        .filter(|item| item.availability == "available")
        .count();
    let keyword = query
        .keyword
        .as_deref()
        .map(str::trim)
        .unwrap_or_default()
        .to_lowercase();
    items.retain(|item| {
        query
            .availability
            .as_deref()
            .is_none_or(|availability| item.availability == availability)
            && (keyword.is_empty()
                || item.name.to_lowercase().contains(&keyword)
                || item.code_prefix.to_lowercase().contains(&keyword))
    });
    let total = items.len();
    let items = items
        .into_iter()
        .skip(offset)
        .take(limit)
        .collect::<Vec<_>>();
    Ok(Json(json!({
        "items": items,
        "total": total,
        "available_count": available_count,
    })))
}

async fn redeem_member_voucher(
    State(state): State<ControlState>,
    headers: HeaderMap,
    request: Result<Json<RedeemVoucherRequest>, JsonRejection>,
) -> Result<Json<Value>, ControlError> {
    let identity = require_member_ready(&state, &headers).await?;
    let Json(request) = request.map_err(|_| ControlError::VoucherInvalid)?;
    if request.code.is_some() == request.delivery_id.is_some() {
        return Err(ControlError::VoucherInvalid);
    }
    let code = request.code.map(Zeroizing::new);
    let code_hash = if let Some(code) = code.as_deref() {
        if !valid_runner_secret(code, "av_", 40, 160) {
            return Err(ControlError::VoucherInvalid);
        }
        Some(sha256_hex(code.as_bytes()))
    } else {
        None
    };
    if request
        .delivery_id
        .as_deref()
        .is_some_and(|delivery_id| !valid_resource_identifier(delivery_id, "voucher_delivery_"))
    {
        return Err(ControlError::VoucherInvalid);
    }
    state
        .redeem_voucher_atomic(
            &identity,
            code_hash.as_deref(),
            request.delivery_id.as_deref(),
        )
        .await?;
    let balance = state.verified_quota_snapshot(&identity.id).await?.balance;
    Ok(Json(json!({
        "ok": true,
        "balance_tokens": balance.balance_tokens,
    })))
}

async fn member_docs(
    State(state): State<ControlState>,
    headers: HeaderMap,
    query: Result<Query<MemberDocsQuery>, QueryRejection>,
) -> Result<Json<Value>, ControlError> {
    let member = require_member_retained_ready(&state, &headers).await?;
    let permitted = state.permitted_model_ids(&member.id).await?;
    let Query(query) = query.map_err(|_| ControlError::MemberUsageInvalid)?;
    let locale = query.locale.as_deref().unwrap_or("zh-CN");
    if !matches!(locale, "zh-CN" | "en-US") {
        return Err(ControlError::MemberUsageInvalid);
    }
    let request_origin = request_origin(&headers)?;
    let configuration = state.runtime_configuration().await?;
    let origin = if configuration.public_api_base_url.is_empty() {
        request_origin
    } else {
        configuration.public_api_base_url
    };
    let openai_base_url = format!("{origin}/v1");
    let codex_config = render_aster_provider_snippet(&openai_base_url)
        .map_err(|_| ControlError::PlatformSettingsInvalid)?;
    let enabled_models = state
        .credential_storage()?
        .enabled_models()
        .await?
        .into_iter()
        .filter(|model| permitted.as_ref().is_none_or(|ids| ids.contains(&model.id)))
        .collect::<Vec<_>>();
    let image_models = enabled_models
        .iter()
        .filter(|model| gateway::capabilities::is_image_model(&model.public_name))
        .map(|model| model.public_name.clone())
        .collect::<Vec<_>>();
    let default_image_model = image_models.first().cloned();
    let models = enabled_models
        .into_iter()
        .map(|model| {
            json!({
                "id": model.public_name,
                "display_name": model.display_name,
            })
        })
        .collect::<Vec<_>>();
    let english = locale == "en-US";
    let names = [
        "Responses",
        "Chat Completions",
        "Anthropic Messages",
        if english {
            "Image Generation"
        } else {
            "图片生成"
        },
        if english {
            "Image Editing"
        } else {
            "图片编辑"
        },
    ];
    let image_docs = gateway::images::documentation(english);
    Ok(Json(json!({
        "public_api_base_url": origin,
        "base_urls": {
            "openai": openai_base_url,
            "anthropic": origin,
        },
        "codex_config": codex_config,
        "usage_multiplier": configuration.usage_multiplier_micros as f64 / 1_000_000.0,
        "claude": {
            "compatibility": {
                "source": CLAUDE_COMPATIBILITY_SOURCE,
                "checked_at": CLAUDE_COMPATIBILITY_CHECKED_AT,
                "minimum_version": CLAUDE_MINIMUM_VERSION,
            },
        },
        "models": models,
        "image_models": image_models,
        "default_image_model": default_image_model,
        "image_parameters": image_docs["image_parameters"],
        "image_edit_parameters": image_docs["image_edit_parameters"],
        "image_size": image_docs["image_size"],
        "image_output": image_docs["image_output"],
        "protocols": [
            { "id": "responses", "name": names[0], "path": "/v1/responses" },
            { "id": "chat", "name": names[1], "path": "/v1/chat/completions" },
            { "id": "anthropic", "name": names[2], "path": "/v1/messages" },
            { "id": "images", "name": names[3], "path": "/v1/images/generations" },
            { "id": "image_edits", "name": names[4], "path": "/v1/images/edits" },
        ],
    })))
}

async fn member_claude_cli_settings(
    State(state): State<ControlState>,
    headers: HeaderMap,
    query: Result<Query<ClaudeCliSettingsQuery>, QueryRejection>,
) -> Result<Json<Value>, ControlError> {
    let member = require_member_retained_ready(&state, &headers).await?;
    let permitted = state.permitted_model_ids(&member.id).await?;
    let Query(query) = query.map_err(|_| ControlError::MemberUsageInvalid)?;
    let version = parse_claude_version(&query.version).ok_or(ControlError::MemberUsageInvalid)?;
    if !supports_claude_version(&version) {
        return Ok(Json(json!({
            "claude_version": version.to_string(),
            "minimum_version": CLAUDE_MINIMUM_VERSION,
            "supported": false,
            "settings": null,
        })));
    }

    let request_origin = request_origin(&headers)?;
    let configuration = state.runtime_configuration().await?;
    let origin = if configuration.public_api_base_url.is_empty() {
        request_origin
    } else {
        configuration.public_api_base_url
    };
    let models = state
        .credential_storage()?
        .enabled_models()
        .await?
        .into_iter()
        .filter(|model| permitted.as_ref().is_none_or(|ids| ids.contains(&model.id)))
        .collect::<Vec<_>>();
    let mappings = suggested_claude_mappings(models.iter().map(|model| model.public_name.as_str()));
    if !mappings.is_complete() {
        return Err(ControlError::ModelNotFound);
    }
    let settings = render_claude_project_settings(
        origin.trim_end_matches('/'),
        "ask_your_key",
        &mappings,
        &version,
    )
    .and_then(|bytes| {
        String::from_utf8(bytes).map_err(|error| format!("Claude settings are not UTF-8: {error}"))
    })
    .map_err(|_| ControlError::DataIntegrityInvalid)?;

    Ok(Json(json!({
        "claude_version": version.to_string(),
        "minimum_version": CLAUDE_MINIMUM_VERSION,
        "supported": true,
        "settings": settings,
    })))
}

