async fn download_member_asterctl_artifact(
    State(state): State<ControlState>,
    headers: HeaderMap,
    AxumPath(artifact_id): AxumPath<String>,
) -> Result<Response, ControlError> {
    require_member_retained_ready(&state, &headers).await?;
    let Some(artifact) = state.installed_asterctl_artifact()? else {
        return Ok(StatusCode::NOT_FOUND.into_response());
    };
    if artifact_id != artifact.view.id {
        return Ok(StatusCode::NOT_FOUND.into_response());
    }
    let disposition = HeaderValue::from_str(&format!(
        "attachment; filename=\"{}\"",
        artifact.view.file_name
    ))
    .map_err(|_| ControlError::DataIntegrityInvalid)?;
    let etag = HeaderValue::from_str(&format!("\"sha256:{}\"", artifact.view.sha256))
        .map_err(|_| ControlError::DataIntegrityInvalid)?;
    let content_length = HeaderValue::from_str(&artifact.view.size_bytes.to_string())
        .map_err(|_| ControlError::DataIntegrityInvalid)?;
    let file = tokio::fs::File::from_std(artifact.file);
    let stream = futures_util::stream::try_unfold(file, |mut file| async move {
        let mut buffer = vec![0_u8; 64 * 1024];
        let count = tokio::io::AsyncReadExt::read(&mut file, &mut buffer).await?;
        if count == 0 {
            Ok(None)
        } else {
            buffer.truncate(count);
            Ok::<_, std::io::Error>(Some((Bytes::from(buffer), file)))
        }
    });
    let mut response = Body::from_stream(stream).into_response();
    response.headers_mut().insert(
        axum::http::header::CONTENT_TYPE,
        HeaderValue::from_static("application/octet-stream"),
    );
    response
        .headers_mut()
        .insert(axum::http::header::CONTENT_DISPOSITION, disposition);
    response
        .headers_mut()
        .insert(axum::http::header::CONTENT_LENGTH, content_length);
    response
        .headers_mut()
        .insert(axum::http::header::ETAG, etag);
    response.headers_mut().insert(
        axum::http::header::CACHE_CONTROL,
        HeaderValue::from_static("private, no-cache"),
    );
    Ok(response)
}

async fn member_usage_summary(
    State(state): State<ControlState>,
    headers: HeaderMap,
    query: Result<Query<MemberUsageQuery>, QueryRejection>,
) -> Result<Json<Value>, ControlError> {
    let identity = require_member_retained_ready(&state, &headers).await?;
    let Query(query) = query.map_err(|_| ControlError::MemberUsageInvalid)?;
    let snapshot = state.verified_quota_snapshot(&identity.id).await?;
    let now = (state.now)();
    let utc_offset = usage_utc_offset(query.utc_offset_minutes)?;
    let automatic_granularity = match query.granularity.as_deref() {
        None => false,
        Some("auto") => true,
        Some(_) => return Err(ControlError::MemberUsageInvalid),
    };
    let (start, end) = usage_summary_time_window(
        query.period.as_deref(),
        query.from.as_deref(),
        query.to.as_deref(),
        now,
        utc_offset,
        automatic_granularity,
    )?;
    let mut entries = filter_member_usage_entries_in_window(
        &snapshot.ledger_entries,
        start,
        end,
        query.api_key_id.as_deref(),
        false,
    )?;
    entries.sort_by(|left, right| {
        left.created_at
            .cmp(&right.created_at)
            .then_with(|| left.id.cmp(&right.id))
    });
    let granularity = if automatic_granularity {
        resolve_usage_granularity(
            query.period.as_deref(),
            query.from.as_deref(),
            query.to.as_deref(),
            start,
            end,
            &entries,
            now,
        )?
    } else {
        UsageGranularity::Day
    };
    let trend_range = usage_trend_range(granularity, start, end, &entries, now, utc_offset)?;

    let mut summary = UsageMetricsView::default();
    let mut models = BTreeMap::<String, UsageMetricsView>::new();
    let mut processing_tiers = BTreeMap::<String, UsageMetricsView>::new();
    let mut reasoning_efforts = BTreeMap::<String, UsageMetricsView>::new();
    let mut trend = BTreeMap::<String, UsageMetricsView>::new();
    let mut model_trend = BTreeMap::<(String, String), UsageMetricsView>::new();
    for entry in &entries {
        add_usage_metrics(&mut summary, entry);
        add_usage_metrics(models.entry(entry.model.clone()).or_default(), entry);
        add_usage_metrics(
            processing_tiers
                .entry(usage_dimension_value(entry.processing_tier.as_deref()).to_owned())
                .or_default(),
            entry,
        );
        add_usage_metrics(
            reasoning_efforts
                .entry(usage_dimension_value(entry.reasoning_effort.as_deref()).to_owned())
                .or_default(),
            entry,
        );
        let date = usage_bucket_label(entry, granularity, utc_offset)?;
        add_usage_metrics(trend.entry(date.clone()).or_default(), entry);
        add_usage_metrics(
            model_trend.entry((date, entry.model.clone())).or_default(),
            entry,
        );
    }
    let models = models
        .into_iter()
        .map(|(model, metrics)| UsageModelView { model, metrics })
        .collect::<Vec<_>>();
    let processing_tiers = usage_dimension_views(processing_tiers);
    let reasoning_efforts = usage_dimension_views(reasoning_efforts);
    let trend = fill_usage_trend(trend, granularity, trend_range)?;
    let observed_until = end.map_or(now, |end| end.min(now));
    let model_trend = model_trend
        .into_iter()
        .map(|((date, model), metrics)| UsageModelTrendView {
            date,
            model,
            metrics,
        })
        .collect::<Vec<_>>();
    let recent = entries
        .iter()
        .rev()
        .take(10)
        .map(|entry| ledger_entry_view(entry))
        .collect::<Vec<_>>();
    Ok(Json(json!({
        "period": query.period.unwrap_or_else(|| "7d".to_owned()),
        "granularity": granularity.as_str(),
        "bucket_minutes": granularity.bucket_minutes(),
        "bucket_seconds": granularity.bucket_seconds(),
        "range_start": format_usage_range_boundary(trend_range.map(|range| range.0))?,
        "range_end": format_usage_range_boundary(trend_range.map(|range| range.1))?,
        "observed_until": format_usage_range_boundary(Some(observed_until))?,
        "utc_offset_minutes": utc_offset.whole_minutes(),
        "summary": summary,
        "models": models,
        "processing_tiers": processing_tiers,
        "reasoning_efforts": reasoning_efforts,
        "trend": trend,
        "model_trend": model_trend,
        "recent": recent,
    })))
}

async fn member_usage_logs(
    State(state): State<ControlState>,
    headers: HeaderMap,
    query: Result<Query<MemberUsageLogsQuery>, QueryRejection>,
) -> Result<Json<Value>, ControlError> {
    let identity = require_member_retained_ready(&state, &headers).await?;
    let Query(query) = query.map_err(|_| ControlError::MemberUsageInvalid)?;
    let limit = query.limit.unwrap_or(100);
    let offset = query.offset.unwrap_or(0);
    if !(1..=200).contains(&limit)
        || offset > 1_000_000
        || query.model.as_ref().is_some_and(|value| value.len() > 160)
        || query
            .protocol
            .as_ref()
            .is_some_and(|value| value.len() > 64)
        || query
            .processing_tier
            .as_deref()
            .is_some_and(|value| value != "model_default" && !valid_processing_tier(value))
        || query
            .reasoning_effort
            .as_deref()
            .is_some_and(|value| value != "model_default" && !valid_reasoning_effort(value))
    {
        return Err(ControlError::MemberUsageInvalid);
    }
    let snapshot = state.verified_quota_snapshot(&identity.id).await?;
    let mut entries = filter_member_usage_entries(
        &snapshot.ledger_entries,
        query.period.as_deref(),
        query.from.as_deref(),
        query.to.as_deref(),
        query.api_key_id.as_deref(),
        (state.now)(),
    )?;
    let models = entries
        .iter()
        .map(|entry| {
            entry
                .requested_model
                .as_deref()
                .unwrap_or(&entry.model)
                .to_owned()
        })
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let protocols = entries
        .iter()
        .map(|entry| entry.protocol.clone())
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let processing_tiers = entries
        .iter()
        .map(|entry| usage_dimension_value(entry.processing_tier.as_deref()).to_owned())
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let reasoning_efforts = entries
        .iter()
        .map(|entry| usage_dimension_value(entry.reasoning_effort.as_deref()).to_owned())
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    entries.retain(|entry| {
        query
            .model
            .as_deref()
            .is_none_or(|model| entry.requested_model.as_deref().unwrap_or(&entry.model) == model)
            && query
                .protocol
                .as_deref()
                .is_none_or(|protocol| entry.protocol == protocol)
            && usage_dimension_matches(
                entry.processing_tier.as_deref(),
                query.processing_tier.as_deref(),
            )
            && usage_dimension_matches(
                entry.reasoning_effort.as_deref(),
                query.reasoning_effort.as_deref(),
            )
    });
    let mut entries = logical_usage_entries(entries.into_iter().cloned())?;
    entries.sort_by(|left, right| {
        right
            .ledger
            .created_at
            .cmp(&left.ledger.created_at)
            .then_with(|| right.ledger.id.cmp(&left.ledger.id))
    });
    let runner_names = state
        .credential_storage()?
        .list_runners()
        .await?
        .into_iter()
        .map(|runner| (runner.id, runner.name))
        .collect::<HashMap<_, _>>();
    let total = entries.len();
    let items = entries
        .into_iter()
        .skip(offset)
        .take(limit)
        .map(|entry| MemberConsumptionEntryView {
            runner_name: runner_name_for_ledger_entry(&entry.ledger, &runner_names),
            ledger: ledger_entry_view_with_attempts(&entry.ledger, entry.attempt_count),
        })
        .collect::<Vec<_>>();
    Ok(Json(json!({
        "items": items,
        "total": total,
        "models": models,
        "protocols": protocols,
        "processing_tiers": processing_tiers,
        "reasoning_efforts": reasoning_efforts,
    })))
}

async fn member_ledger(
    State(state): State<ControlState>,
    headers: HeaderMap,
    query: Result<Query<MemberLedgerQuery>, QueryRejection>,
) -> Result<Json<Value>, ControlError> {
    let identity = require_member_retained_ready(&state, &headers).await?;
    let Query(query) = query.map_err(|_| ControlError::MemberUsageInvalid)?;
    let (limit, offset) = validated_page(query.limit, query.offset, 20, 100)
        .ok_or(ControlError::MemberUsageInvalid)?;
    if query
        .keyword
        .as_ref()
        .is_some_and(|value| value.chars().count() > 160 || !valid_optional_human_text(value, 160))
    {
        return Err(ControlError::MemberUsageInvalid);
    }
    let mut entries = state
        .verified_quota_snapshot(&identity.id)
        .await?
        .ledger_entries;
    entries.retain(|entry| {
        matches!(
            entry.kind.as_str(),
            "grant" | "voucher_grant" | "quota_request_grant" | "admin_grant"
        )
    });
    let keyword = query
        .keyword
        .as_deref()
        .map(str::trim)
        .unwrap_or_default()
        .to_lowercase();
    if !keyword.is_empty() {
        entries.retain(|entry| {
            entry.description.to_lowercase().contains(&keyword)
                || entry.kind.to_lowercase().contains(&keyword)
        });
    }
    entries.sort_by(|left, right| {
        right
            .created_at
            .cmp(&left.created_at)
            .then_with(|| right.id.cmp(&left.id))
    });
    let total = entries.len();
    Ok(Json(json!({
        "items": entries
            .iter()
            .skip(offset)
            .take(limit)
            .map(ledger_entry_view)
            .collect::<Vec<_>>(),
        "total": total,
    })))
}

