async fn create_api_key(
    State(state): State<ControlState>,
    headers: HeaderMap,
    request: Result<Json<CreateApiKeyRequest>, JsonRejection>,
) -> Result<Response, ControlError> {
    let identity = require_member_ready(&state, &headers).await?;
    let license = authorize_non_consuming_feature(&state, "member")?;
    let active_key_limit = resource_quota_limit(license.as_ref().quota(QuotaId::ApiKeysPerMember));
    let Json(request) = request.map_err(|_| ControlError::ApiKeyInvalid)?;
    let name = request.name.trim();
    if name.is_empty() || name.len() > 100 || name.chars().any(|value| value.is_control()) {
        return Err(ControlError::ApiKeyInvalid);
    }

    let id = random_identifier("key")?;
    let created_at =
        format_database_time((state.now)()).map_err(|_| ControlError::TimeConversionFailed)?;
    let issued = state
        .auth_core()?
        .issue_api_key()
        .map_err(ControlError::Auth)?;
    let mut record = ApiKeyRecord {
        id,
        identity_id: identity.id.clone(),
        name: name.to_owned(),
        key_hash: issued.digest().to_owned(),
        key_prefix: issued.prefix().to_owned(),
        status: "active".to_owned(),
        revision: 0,
        integrity_hmac: String::new(),
        created_at,
        last_used_at: None,
    };
    record.integrity_hmac = state
        .auth_core()?
        .api_key_integrity_hmac(api_key_integrity_input(&record))
        .map_err(ControlError::Auth)?;
    let mut inserted = false;
    for _ in 0..AUDIT_APPEND_RETRIES {
        let (expected_audit_sequence, expected_audit_hmac, audit_event) = state
            .prepare_audit_event(
                Some(&identity),
                "api_key.create",
                "api_key",
                Some(&record.id),
                "succeeded",
            )
            .await?;
        let _license_commit = state.guard_licensed_mutation(Some(&license), "member")?;
        let storage = state.credential_storage()?.clone();
        let mutation_record = record.clone();
        match finish_licensed_mutation(
            Arc::clone(&state.mutation_tasks),
            _license_commit,
            async move {
                storage
                    .insert_api_key_and_audit(
                        &mutation_record,
                        active_key_limit,
                        expected_audit_sequence,
                        &expected_audit_hmac,
                        &audit_event,
                    )
                    .await
            },
        )
        .await?
        {
            MutationWithAuditOutcome::Mutation(ResourceCreateOutcome::Created) => {
                inserted = true;
                break;
            }
            MutationWithAuditOutcome::AuditConflict => continue,
            MutationWithAuditOutcome::Mutation(ResourceCreateOutcome::Conflict) => {
                return Err(ControlError::DataIntegrityInvalid);
            }
            MutationWithAuditOutcome::Mutation(ResourceCreateOutcome::LimitReached) => {
                return Err(ControlError::ApiKeyLimitReached);
            }
        }
    }
    if !inserted {
        return Err(ControlError::DataIntegrityInvalid);
    }

    let key = issued.plaintext().to_owned();
    Ok((
        StatusCode::CREATED,
        Json(CreateApiKeyResponse {
            api_key: api_key_view(record),
            key,
            notice: "Key 明文仅显示一次，请立即保存",
        }),
    )
        .into_response())
}

async fn revoke_api_key(
    State(state): State<ControlState>,
    AxumPath(api_key_id): AxumPath<String>,
    headers: HeaderMap,
) -> Result<Json<Value>, ControlError> {
    let identity = require_member_retained_ready(&state, &headers).await?;
    let license = authorize_retained_feature(&state, "member")?;
    if !valid_resource_identifier(&api_key_id, "key_") {
        return Err(ControlError::ApiKeyNotFound);
    }
    let mut record = state
        .credential_storage()?
        .api_key_for_identity(&api_key_id, &identity.id)
        .await?
        .ok_or(ControlError::ApiKeyNotFound)?;
    verify_api_key_integrity(state.auth_core()?, &record)?;
    if record.status != "active" {
        return Err(ControlError::ApiKeyNotFound);
    }
    let expected_revision = record.revision;
    record.status = "revoked".to_owned();
    record.revision = record
        .revision
        .checked_add(1)
        .ok_or(ControlError::DataIntegrityInvalid)?;
    let integrity_hmac = state
        .auth_core()?
        .api_key_integrity_hmac(api_key_integrity_input(&record))
        .map_err(ControlError::Auth)?;
    let mut updated = false;
    for _ in 0..AUDIT_APPEND_RETRIES {
        let (expected_audit_sequence, expected_audit_hmac, audit_event) = state
            .prepare_audit_event(
                Some(&identity),
                "api_key.revoke",
                "api_key",
                Some(&api_key_id),
                "succeeded",
            )
            .await?;
        validate_service_actor(&state, &identity, PrincipalKind::Member, true).await?;
        let guard = state.guard_retained_mutation(&license, "member")?;
        let mutation = {
            let storage = state.credential_storage()?.clone();
            let api_key_id = api_key_id.clone();
            let identity = identity.clone();
            let integrity_hmac = integrity_hmac.clone();
            async move {
                storage
                    .update_api_key_status_and_audit(
                        &api_key_id,
                        &identity.id,
                        expected_revision,
                        "revoked",
                        &integrity_hmac,
                        expected_audit_sequence,
                        &expected_audit_hmac,
                        &audit_event,
                    )
                    .await
            }
        };
        match finish_licensed_mutation(Arc::clone(&state.mutation_tasks), guard, mutation).await? {
            AuditedMutationOutcome::Applied => {
                updated = true;
                break;
            }
            AuditedMutationOutcome::MutationConflict => {
                return Err(ControlError::ApiKeyUpdateConflict);
            }
            AuditedMutationOutcome::AuditConflict => continue,
        }
    }
    if !updated {
        return Err(ControlError::DataIntegrityInvalid);
    }
    Ok(Json(json!({ "ok": true })))
}

async fn require_member_ready(
    state: &ControlState,
    headers: &HeaderMap,
) -> Result<IdentityRecord, ControlError> {
    let identity = require_member_identity(state, headers).await?;
    authorize_model_consumption(state, "member").await?;
    Ok(identity)
}

async fn require_member_retained_ready(
    state: &ControlState,
    headers: &HeaderMap,
) -> Result<IdentityRecord, ControlError> {
    let identity = require_member_identity(state, headers).await?;
    authorize_retained_feature(state, "member")?;
    Ok(identity)
}

async fn require_member_identity(
    state: &ControlState,
    headers: &HeaderMap,
) -> Result<IdentityRecord, ControlError> {
    let identity = authenticate(state, headers, PrincipalKind::Member).await?;
    if identity.password_change_required {
        return Err(ControlError::PasswordChangeRequired(PrincipalKind::Member));
    }
    if !identity.can_consume_model {
        return Err(ControlError::Unauthenticated(PrincipalKind::Member));
    }
    Ok(identity)
}

async fn require_admin_ready(
    state: &ControlState,
    headers: &HeaderMap,
) -> Result<IdentityRecord, ControlError> {
    let identity = authenticate(state, headers, PrincipalKind::Admin).await?;
    if identity.password_change_required {
        return Err(ControlError::PasswordChangeRequired(PrincipalKind::Admin));
    }
    Ok(identity)
}

// Service callers must supply an intact administrator record that still matches
// storage. A previously valid snapshot cannot survive demotion, suspension or a
// password reset. HTTP authentication remains responsible for the session.
async fn validate_admin_actor(
    state: &ControlState,
    actor: &IdentityRecord,
) -> Result<(), ControlError> {
    validate_service_actor(state, actor, PrincipalKind::Admin, true).await
}

async fn validate_service_actor(
    state: &ControlState,
    actor: &IdentityRecord,
    kind: PrincipalKind,
    password_ready: bool,
) -> Result<(), ControlError> {
    verify_identity_integrity(state.auth_core()?, actor)?;
    let current = state
        .credential_storage()?
        .identity_by_id(&actor.id)
        .await?
        .ok_or(ControlError::Unauthenticated(kind))?;
    verify_identity_integrity(state.auth_core()?, &current)?;
    if !role_matches(kind, &current.role)
        || current.status != "active"
        || (password_ready && current.password_change_required)
        || (password_ready && kind == PrincipalKind::Member && !current.can_consume_model)
        || current != *actor
    {
        return Err(ControlError::Unauthenticated(kind));
    }
    Ok(())
}

async fn validate_quota_grant_target(
    state: &ControlState,
    identity_id: &str,
) -> Result<(), ControlError> {
    let target = state
        .credential_storage()?
        .identity_by_id(identity_id)
        .await?
        .filter(|identity| identity.role == "member" && identity.status != "deleted")
        .ok_or(ControlError::IdentityNotFound)?;
    verify_identity_integrity(state.auth_core()?, &target)
}

fn verify_api_key_integrity(
    auth_core: &AuthCore,
    api_key: &ApiKeyRecord,
) -> Result<(), ControlError> {
    let valid = auth_core
        .verify_api_key_integrity_hmac(api_key_integrity_input(api_key), &api_key.integrity_hmac)
        .map_err(|_| ControlError::DataIntegrityInvalid)?;
    if !valid {
        return Err(ControlError::DataIntegrityInvalid);
    }
    Ok(())
}

fn quota_request_integrity_hmac(
    auth_core: &AuthCore,
    request: &QuotaRequestRecord,
) -> Result<String, ControlError> {
    let payload = serde_json::to_vec(&json!([
        request.id,
        request.identity_id,
        request.amount_nanos,
        request.reason,
        request.status,
        request.review_note,
        request.reviewed_by,
        request.reviewed_at,
        request.created_at,
    ]))
    .map_err(|_| ControlError::DataIntegrityInvalid)?;
    auth_core
        .security_state_integrity_hmac(SecurityStateIntegrityInput {
            key: QUOTA_REQUEST_INTEGRITY_KEY,
            value: &payload,
            revision: u64::from(request.revision),
        })
        .map_err(ControlError::Auth)
}

fn verify_quota_request_integrity(
    auth_core: &AuthCore,
    request: &QuotaRequestRecord,
) -> Result<(), ControlError> {
    let expected = quota_request_integrity_hmac(auth_core, request)?;
    if !constant_time_string_eq(&expected, &request.integrity_hmac) {
        return Err(ControlError::DataIntegrityInvalid);
    }
    Ok(())
}

fn voucher_integrity_hmac(
    auth_core: &AuthCore,
    voucher: &VoucherRecord,
) -> Result<String, ControlError> {
    let payload = serde_json::to_vec(&json!([
        voucher.id,
        voucher.code_hash,
        voucher.code_prefix,
        voucher.name,
        voucher.quota_tokens,
        voucher.status,
        voucher.max_redemptions,
        voucher.redeemed_count,
        voucher.expires_at,
        voucher.created_by,
        voucher.created_at,
    ]))
    .map_err(|_| ControlError::DataIntegrityInvalid)?;
    auth_core
        .security_state_integrity_hmac(SecurityStateIntegrityInput {
            key: VOUCHER_INTEGRITY_KEY,
            value: &payload,
            revision: u64::from(voucher.revision),
        })
        .map_err(ControlError::Auth)
}

fn verify_voucher_integrity(
    auth_core: &AuthCore,
    voucher: &VoucherRecord,
) -> Result<(), ControlError> {
    let expected = voucher_integrity_hmac(auth_core, voucher)?;
    if !constant_time_string_eq(&expected, &voucher.integrity_hmac) {
        return Err(ControlError::DataIntegrityInvalid);
    }
    Ok(())
}

fn runtime_setting_integrity_hmac(
    auth_core: &AuthCore,
    record: &RuntimeSettingRecord,
) -> Result<String, ControlError> {
    auth_core
        .security_state_integrity_hmac(SecurityStateIntegrityInput {
            key: &record.key,
            value: record.value.as_bytes(),
            revision: record.revision,
        })
        .map_err(ControlError::Auth)
}

fn verify_runtime_setting_integrity(
    auth_core: &AuthCore,
    record: &RuntimeSettingRecord,
) -> Result<(), ControlError> {
    verify_runtime_setting_integrity_for_key(auth_core, record, RUNTIME_CONFIGURATION_KEY)
}

fn verify_runtime_setting_integrity_for_key(
    auth_core: &AuthCore,
    record: &RuntimeSettingRecord,
    expected_key: &str,
) -> Result<(), ControlError> {
    if record.key != expected_key {
        return Err(ControlError::DataIntegrityInvalid);
    }
    let expected = runtime_setting_integrity_hmac(auth_core, record)?;
    if !constant_time_string_eq(&expected, &record.integrity_hmac) {
        return Err(ControlError::DataIntegrityInvalid);
    }
    Ok(())
}

fn normalize_public_api_base_url(value: &str) -> Result<String, ControlError> {
    let mut parsed =
        url::Url::parse(value.trim()).map_err(|_| ControlError::PlatformSettingsInvalid)?;
    if !matches!(parsed.scheme(), "http" | "https")
        || parsed.host_str().is_none()
        || !parsed.username().is_empty()
        || parsed.password().is_some()
        || parsed.query().is_some()
        || parsed.fragment().is_some()
        || !matches!(parsed.path(), "" | "/")
    {
        return Err(ControlError::PlatformSettingsInvalid);
    }
    parsed.set_path("");
    Ok(parsed.as_str().trim_end_matches('/').to_owned())
}

fn api_key_view(record: ApiKeyRecord) -> ApiKeyView {
    ApiKeyView {
        id: record.id,
        name: record.name,
        key_prefix: record.key_prefix,
        status: record.status,
        created_at: record.created_at,
        last_used_at: record.last_used_at,
    }
}

fn request_origin(headers: &HeaderMap) -> Result<String, ControlError> {
    let scheme = headers
        .get("x-forwarded-proto")
        .and_then(|value| value.to_str().ok())
        .unwrap_or("http");
    if !matches!(scheme, "http" | "https") {
        return Err(ControlError::MemberUsageInvalid);
    }
    let host = headers
        .get(axum::http::header::HOST)
        .and_then(|value| value.to_str().ok())
        .ok_or(ControlError::MemberUsageInvalid)?;
    if host.is_empty()
        || host.len() > 255
        || !host.bytes().all(|byte| {
            byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'-' | b':' | b'[' | b']')
        })
    {
        return Err(ControlError::MemberUsageInvalid);
    }
    Ok(format!("{scheme}://{host}"))
}

fn filter_member_usage_entries<'a>(
    entries: &'a [QuotaLedgerEntry],
    period: Option<&str>,
    from: Option<&str>,
    to: Option<&str>,
    api_key_id: Option<&str>,
    now: OffsetDateTime,
) -> Result<Vec<&'a QuotaLedgerEntry>, ControlError> {
    let (start, end) = usage_time_window(period, from, to, now)?;
    filter_member_usage_entries_in_window(entries, start, end, api_key_id, true)
}

fn filter_member_usage_entries_in_window<'a>(
    entries: &'a [QuotaLedgerEntry],
    start: Option<OffsetDateTime>,
    end: Option<OffsetDateTime>,
    api_key_id: Option<&str>,
    include_failures: bool,
) -> Result<Vec<&'a QuotaLedgerEntry>, ControlError> {
    if api_key_id.is_some_and(|value| !valid_resource_identifier(value, "key_")) {
        return Err(ControlError::MemberUsageInvalid);
    }
    let mut filtered = Vec::new();
    for entry in entries
        .iter()
        .filter(|entry| entry.kind == "usage" || (include_failures && entry.kind == "usage_failed"))
    {
        let created_at = OffsetDateTime::parse(&entry.created_at, &Rfc3339)
            .map_err(|_| ControlError::DataIntegrityInvalid)?;
        if start.is_some_and(|start| created_at < start)
            || end.is_some_and(|end| created_at >= end)
            || api_key_id.is_some_and(|api_key_id| entry.api_key_id.as_deref() != Some(api_key_id))
        {
            continue;
        }
        filtered.push(entry);
    }
    Ok(filtered)
}

fn usage_time_window(
    period: Option<&str>,
    from: Option<&str>,
    to: Option<&str>,
    now: OffsetDateTime,
) -> Result<(Option<OffsetDateTime>, Option<OffsetDateTime>), ControlError> {
    usage_time_window_at_offset(period, from, to, now, UtcOffset::UTC, false)
}

fn usage_summary_time_window(
    period: Option<&str>,
    from: Option<&str>,
    to: Option<&str>,
    now: OffsetDateTime,
    utc_offset: UtcOffset,
    align_rolling_hours: bool,
) -> Result<(Option<OffsetDateTime>, Option<OffsetDateTime>), ControlError> {
    usage_time_window_at_offset(period, from, to, now, utc_offset, align_rolling_hours)
}

fn usage_time_window_at_offset(
    period: Option<&str>,
    from: Option<&str>,
    to: Option<&str>,
    now: OffsetDateTime,
    utc_offset: UtcOffset,
    align_rolling_hours: bool,
) -> Result<(Option<OffsetDateTime>, Option<OffsetDateTime>), ControlError> {
    if from.is_some() || to.is_some() {
        let from = parse_usage_date(from.ok_or(ControlError::MemberUsageInvalid)?)?;
        let to = parse_usage_date(to.ok_or(ControlError::MemberUsageInvalid)?)?;
        if from > to {
            return Err(ControlError::MemberUsageInvalid);
        }
        let start = time::PrimitiveDateTime::new(from, time::Time::MIDNIGHT)
            .assume_offset(utc_offset)
            .to_offset(UtcOffset::UTC);
        let end = time::PrimitiveDateTime::new(to, time::Time::MIDNIGHT)
            .assume_offset(utc_offset)
            .checked_add(time::Duration::days(1))
            .ok_or(ControlError::MemberUsageInvalid)?
            .to_offset(UtcOffset::UTC);
        return Ok((Some(start), Some(end)));
    }
    if align_rolling_hours && matches!(period, Some("24h" | "1d")) {
        let current_hour = usage_bucket_start(now, UsageGranularity::Minute(60), utc_offset)?;
        return Ok((Some(current_hour - time::Duration::hours(23)), None));
    }
    if align_rolling_hours {
        let days = match period {
            Some("7d") => Some(7),
            Some("14d") => Some(14),
            Some("30d") => Some(30),
            _ => None,
        };
        if let Some(days) = days {
            let today = usage_bucket_start(now, UsageGranularity::Day, utc_offset)?;
            return Ok((Some(today - time::Duration::days(days - 1)), None));
        }
    }
    let rolling_hours = match period.unwrap_or("7d") {
        "1h" => Some(1),
        "6h" => Some(6),
        _ => None,
    };
    if align_rolling_hours && let Some(hours) = rolling_hours {
        let end = now;
        let start = end
            .checked_sub(time::Duration::hours(hours))
            .ok_or(ControlError::MemberUsageInvalid)?;
        return Ok((Some(start), Some(end)));
    }
    let start = match period.unwrap_or("7d") {
        "1h" => Some(now - time::Duration::hours(1)),
        "6h" => Some(now - time::Duration::hours(6)),
        "24h" | "1d" => Some(now - time::Duration::days(1)),
        "7d" => Some(now - time::Duration::days(7)),
        "14d" => Some(now - time::Duration::days(14)),
        "30d" => Some(now - time::Duration::days(30)),
        "all" => None,
        _ => return Err(ControlError::MemberUsageInvalid),
    };
    Ok((start, None))
}

fn parse_usage_date(value: &str) -> Result<time::Date, ControlError> {
    if value.len() != 10 {
        return Err(ControlError::MemberUsageInvalid);
    }
    time::Date::parse(value, format_description!("[year]-[month]-[day]"))
        .map_err(|_| ControlError::MemberUsageInvalid)
}

fn usage_utc_offset(minutes: Option<i32>) -> Result<UtcOffset, ControlError> {
    let minutes = minutes.unwrap_or(0);
    if !(-14 * 60..=14 * 60).contains(&minutes) {
        return Err(ControlError::MemberUsageInvalid);
    }
    UtcOffset::from_whole_seconds(minutes.saturating_mul(60))
        .map_err(|_| ControlError::MemberUsageInvalid)
}

fn resolve_usage_granularity(
    period: Option<&str>,
    from: Option<&str>,
    to: Option<&str>,
    start: Option<OffsetDateTime>,
    end: Option<OffsetDateTime>,
    entries: &[&QuotaLedgerEntry],
    now: OffsetDateTime,
) -> Result<UsageGranularity, ControlError> {
    if from.is_some() || to.is_some() {
        let (Some(start), Some(end)) = (start, end) else {
            return Err(ControlError::MemberUsageInvalid);
        };
        return Ok(usage_granularity_for_duration(end - start));
    }
    match period.unwrap_or("7d") {
        "1h" => Ok(UsageGranularity::Second(10)),
        "6h" => Ok(UsageGranularity::Minute(1)),
        "24h" | "1d" => Ok(UsageGranularity::Minute(60)),
        "7d" | "14d" | "30d" => Ok(UsageGranularity::Day),
        "all" => {
            let earliest = entries
                .first()
                .map(|entry| OffsetDateTime::parse(&entry.created_at, &Rfc3339))
                .transpose()
                .map_err(|_| ControlError::DataIntegrityInvalid)?;
            Ok(earliest.map_or(UsageGranularity::Day, |earliest| {
                usage_granularity_for_duration(now - earliest)
            }))
        }
        _ => Err(ControlError::MemberUsageInvalid),
    }
}

fn usage_granularity_for_duration(duration: time::Duration) -> UsageGranularity {
    let seconds = duration.whole_seconds().max(1);
    if seconds <= 60 * 60 {
        UsageGranularity::Second(10)
    } else if seconds <= 6 * 60 * 60 {
        UsageGranularity::Minute(1)
    } else if seconds <= 24 * 60 * 60 {
        UsageGranularity::Minute(5)
    } else if seconds <= 7 * 24 * 60 * 60 {
        UsageGranularity::Minute(30)
    } else if seconds <= 90 * 24 * 60 * 60 {
        UsageGranularity::Day
    } else if seconds <= 730 * 24 * 60 * 60 {
        UsageGranularity::Week
    } else {
        UsageGranularity::Month
    }
}

fn usage_bucket_start(
    value: OffsetDateTime,
    granularity: UsageGranularity,
    utc_offset: UtcOffset,
) -> Result<OffsetDateTime, ControlError> {
    let local = value.to_offset(utc_offset);
    let date = match granularity {
        UsageGranularity::Second(_) | UsageGranularity::Minute(_) | UsageGranularity::Day => {
            local.date()
        }
        UsageGranularity::Week => local
            .date()
            .checked_sub(time::Duration::days(i64::from(
                local.weekday().number_days_from_monday(),
            )))
            .ok_or(ControlError::MemberUsageInvalid)?,
        UsageGranularity::Month => time::Date::from_calendar_date(local.year(), local.month(), 1)
            .map_err(|_| ControlError::MemberUsageInvalid)?,
    };
    let time = match granularity {
        UsageGranularity::Second(seconds) => {
            let second = local.second() - local.second() % seconds;
            time::Time::from_hms(local.hour(), local.minute(), second)
                .map_err(|_| ControlError::MemberUsageInvalid)?
        }
        UsageGranularity::Minute(minutes) => {
            let minute = local.minute() - local.minute() % minutes;
            time::Time::from_hms(local.hour(), minute, 0)
                .map_err(|_| ControlError::MemberUsageInvalid)?
        }
        UsageGranularity::Day | UsageGranularity::Week | UsageGranularity::Month => {
            time::Time::MIDNIGHT
        }
    };
    Ok(time::PrimitiveDateTime::new(date, time).assume_offset(utc_offset))
}

fn next_usage_bucket(
    value: OffsetDateTime,
    granularity: UsageGranularity,
) -> Result<OffsetDateTime, ControlError> {
    match granularity {
        UsageGranularity::Second(seconds) => {
            value.checked_add(time::Duration::seconds(i64::from(seconds)))
        }
        UsageGranularity::Minute(minutes) => {
            value.checked_add(time::Duration::minutes(i64::from(minutes)))
        }
        UsageGranularity::Day => value.checked_add(time::Duration::days(1)),
        UsageGranularity::Week => value.checked_add(time::Duration::weeks(1)),
        UsageGranularity::Month => {
            let (year, month) = if value.month() == time::Month::December {
                (value.year() + 1, time::Month::January)
            } else {
                (value.year(), value.month().next())
            };
            let date = time::Date::from_calendar_date(year, month, 1)
                .map_err(|_| ControlError::MemberUsageInvalid)?;
            Some(
                time::PrimitiveDateTime::new(date, time::Time::MIDNIGHT)
                    .assume_offset(value.offset()),
            )
        }
    }
    .ok_or(ControlError::MemberUsageInvalid)
}

fn usage_bucket_label(
    entry: &QuotaLedgerEntry,
    granularity: UsageGranularity,
    utc_offset: UtcOffset,
) -> Result<String, ControlError> {
    let created_at = OffsetDateTime::parse(&entry.created_at, &Rfc3339)
        .map_err(|_| ControlError::DataIntegrityInvalid)?;
    format_usage_bucket(
        usage_bucket_start(created_at, granularity, utc_offset)?,
        granularity,
    )
}

fn format_usage_bucket(
    value: OffsetDateTime,
    granularity: UsageGranularity,
) -> Result<String, ControlError> {
    if matches!(
        granularity,
        UsageGranularity::Second(_) | UsageGranularity::Minute(_)
    ) {
        value
            .format(&Rfc3339)
            .map_err(|_| ControlError::DataIntegrityInvalid)
    } else {
        value
            .date()
            .format(format_description!("[year]-[month]-[day]"))
            .map_err(|_| ControlError::DataIntegrityInvalid)
    }
}

fn usage_trend_range(
    granularity: UsageGranularity,
    start: Option<OffsetDateTime>,
    end: Option<OffsetDateTime>,
    entries: &[&QuotaLedgerEntry],
    now: OffsetDateTime,
    utc_offset: UtcOffset,
) -> Result<Option<(OffsetDateTime, OffsetDateTime)>, ControlError> {
    let range_start = if let Some(start) = start {
        usage_bucket_start(start, granularity, utc_offset)?
    } else if let Some(entry) = entries.first() {
        let created_at = OffsetDateTime::parse(&entry.created_at, &Rfc3339)
            .map_err(|_| ControlError::DataIntegrityInvalid)?;
        usage_bucket_start(created_at, granularity, utc_offset)?
    } else {
        return Ok(None);
    };
    let range_end = if let Some(end) = end {
        let bucket = usage_bucket_start(end, granularity, utc_offset)?;
        if bucket < end {
            next_usage_bucket(bucket, granularity)?
        } else {
            bucket
        }
    } else {
        next_usage_bucket(
            usage_bucket_start(now, granularity, utc_offset)?,
            granularity,
        )?
    };
    if range_start >= range_end {
        return Err(ControlError::MemberUsageInvalid);
    }
    Ok(Some((range_start, range_end)))
}

fn fill_usage_trend(
    mut trend: BTreeMap<String, UsageMetricsView>,
    granularity: UsageGranularity,
    range: Option<(OffsetDateTime, OffsetDateTime)>,
) -> Result<Vec<UsageTrendView>, ControlError> {
    let Some((mut cursor, end)) = range else {
        return Ok(Vec::new());
    };
    let mut rows = Vec::new();
    while cursor < end {
        if rows.len() >= 400 {
            return Err(ControlError::MemberUsageInvalid);
        }
        let date = format_usage_bucket(cursor, granularity)?;
        rows.push(UsageTrendView {
            metrics: trend.remove(&date).unwrap_or_default(),
            date,
        });
        cursor = next_usage_bucket(cursor, granularity)?;
    }
    Ok(rows)
}

fn format_usage_range_boundary(
    value: Option<OffsetDateTime>,
) -> Result<Option<String>, ControlError> {
    value
        .map(|value| {
            value
                .format(&Rfc3339)
                .map_err(|_| ControlError::DataIntegrityInvalid)
        })
        .transpose()
}

fn add_usage_metrics(metrics: &mut UsageMetricsView, entry: &QuotaLedgerEntry) {
    metrics.request_count = metrics.request_count.saturating_add(1);
    metrics.raw_tokens = metrics.raw_tokens.saturating_add(entry.raw_tokens);
    metrics.billed_tokens = metrics.billed_tokens.saturating_add(entry.billed_tokens);
    metrics.uncovered_tokens = metrics
        .uncovered_tokens
        .saturating_add(entry.uncovered_tokens);
    metrics.uncached_input_tokens = metrics
        .uncached_input_tokens
        .saturating_add(entry.uncached_input);
    metrics.cached_input_tokens = metrics
        .cached_input_tokens
        .saturating_add(entry.cached_input);
    metrics.cache_write_tokens = metrics.cache_write_tokens.saturating_add(entry.cache_write);
    metrics.output_tokens = metrics.output_tokens.saturating_add(entry.output_tokens);
}

fn add_usage_metrics_checked(
    metrics: &mut UsageMetricsView,
    entry: &QuotaLedgerEntry,
) -> Result<(), ControlError> {
    metrics.request_count = metrics
        .request_count
        .checked_add(1)
        .ok_or(ControlError::DataIntegrityInvalid)?;
    metrics.raw_tokens = metrics
        .raw_tokens
        .checked_add(entry.raw_tokens)
        .ok_or(ControlError::DataIntegrityInvalid)?;
    metrics.billed_tokens = metrics
        .billed_tokens
        .checked_add(entry.billed_tokens)
        .ok_or(ControlError::DataIntegrityInvalid)?;
    metrics.uncovered_tokens = metrics
        .uncovered_tokens
        .checked_add(entry.uncovered_tokens)
        .ok_or(ControlError::DataIntegrityInvalid)?;
    metrics.uncached_input_tokens = metrics
        .uncached_input_tokens
        .checked_add(entry.uncached_input)
        .ok_or(ControlError::DataIntegrityInvalid)?;
    metrics.cached_input_tokens = metrics
        .cached_input_tokens
        .checked_add(entry.cached_input)
        .ok_or(ControlError::DataIntegrityInvalid)?;
    metrics.cache_write_tokens = metrics
        .cache_write_tokens
        .checked_add(entry.cache_write)
        .ok_or(ControlError::DataIntegrityInvalid)?;
    metrics.output_tokens = metrics
        .output_tokens
        .checked_add(entry.output_tokens)
        .ok_or(ControlError::DataIntegrityInvalid)?;
    Ok(())
}

fn usage_dimension_value(value: Option<&str>) -> &'static str {
    match value {
        Some("auto") => "auto",
        Some("standard") => "standard",
        Some("flex") => "flex",
        Some("fast") => "fast",
        Some("ultrafast") => "ultrafast",
        Some("none") => "none",
        Some("low") => "low",
        Some("medium") => "medium",
        Some("high") => "high",
        Some("xhigh") => "xhigh",
        Some("max") => "max",
        _ => "model_default",
    }
}

fn usage_dimension_matches(stored: Option<&str>, filter: Option<&str>) -> bool {
    filter.is_none_or(|filter| usage_dimension_value(stored) == filter)
}

fn usage_dimension_views(
    dimensions: BTreeMap<String, UsageMetricsView>,
) -> Vec<UsageDimensionView> {
    let mut rows = dimensions
        .into_iter()
        .map(|(value, metrics)| UsageDimensionView { value, metrics })
        .collect::<Vec<_>>();
    rows.sort_by(|left, right| {
        right
            .metrics
            .raw_tokens
            .cmp(&left.metrics.raw_tokens)
            .then_with(|| left.value.cmp(&right.value))
    });
    rows
}

#[derive(Clone, Debug)]
struct LogicalUsageEntry {
    ledger: QuotaLedgerEntry,
    attempt_count: u32,
}

fn logical_usage_entries(
    entries: impl IntoIterator<Item = QuotaLedgerEntry>,
) -> Result<Vec<LogicalUsageEntry>, ControlError> {
    let mut logical = HashMap::<(String, String, String), LogicalUsageEntry>::new();
    for entry in entries {
        let key = (
            entry.identity_id.clone(),
            entry.api_key_id.clone().unwrap_or_default(),
            entry
                .client_request_id
                .clone()
                .unwrap_or_else(|| format!("aster:{}", entry.reference_id)),
        );
        let Some(existing) = logical.get_mut(&key) else {
            logical.insert(
                key,
                LogicalUsageEntry {
                    ledger: entry,
                    attempt_count: 1,
                },
            );
            continue;
        };
        existing.attempt_count = existing
            .attempt_count
            .checked_add(1)
            .ok_or(ControlError::DataIntegrityInvalid)?;
        match (existing.ledger.kind.as_str(), entry.kind.as_str()) {
            ("usage_failed", "usage") => existing.ledger = entry,
            ("usage_failed", "usage_failed") if entry.created_at > existing.ledger.created_at => {
                existing.ledger = entry;
            }
            ("usage", "usage") => {
                existing.ledger.amount_tokens = existing
                    .ledger
                    .amount_tokens
                    .checked_add(entry.amount_tokens)
                    .ok_or(ControlError::DataIntegrityInvalid)?;
                existing.ledger.uncached_input = existing
                    .ledger
                    .uncached_input
                    .checked_add(entry.uncached_input)
                    .ok_or(ControlError::DataIntegrityInvalid)?;
                existing.ledger.cached_input = existing
                    .ledger
                    .cached_input
                    .checked_add(entry.cached_input)
                    .ok_or(ControlError::DataIntegrityInvalid)?;
                existing.ledger.cache_write = existing
                    .ledger
                    .cache_write
                    .checked_add(entry.cache_write)
                    .ok_or(ControlError::DataIntegrityInvalid)?;
                existing.ledger.output_tokens = existing
                    .ledger
                    .output_tokens
                    .checked_add(entry.output_tokens)
                    .ok_or(ControlError::DataIntegrityInvalid)?;
                existing.ledger.uncovered_tokens = existing
                    .ledger
                    .uncovered_tokens
                    .checked_add(entry.uncovered_tokens)
                    .ok_or(ControlError::DataIntegrityInvalid)?;
                existing.ledger.raw_tokens = existing
                    .ledger
                    .raw_tokens
                    .checked_add(entry.raw_tokens)
                    .ok_or(ControlError::DataIntegrityInvalid)?;
                existing.ledger.billed_tokens = existing
                    .ledger
                    .billed_tokens
                    .checked_add(entry.billed_tokens)
                    .ok_or(ControlError::DataIntegrityInvalid)?;
                if entry.created_at > existing.ledger.created_at {
                    existing.ledger.id = entry.id;
                    existing.ledger.runner_id = entry.runner_id;
                    existing.ledger.created_at = entry.created_at;
                }
            }
            _ => {}
        }
    }
    Ok(logical.into_values().collect())
}

