fn admin_voucher_view(
    voucher: VoucherRecord,
    delivery_count: usize,
    delivered_to_emails: String,
    redeemed_by_emails: String,
    last_redeemed_at: Option<String>,
    now: OffsetDateTime,
) -> Result<AdminVoucherView, ControlError> {
    let expired = voucher
        .expires_at
        .as_deref()
        .map(|expires_at| {
            OffsetDateTime::parse(expires_at, &Rfc3339)
                .map(|expires_at| expires_at <= now)
                .map_err(|_| ControlError::DataIntegrityInvalid)
        })
        .transpose()?
        .unwrap_or(false);
    Ok(AdminVoucherView {
        id: voucher.id,
        code_prefix: voucher.code_prefix,
        name: voucher.name,
        quota_tokens: voucher.quota_tokens,
        status: if expired && voucher.status == "active" {
            "expired".to_owned()
        } else {
            voucher.status
        },
        max_redemptions: voucher.max_redemptions,
        redeemed_count: voucher.redeemed_count,
        delivery_count,
        delivered_to_emails,
        redeemed_by_emails,
        last_redeemed_at,
        expires_at: voucher.expires_at,
        created_at: voucher.created_at,
    })
}

