    #[test]
    fn storage_failures_keep_distinct_public_causes() {
        let decode = ControlError::StorageFailure(
            StorageFailureKind::Decode,
            "revision column decoded with an incompatible Rust type".to_owned(),
        );
        assert_eq!(decode.descriptor().code, "BACKEND_DATABASE_DECODE_FAILED");
        assert_eq!(decode.descriptor().number, 91010);
        assert_eq!(decode.status(), StatusCode::INTERNAL_SERVER_ERROR);
        assert!(!decode.safe_message().contains("revision"));
        let connection = ControlError::StorageFailure(
            StorageFailureKind::Connection,
            "private database host".to_owned(),
        );
        assert_eq!(
            connection.descriptor().code,
            "BACKEND_DATABASE_CONNECTION_FAILED"
        );
        assert_eq!(connection.status(), StatusCode::SERVICE_UNAVAILABLE);
        assert!(!connection.safe_message().contains("private database host"));
    }

    #[test]
    fn unsupported_official_price_sync_has_distinct_public_error() {
        let error = ControlError::BillingPriceSyncUnsupported;
        assert_eq!(error.descriptor().code, "BILLING_PRICE_SYNC_UNSUPPORTED");
        assert_eq!(error.descriptor().number, 15_004);
        assert_eq!(error.status(), StatusCode::UNPROCESSABLE_ENTITY);
    }

    #[test]
    fn missing_member_model_grant_has_a_distinct_public_error() {
        let error = ControlError::ModelAccessDenied;
        assert_eq!(error.descriptor().code, "MODEL_ACCESS_DENIED");
        assert_eq!(error.descriptor().number, 33_005);
        assert_eq!(error.safe_message(), "该模型未授权给当前用户");
        assert_eq!(error.status(), StatusCode::FORBIDDEN);
    }

