    #[test]
    fn upstream_error_diagnostics_keep_allowlisted_fields_and_redact_secrets() {
        let headers = vec![ResponseHeader {
            name: "x-request-id".to_owned(),
            value: "upstream_req_12345678".to_owned(),
        }];
        let diagnostic = safe_upstream_error(
            br#"{"error":{"code":"unsupported_value","type":"invalid_request_error","param":"service_tier","message":"Unsupported value: fast"},"ignored":"secret"}"#,
            &headers,
        );
        assert_eq!(diagnostic.code.as_deref(), Some("unsupported_value"));
        assert_eq!(diagnostic.kind.as_deref(), Some("invalid_request_error"));
        assert_eq!(diagnostic.param.as_deref(), Some("service_tier"));
        assert_eq!(
            diagnostic.message.as_deref(),
            Some("Unsupported value: fast")
        );
        assert_eq!(
            diagnostic.request_id.as_deref(),
            Some("upstream_req_12345678")
        );

        let redacted = safe_upstream_error(
            br#"{"error":{"message":"Authorization: Bearer sk-secret-value"}}"#,
            &[],
        );
        assert_eq!(redacted.message.as_deref(), Some("[redacted]"));
    }

    #[test]
    fn gateway_request_id_is_unique_when_clients_reuse_tracking_headers() {
        let client_id = "01a06bea-7368-77b2-9503-677bc5b68235";
        for header_names in [
            vec![],
            vec!["x-request-id"],
            vec!["x-client-request-id"],
            vec!["x-request-id", "x-client-request-id"],
        ] {
            let mut headers = HeaderMap::new();
            for name in header_names {
                headers.insert(name, HeaderValue::from_static(client_id));
            }
            let first = gateway_request_id(&headers).expect("first request ID");
            let second = gateway_request_id(&headers).expect("second request ID");
            assert_ne!(
                first, second,
                "separate HTTP requests need separate quota IDs"
            );
            assert_ne!(first.as_str(), client_id);
            assert!(first.starts_with("request_"));
            assert!(valid_gateway_request_id(&first));
        }
    }

    #[test]
    fn gateway_client_request_id_preserves_safe_correlation_and_rejects_log_injection() {
        let mut headers = HeaderMap::new();
        assert_eq!(gateway_client_request_id(&headers), None);
        headers.insert(
            "x-client-request-id",
            HeaderValue::from_static("diag-20260904182907-fast"),
        );
        assert_eq!(
            gateway_client_request_id(&headers),
            Some("diag-20260904182907-fast")
        );
        headers.insert("x-request-id", HeaderValue::from_static("proxy-12345678"));
        assert_eq!(
            gateway_client_request_id(&headers),
            Some("diag-20260904182907-fast")
        );
        headers.insert("x-request-id", HeaderValue::from_static("unsafe log value"));
        assert_eq!(
            gateway_client_request_id(&headers),
            Some("diag-20260904182907-fast")
        );
        headers.insert("x-client-request-id", HeaderValue::from_static("unsafe/id"));
        assert_eq!(gateway_client_request_id(&headers), None);
        headers.insert(
            "x-request-id",
            HeaderValue::from_str(&"a".repeat(161)).expect("long header"),
        );
        assert_eq!(gateway_client_request_id(&headers), None);
        assert!(valid_gateway_request_id("request_12345678"));
        assert!(!valid_gateway_request_id("request id with spaces"));
        assert!(!valid_gateway_request_id("request/with/slashes"));
    }

    #[tokio::test]
    async fn gateway_error_returns_the_aster_request_id() {
        let response = GatewayError::with_request_id(
            ControlError::UpstreamRequestFailed,
            false,
            "request_test_12345678",
        )
        .into_response();
        assert_eq!(
            response
                .headers()
                .get("X-Aster-Request-ID")
                .and_then(|value| value.to_str().ok()),
            Some("request_test_12345678")
        );
        let body = response
            .into_body()
            .collect()
            .await
            .expect("collect gateway error")
            .to_bytes();
        let value: Value = serde_json::from_slice(&body).expect("decode gateway error");
        assert_eq!(value["request_id"], "request_test_12345678");
        assert!(
            value["error"]["message"]
                .as_str()
                .is_some_and(|message| message.contains("request_test_12345678"))
        );
    }

