    #[test]
    fn admin_overview_uses_complete_calendar_periods_and_previous_comparison() {
        let window =
            admin_overview_window(Some("14d"), None, None, datetime!(2026-09-02 13:24 UTC))
                .expect("valid overview period");
        assert_eq!(window.period, "14d");
        assert_eq!(window.days, 14);
        assert_eq!(window.current_start, datetime!(2026-08-20 0:00 UTC));
        assert_eq!(window.current_end, datetime!(2026-09-03 0:00 UTC));
        assert_eq!(window.previous_start, datetime!(2026-08-06 0:00 UTC));
        assert_eq!(window.previous_end, datetime!(2026-08-20 0:00 UTC));
        assert!(matches!(
            admin_overview_window(Some("all"), None, None, datetime!(2026-09-02 13:24 UTC)),
            Err(ControlError::AdminConsumptionInvalid)
        ));

        let custom = admin_overview_window(
            None,
            Some("2026-08-20"),
            Some("2026-09-02"),
            datetime!(2026-09-02 13:24 UTC),
        )
        .expect("valid custom overview period");
        assert_eq!(custom.period, "custom");
        assert_eq!(custom.days, 14);
        assert_eq!(custom.current_start, datetime!(2026-08-20 0:00 UTC));
        assert_eq!(custom.current_end, datetime!(2026-09-03 0:00 UTC));
        assert_eq!(custom.previous_start, datetime!(2026-08-06 0:00 UTC));
        assert_eq!(custom.previous_end, datetime!(2026-08-20 0:00 UTC));
        assert!(matches!(
            admin_overview_window(
                None,
                Some("2026-09-01"),
                None,
                datetime!(2026-09-02 13:24 UTC),
            ),
            Err(ControlError::AdminConsumptionInvalid)
        ));
        assert!(matches!(
            admin_overview_window(
                Some("7d"),
                Some("2026-09-01"),
                Some("2026-09-02"),
                datetime!(2026-09-02 13:24 UTC),
            ),
            Err(ControlError::AdminConsumptionInvalid)
        ));
        assert!(matches!(
            admin_overview_window(
                None,
                Some("2025-09-01"),
                Some("2026-09-02"),
                datetime!(2026-09-02 13:24 UTC),
            ),
            Err(ControlError::AdminConsumptionInvalid)
        ));
    }

    #[test]
    fn asterctl_download_is_derived_from_the_signed_installed_release() {
        let directory = tempdir().expect("release root");
        let binary = b"MZ signed asterctl fixture";
        let artifact_path = directory
            .path()
            .join("client-tools/asterctl/windows-x86_64/asterctl.exe");
        std::fs::create_dir_all(artifact_path.parent().expect("artifact parent"))
            .expect("binary directory");
        std::fs::write(&artifact_path, binary).expect("asterctl fixture");
        let signing_key = SigningKey::from_bytes(&[61_u8; 32]);
        let claims = ReleaseClaims {
            schema: RELEASE_SCHEMA.to_owned(),
            key_id: "release-asterctl-test".to_owned(),
            product: "aster-team".to_owned(),
            version: "2.0.0".to_owned(),
            platform: "linux".to_owned(),
            architecture: "amd64".to_owned(),
            runtime: "musl-static".to_owned(),
            created_at: "2026-09-02T00:00:00.000Z".to_owned(),
            files: vec![ReleaseFile {
                path: "client-tools/asterctl/windows-x86_64/asterctl.exe".to_owned(),
                size: binary.len() as u64,
                sha256: sha256_hex(binary),
                executable: false,
            }],
        };
        let document = sign_release(claims, &signing_key).expect("sign release");
        std::fs::write(
            directory.path().join(RELEASE_MANIFEST_FILE),
            serde_json::to_vec(&document).expect("release JSON"),
        )
        .expect("release manifest");
        let mut trusted_keys = TrustedReleaseKeys::new();
        trusted_keys
            .insert("release-asterctl-test", signing_key.verifying_key())
            .expect("trusted release key");

        let mut artifact = load_asterctl_from_release_root(directory.path(), &trusted_keys)
            .expect("load artifact")
            .expect("artifact exists");
        assert_eq!(artifact.view.id, "asterctl-2.0.0-windows-x86_64");
        assert_eq!(artifact.view.file_name, "asterctl.exe");
        assert_eq!(
            artifact.view.download_url,
            "/api/member/asterctl/artifacts/asterctl-2.0.0-windows-x86_64/download"
        );
        let mut streamed = Vec::new();
        artifact
            .file
            .read_to_end(&mut streamed)
            .expect("read verified artifact");
        assert_eq!(streamed, binary);

        std::fs::write(&artifact_path, b"tampered").expect("tamper fixture");
        assert!(matches!(
            load_asterctl_from_release_root(directory.path(), &trusted_keys),
            Err(ControlError::DataIntegrityInvalid)
        ));
    }

