    pub(super) fn verified_license() -> VerifiedProductLicense {
        verified_license_with_seats(10)
    }

    fn verified_license_with_seats(member_seats: u32) -> VerifiedProductLicense {
        let signing_key = SigningKey::from_bytes(&[31_u8; 32]);
        let claims = LicenseClaims {
            schema: LICENSE_SCHEMA.to_owned(),
            key_id: "license-test-01".to_owned(),
            license_id: "license_test_001".to_owned(),
            serial: "AT-TEST-001".to_owned(),
            request_id: "request_test_001".to_owned(),
            customer_ref: "customer_test_001".to_owned(),
            product: "aster-team".to_owned(),
            edition: "enterprise".to_owned(),
            features: vec![
                "gateway".to_owned(),
                "member".to_owned(),
                "runner".to_owned(),
            ],
            limits: LicenseLimits {
                member_seats,
                seat_over_limit_grace_days: 0,
            },
            minimum_version: "0.1.0".to_owned(),
            installation_id: "installation_test_001".to_owned(),
            machine_fingerprint_sha256: "A".repeat(43),
            transfer_sequence: 0,
            issued_at: "2026-08-26T00:00:00.000Z".to_owned(),
            not_before: "2026-08-26T00:00:00.000Z".to_owned(),
            expires_at: "2027-08-26T00:00:00.000Z".to_owned(),
        };
        let document = sign(claims, &signing_key).expect("sign license");
        let mut keys = TrustedLicenseKeys::new();
        keys.insert("license-test-01", signing_key.verifying_key())
            .expect("insert key");
        verify_v1(
            &serde_json::to_vec(&document).expect("serialize license"),
            &keys,
        )
        .expect("verify license")
        .into()
    }

    fn signed_bound_license(
        profile: &InstallationProfile,
        sequence: u32,
        issued_at: &str,
    ) -> (Vec<u8>, TrustedLicenseKeys) {
        signed_bound_license_with_features(profile, sequence, issued_at, &["member"])
    }

    fn signed_bound_license_with_features(
        profile: &InstallationProfile,
        sequence: u32,
        issued_at: &str,
        features: &[&str],
    ) -> (Vec<u8>, TrustedLicenseKeys) {
        let signing_key = SigningKey::from_bytes(&[32_u8; 32]);
        let (template, _) = signed_v2_license(2, Some(profile));
        let mut claims: v2::Claims = serde_json::from_slice::<v2::Document>(&template)
            .unwrap()
            .claims;
        claims.key_id = "license-install-test-01".to_owned();
        claims.license_id = "license_install_test_001".to_owned();
        claims.serial = format!("AT-INSTALL-{sequence:03}");
        claims.source = v2::Source::CommercialOrder {
            order_id: "order_install_test_001".to_owned(),
            request_id: format!("request_install_{sequence:03}"),
            customer_ref: "customer_install_test_001".to_owned(),
        };
        claims.edition = "enterprise".to_owned();
        claims.entitlements.features = serde_json::from_value(json!(features)).unwrap();
        for quota in &mut claims.entitlements.quotas {
            quota.limit = if quota.id == QuotaId::MemberSeats {
                QuotaLimit::Limited { value: 10 }
            } else {
                QuotaLimit::Unlimited {}
            };
        }
        claims.minimum_version = "0.1.0".to_owned();
        set_test_transfer_sequence(&mut claims, sequence);
        claims.issued_at = issued_at.to_owned();
        claims.validity.not_before = issued_at.to_owned();
        claims.validity.expiry = v2::Expiry::Fixed {
            expires_at: "2027-08-26T00:00:00.000Z".to_owned(),
        };
        let document = v2::sign(claims, &signing_key).expect("sign bound license");
        let mut keys = TrustedLicenseKeys::new();
        // This test issuer serves successive paid documents with different
        // feature selections; its fixed ceiling includes all current features.
        let mut policy = v2_policy(&document);
        policy.entitlement_ceiling.features =
            serde_json::from_value(json!(["gateway", "member", "runner"])).unwrap();
        keys.insert_scoped(
            "license-install-test-01",
            signing_key.verifying_key(),
            policy,
        )
        .expect("insert scoped key");
        (
            serde_json::to_vec(&document).expect("serialize bound license"),
            keys,
        )
    }

    fn set_test_transfer_sequence(claims: &mut v2::Claims, sequence: u32) {
        let v2::Binding::Installation {
            transfer_sequence, ..
        } = &mut claims.binding
        else {
            panic!("bound fixture");
        };
        *transfer_sequence = sequence;
    }

    fn set_test_installation_id(claims: &mut v2::Claims, value: String) {
        let v2::Binding::Installation {
            installation_id, ..
        } = &mut claims.binding
        else {
            panic!("bound fixture");
        };
        *installation_id = value;
    }

    fn set_test_seats(claims: &mut v2::Claims, value: u32) {
        claims
            .entitlements
            .quotas
            .iter_mut()
            .find(|quota| quota.id == QuotaId::MemberSeats)
            .unwrap()
            .limit = QuotaLimit::Limited { value };
    }

    pub(super) fn signed_v2_license(
        fixture_index: usize,
        profile: Option<&InstallationProfile>,
    ) -> (Vec<u8>, TrustedLicenseKeys) {
        let fixture: Value = serde_json::from_slice(include_bytes!(
            "../../../../contracts/test-vectors/license.v2.json"
        ))
        .expect("parse v2 fixture");
        let mut document: v2::Document =
            serde_json::from_value(fixture["cases"][fixture_index]["document"].clone())
                .expect("parse v2 document");
        if let Some(profile) = profile {
            document.claims.binding = v2::Binding::Installation {
                installation_id: profile.installation_id.clone(),
                machine_fingerprint_sha256: profile.machine_fingerprint_sha256.clone(),
                transfer_sequence: 0,
            };
        }
        let signing_key = SigningKey::from_bytes(&[42_u8; 32]);
        let document = v2::sign(document.claims, &signing_key).expect("sign v2 license");
        let policy = v2_policy(&document);
        let mut keys = TrustedLicenseKeys::new();
        keys.insert_scoped(
            document.claims.key_id.clone(),
            signing_key.verifying_key(),
            policy,
        )
        .expect("insert scoped v2 key");
        (
            serde_json::to_vec(&document).expect("serialize v2 license"),
            keys,
        )
    }

    #[cfg(any(feature = "sqlcipher", feature = "sqlite-dev"))]
    pub(super) fn signed_v2_license_with_features(
        features: Vec<aster_license_core::catalog::CapabilityId>,
    ) -> (Vec<u8>, TrustedLicenseKeys) {
        let (source, _) = signed_v2_license(0, None);
        let mut document: v2::Document = serde_json::from_slice(&source).unwrap();
        document.claims.entitlements.features = features;
        let key = SigningKey::from_bytes(&[42; 32]);
        let document = v2::sign(document.claims, &key).unwrap();
        let mut keys = TrustedLicenseKeys::new();
        keys.insert_scoped(
            document.claims.key_id.clone(),
            key.verifying_key(),
            v2_policy(&document),
        )
        .unwrap();
        (serde_json::to_vec(&document).unwrap(), keys)
    }

    pub(super) fn v2_policy(document: &v2::Document) -> IssuerPolicy {
        let binding = match &document.claims.binding {
            v2::Binding::Unbound {} => BindingKind::Unbound,
            v2::Binding::Installation { .. } => BindingKind::Installation,
        };
        let expiry = match &document.claims.validity.expiry {
            v2::Expiry::Fixed { .. } => ExpiryKind::Fixed,
            v2::Expiry::None {} => ExpiryKind::None,
        };
        let source = match &document.claims.source {
            v2::Source::FreeDistribution { .. } => SourceKind::FreeDistribution,
            v2::Source::CommercialOrder { .. } => SourceKind::CommercialOrder,
            v2::Source::ApprovedTrial { .. } => SourceKind::ApprovedTrial,
        };
        IssuerPolicy {
            sources: vec![source],
            bindings: vec![binding],
            expiries: vec![expiry],
            entitlement_ceiling: document.claims.entitlements.clone(),
        }
    }

