    #[test]
    fn openai_oauth_callback_is_strict_and_error_codes_are_fixed() {
        let parsed = parse_openai_oauth_callback(
            "http://localhost:1455/auth/callback?code=code-1&state=state-1",
        )
        .expect("valid callback");
        assert_eq!(parsed.code, "code-1");
        assert_eq!(parsed.state, "state-1");
        assert!(matches!(
            parse_openai_oauth_callback(
                "http://localhost:1455/auth/callback?code=one&state=a&state=b"
            ),
            Err(ControlError::OAuthSessionInvalid)
        ));
        assert!(matches!(
            parse_openai_oauth_callback(
                "http://attacker.example/auth/callback?code=one&state=state-1"
            ),
            Err(ControlError::OAuthSessionInvalid)
        ));
        let upstream_error = match parse_openai_oauth_callback(
            "http://localhost:1455/auth/callback?error=access_denied&state=state-1",
        ) {
            Err(error) => error,
            Ok(_) => panic!("upstream OAuth error must be rejected"),
        };
        assert_eq!(upstream_error.descriptor().number, 13_009);
        assert_eq!(
            ControlError::OAuthSessionInvalid.descriptor().number,
            13_008
        );
        assert_eq!(ControlError::OAuthSessionBusy.descriptor().number, 13_010);
    }

    #[test]
    fn license_state_io_is_reported_as_local_state_failure() {
        let io_error = ControlError::LicenseState(LicenseStateError::Io);
        assert_eq!(io_error.descriptor().number, 91_008);
        assert_eq!(io_error.status(), StatusCode::SERVICE_UNAVAILABLE);
        let pending = ControlError::LicenseState(LicenseStateError::RecoveryRequired);
        assert_eq!(pending.descriptor().number, 91_008);
        assert_eq!(pending.status(), StatusCode::SERVICE_UNAVAILABLE);
        let conflict = ControlError::LicenseState(LicenseStateError::MutationConflict);
        assert_eq!(conflict.descriptor().number, 91_008);
        assert_eq!(conflict.status(), StatusCode::SERVICE_UNAVAILABLE);

        let integrity_error = ControlError::LicenseState(LicenseStateError::Integrity);
        assert_eq!(integrity_error.descriptor().number, 51_003);
        assert_eq!(integrity_error.status(), StatusCode::FORBIDDEN);
    }

    #[tokio::test]
    async fn licensed_mutation_keeps_its_lease_when_the_http_caller_is_cancelled() {
        let directory = tempdir().unwrap();
        let history = Arc::new(
            LicenseStateStore::new(directory.path().join("state.json"), &[97; 32]).unwrap(),
        );
        let license = verified_license();
        let now = datetime!(2026-08-28 0:00 UTC);
        history.initialize(&license, now).unwrap();
        let guard = history.guard_mutation(Some(&license), None, now).unwrap();
        let (started_tx, started_rx) = oneshot::channel();
        let (finish_tx, finish_rx) = oneshot::channel();
        let (done_tx, done_rx) = oneshot::channel();
        let tasks = Arc::new(tokio::sync::RwLock::new(false));
        let caller = tokio::spawn(finish_licensed_mutation(
            Arc::clone(&tasks),
            guard,
            async move {
                started_tx.send(()).unwrap();
                finish_rx.await.unwrap();
                done_tx.send(()).unwrap();
                Ok(())
            },
        ));
        started_rx.await.unwrap();
        caller.abort();
        assert!(caller.await.unwrap_err().is_cancelled());
        assert!(
            tasks.try_write().is_err(),
            "shutdown must wait for the detached commit"
        );
        assert_eq!(
            history.accept_replacement(&license, now),
            Err(LicenseStateError::MutationConflict)
        );
        finish_tx.send(()).unwrap();
        done_rx.await.unwrap();
        // The inner task releases the lease after its final await returns.
        for _ in 0..100 {
            match history.accept_replacement(&license, now) {
                Ok(()) => return,
                Err(LicenseStateError::MutationConflict) => tokio::task::yield_now().await,
                other => panic!("unexpected replacement result: {other:?}"),
            }
        }
        panic!("completed mutation retained the lease");
    }

    #[cfg(any(feature = "sqlcipher", feature = "sqlite-dev"))]
    #[tokio::test]
    async fn shutdown_drains_a_real_database_commit_after_caller_cancellation() {
        let directory = tempdir().unwrap();
        let history = Arc::new(
            LicenseStateStore::new(directory.path().join("state.json"), &[96; 32]).unwrap(),
        );
        let license = verified_license();
        let now = datetime!(2026-08-28 0:00 UTC);
        history.initialize(&license, now).unwrap();
        let store = Arc::new(StdMutex::new(
            aster_storage::SqlCipherStore::initialize(
                &directory.path().join("customer.db"),
                &[95; 32],
            )
            .unwrap(),
        ));
        let state = ControlState::new("0.1.0", Some(license.clone()))
            .with_license_state(Arc::clone(&history))
            .with_now(now);
        let guard = state
            .guard_licensed_mutation(Some(&license), "gateway")
            .unwrap();
        let (started_tx, started_rx) = oneshot::channel();
        let (finish_tx, finish_rx) = std::sync::mpsc::channel();
        let mutation_store = Arc::clone(&store);
        let caller = tokio::spawn(finish_licensed_mutation(
            Arc::clone(&state.mutation_tasks),
            guard,
            async move {
                tokio::task::spawn_blocking(move || {
                    let store = mutation_store.lock().unwrap();
                    started_tx.send(()).unwrap();
                    finish_rx
                        .recv_timeout(std::time::Duration::from_secs(10))
                        .unwrap();
                    store
                        .insert_upstream_account_unchecked(
                            "account_commit_drain",
                            "openai",
                            "subject_commit_drain",
                            "drain@example.com",
                            "2026-08-28T00:00:00.000Z",
                        )
                        .map_err(ControlError::storage)
                })
                .await
                .map_err(ControlError::storage)?
            },
        ));
        started_rx.await.unwrap();
        caller.abort();
        assert!(caller.await.unwrap_err().is_cancelled());
        let shutdown_state = state.clone();
        let shutdown = tokio::spawn(async move {
            shutdown_state.drain_licensed_mutations().await;
        });
        tokio::task::yield_now().await;
        assert!(!shutdown.is_finished());
        assert_eq!(
            history.accept_replacement(&license, now),
            Err(LicenseStateError::MutationConflict)
        );
        finish_tx.send(()).unwrap();
        tokio::time::timeout(std::time::Duration::from_secs(10), shutdown)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(
            store
                .lock()
                .unwrap()
                .list_upstream_accounts()
                .unwrap()
                .len(),
            1
        );
        history.accept_replacement(&license, now).unwrap();
        let guard = state
            .guard_licensed_mutation(Some(&license), "gateway")
            .unwrap();
        assert!(matches!(
            finish_licensed_mutation::<()>(Arc::clone(&state.mutation_tasks), guard, async {
                panic!("closed server must not begin another transaction");
            })
            .await,
            Err(ControlError::InstanceDraining)
        ));
    }

    #[cfg(any(feature = "sqlcipher", feature = "sqlite-dev"))]
    #[tokio::test]
    async fn member_creation_rechecks_license_after_password_hashing_before_commit() {
        let directory = tempdir().unwrap();
        let history = Arc::new(
            LicenseStateStore::new(directory.path().join("state.json"), &[98; 32]).unwrap(),
        );
        let now = datetime!(2026-08-28 0:00 UTC);
        let old = verified_license();
        let VerifiedProductLicense::V1(old_v1) = &old else {
            panic!("v1 fixture");
        };
        let mut claims = old_v1.claims().clone();
        claims.issued_at = "2026-08-27T00:00:00.000Z".to_owned();
        claims.not_before = claims.issued_at.clone();
        claims.limits.member_seats = 1;
        let key = SigningKey::from_bytes(&[31; 32]);
        let document = sign(claims, &key).unwrap();
        let mut trusted = TrustedLicenseKeys::new();
        trusted
            .insert("license-test-01", key.verifying_key())
            .unwrap();
        let next: VerifiedProductLicense =
            verify_v1(&serde_json::to_vec(&document).unwrap(), &trusted)
                .unwrap()
                .into();
        history.initialize(&old, now).unwrap();
        let store = aster_storage::SqlCipherStore::initialize(
            &directory.path().join("customer.db"),
            &[99; 32],
        )
        .unwrap();
        let mut state = ControlState::new("0.1.0", Some(old))
            .with_storage(ControlStorage::SqlCipher(Arc::new(StdMutex::new(store))))
            .with_license_state(Arc::clone(&history))
            .with_auth_core(AuthCore::new(&[98; 32], "installation-commit-race").unwrap())
            .with_now(now);
        let owner = state
            .initialize_owner_identity(
                "owner@example.com",
                "Owner",
                Zeroizing::new(b"owner-password-strong".to_vec()),
            )
            .await
            .unwrap();
        state
            .reset_admin_password(
                &owner.email,
                Zeroizing::new(b"owner-password-updated".to_vec()),
            )
            .await
            .unwrap();
        let actor = state
            .credential_storage()
            .unwrap()
            .identity_by_id(&owner.id)
            .await
            .unwrap()
            .unwrap();
        let observed = AtomicU64::new(0);
        state.now = Arc::new(move || {
            // First observation authorizes the old License. The next occurs
            // after password hashing but before the real SQL insert.
            if observed.fetch_add(1, Ordering::SeqCst) == 1 {
                history.accept_replacement(&next, now).unwrap();
            }
            now
        });
        let result = state
            .create_member_identity(
                &actor,
                "late@example.com",
                "Late",
                Zeroizing::new(b"member-password-strong".to_vec()),
            )
            .await;
        assert!(matches!(
            result,
            Err(ControlError::LicenseState(
                LicenseStateError::MutationConflict
            ))
        ));
        assert!(
            state
                .credential_storage()
                .unwrap()
                .identity_by_email("late@example.com")
                .await
                .unwrap()
                .is_none()
        );
        assert_eq!(state.verified_occupied_seats().await.unwrap(), 0);
    }

