    #[test]
    fn billing_configuration_uses_exact_decimal_exchange_rate() {
        let configuration: UpdateBillingConfigurationRequest = serde_json::from_value(json!({
            "settlement_currency": "CNY",
            "usd_to_cny": "7.123456789"
        }))
        .expect("deserialize billing configuration");
        let rate = aster_policy_core::billing::Money::parse(
            aster_policy_core::billing::Currency::Cny,
            configuration.usd_to_cny.as_deref().expect("rate"),
        )
        .expect("parse exact rate");
        assert_eq!(rate.nanos, 7_123_456_789);
        assert_eq!(
            billing_configuration_view(&StoredBillingConfiguration {
                settlement_currency: configuration.settlement_currency,
                usd_to_cny_nanos: Some(rate.nanos),
            })["usd_to_cny"],
            "7.123456789"
        );
        assert!(
            serde_json::from_value::<UpdateBillingConfigurationRequest>(json!({
                "settlement_currency": "EUR", "usd_to_cny": null
            }))
            .is_err()
        );
        assert!(
            serde_json::from_value::<UpdateBillingConfigurationRequest>(json!({
                "settlement_currency": "USD", "usd_to_cny": null, "unknown": true
            }))
            .is_err()
        );
    }

    #[test]
    fn money_snapshot_verifies_signed_ledger_chain_and_detects_tampering() {
        let state = ControlState::new("2.2.0", None).with_auth_core(
            AuthCore::new(&[86_u8; 32], "installation-money-chain").expect("auth core"),
        );
        let mut initial = MoneyBalanceRecord {
            identity_id: "member".to_owned(),
            currency: "USD".to_owned(),
            balance_nanos: 0,
            credited_nanos: 0,
            debited_nanos: 0,
            revision: 0,
            last_ledger_hmac: String::new(),
            integrity_hmac: String::new(),
            updated_at: "2026-09-23T00:00:00.000Z".to_owned(),
        };
        initial.integrity_hmac = state.money_balance_integrity_hmac(&initial).unwrap();
        state
            .verify_money_state_snapshot(&MoneyStateSnapshot {
                balance: initial.clone(),
                ledger_entries: Vec::new(),
            })
            .unwrap();

        let mut grant = MoneyLedgerEntry {
            id: "grant-1".to_owned(),
            identity_id: initial.identity_id.clone(),
            currency: initial.currency.clone(),
            kind: "grant".to_owned(),
            amount_nanos: 2_000,
            balance_revision: 1,
            reference_id: "grant:1".to_owned(),
            billing_status: "not_applicable".to_owned(),
            details_json: "{}".to_owned(),
            previous_entry_hmac: String::new(),
            integrity_hmac: String::new(),
            created_at: "2026-09-23T00:01:00.000Z".to_owned(),
        };
        grant.integrity_hmac = state.money_ledger_integrity_hmac(&grant).unwrap();
        let mut balance = MoneyBalanceRecord {
            balance_nanos: 2_000,
            credited_nanos: 2_000,
            revision: 1,
            last_ledger_hmac: grant.integrity_hmac.clone(),
            integrity_hmac: String::new(),
            updated_at: grant.created_at.clone(),
            ..initial
        };
        balance.integrity_hmac = state.money_balance_integrity_hmac(&balance).unwrap();
        let mut snapshot = MoneyStateSnapshot {
            balance,
            ledger_entries: vec![grant],
        };
        state.verify_money_state_snapshot(&snapshot).unwrap();

        snapshot.ledger_entries[0].amount_nanos = 3_000;
        assert!(matches!(
            state.verify_money_state_snapshot(&snapshot),
            Err(ControlError::DataIntegrityInvalid)
        ));
        snapshot.ledger_entries[0].amount_nanos = 2_000;
        snapshot.ledger_entries.clear();
        assert!(matches!(
            state.verify_money_state_snapshot(&snapshot),
            Err(ControlError::DataIntegrityInvalid)
        ));
    }

