    #[cfg(any(feature = "sqlcipher", feature = "sqlite-dev"))]
    #[tokio::test]
    async fn monetary_charge_is_atomic_idempotent_and_can_overdraw() {
        let directory = tempdir().expect("temp directory");
        let store = aster_storage::SqlCipherStore::initialize(
            &directory.path().join("customer.db"),
            &[89_u8; 32],
        )
        .expect("initialize database");
        let state = ControlState::new("2.2.0", None)
            .with_storage(ControlStorage::SqlCipher(Arc::new(StdMutex::new(store))))
            .with_auth_core(
                AuthCore::new(&[90_u8; 32], "installation-money-charge").expect("auth core"),
            )
            .with_now(datetime!(2026-09-23 0:00 UTC));
        let owner = state
            .ensure_owner_identity(
                "owner@example.com",
                "Owner",
                Zeroizing::new(b"owner-password-strong".to_vec()),
            )
            .await
            .expect("initialize owner");
        let storage = state.credential_storage().unwrap();
        let mut setting = RuntimeSettingRecord {
            key: BILLING_CONFIGURATION_KEY.to_owned(),
            value: serde_json::to_string(&StoredBillingConfiguration {
                settlement_currency: BillingSettlementCurrency::Usd,
                usd_to_cny_nanos: None,
            })
            .unwrap(),
            revision: 0,
            integrity_hmac: String::new(),
            updated_at: "2026-09-23T00:00:00.000Z".to_owned(),
        };
        setting.integrity_hmac =
            runtime_setting_integrity_hmac(state.auth_core().unwrap(), &setting).unwrap();
        assert!(matches!(
            storage.write_runtime_setting(None, &setting).await.unwrap(),
            RuntimeSettingWriteOutcome::Applied
        ));
        let granted = state
            .append_money_entry(
                &owner.id,
                "grant",
                1_000,
                "grant:1",
                r#"{"reason":"test"}"#,
                None,
            )
            .await
            .unwrap();
        assert_eq!(granted.balance_nanos, 1_000);
        let charged = state
            .append_money_entry(
                &owner.id,
                "charge",
                -1_500,
                "request:1",
                r#"{"model":"example","usage":{}}"#,
                None,
            )
            .await
            .unwrap();
        assert_eq!(charged.balance_nanos, -500);
        assert_eq!(charged.debited_nanos, 1_500);
        let repeated = state
            .append_money_entry(
                &owner.id,
                "charge",
                -1_500,
                "request:1",
                r#"{"model":"example","usage":{}}"#,
                None,
            )
            .await
            .unwrap();
        assert_eq!(repeated, charged);
        assert!(matches!(
            state
                .append_money_entry(
                    &owner.id,
                    "charge",
                    -1_499,
                    "request:1",
                    r#"{"model":"example","usage":{}}"#,
                    None,
                )
                .await,
            Err(ControlError::DuplicateGatewayRequest)
        ));
        let snapshot = storage
            .money_state_snapshot(&owner.id)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(snapshot.ledger_entries.len(), 2);
        state.verify_money_state_snapshot(&snapshot).unwrap();
    }

    #[cfg(any(feature = "sqlcipher", feature = "sqlite-dev"))]
    #[tokio::test]
    async fn public_model_price_book_round_trips_and_rejects_wrong_identity() {
        use aster_policy_core::billing::plan::{ModelPriceVersion, PriceTier, RateCard};
        use aster_policy_core::billing::schedule::PriceSchedule;
        use aster_policy_core::billing::{Currency, TokenPrices};

        let directory = tempdir().expect("temp directory");
        let store = aster_storage::SqlCipherStore::initialize(
            &directory.path().join("customer.db"),
            &[79_u8; 32],
        )
        .expect("initialize database");
        let state = ControlState::new("2.2.0", None)
            .with_storage(ControlStorage::SqlCipher(Arc::new(StdMutex::new(store))))
            .with_auth_core(
                AuthCore::new(&[80_u8; 32], "installation-billing-prices").expect("auth core"),
            );
        let plan = ModelPriceVersion {
            public_model: "provider/model".to_owned(),
            version: "manual-1".to_owned(),
            currency: Currency::Usd,
            tiers: vec![PriceTier {
                id: "standard".to_owned(),
                schedule: PriceSchedule {
                    base: RateCard::Tokens(TokenPrices {
                        input: Some(1_000_000_000),
                        output: Some(2_000_000_000),
                        ..TokenPrices::default()
                    }),
                    windows: Vec::new(),
                },
            }],
        };
        let book = StoredBillingPriceBook {
            public_model: plan.public_model.clone(),
            active_version: plan.version.clone(),
            versions: vec![StoredBillingPriceVersion {
                plan,
                source: BillingPriceSource::Manual,
                source_url: None,
                verified_at: None,
                saved_at: "2026-09-23T00:00:00.000Z".to_owned(),
            }],
        };
        let mut record = RuntimeSettingRecord {
            key: billing_price_key(&book.public_model),
            value: serde_json::to_string(&book).unwrap(),
            revision: 0,
            integrity_hmac: String::new(),
            updated_at: "2026-09-23T00:00:00.000Z".to_owned(),
        };
        record.integrity_hmac =
            runtime_setting_integrity_hmac(state.auth_core().unwrap(), &record).unwrap();
        assert!(matches!(
            state
                .credential_storage()
                .unwrap()
                .write_runtime_setting(None, &record)
                .await
                .unwrap(),
            RuntimeSettingWriteOutcome::Applied
        ));
        let stored = state
            .credential_storage()
            .unwrap()
            .runtime_setting(&record.key)
            .await
            .unwrap()
            .unwrap();
        let decoded =
            decode_billing_price_book(state.auth_core().unwrap(), &stored, "provider/model")
                .expect("read signed public price");
        assert_eq!(decoded.active_version, "manual-1");
        assert!(matches!(
            decode_billing_price_book(state.auth_core().unwrap(), &stored, "other/model"),
            Err(ControlError::DataIntegrityInvalid)
        ));
        let mut tampered = stored;
        tampered.value = tampered.value.replace("1000000000", "1");
        assert!(matches!(
            decode_billing_price_book(state.auth_core().unwrap(), &tampered, "provider/model",),
            Err(ControlError::DataIntegrityInvalid)
        ));
    }

    #[test]
    fn official_builtin_prices_are_available_without_an_admin_setting() {
        for model in [
            "gpt-5.5",
            "gpt-5.6-sol",
            "gpt-5.6-terra",
            "gpt-5.6-luna",
            "gpt-6-astra",
            "gpt-6-sol",
            "gpt-6-luna",
        ] {
            let book = builtin_billing_price_book(model).expect("verified default price");
            assert_eq!(book.public_model, model);
            assert_eq!(book.versions.len(), 1);
            assert_eq!(book.active_version, book.versions[0].plan.version);
            assert!(matches!(
                book.versions[0].source,
                BillingPriceSource::Builtin
            ));
            book.versions[0]
                .plan
                .validate()
                .expect("valid default price");
            let preview = admin_model_price_preview(&book.versions[0]);
            assert_eq!(preview["currency"], "USD");
            assert_eq!(preview["rate"]["kind"], "context_tokens");
            assert_eq!(preview["has_other_prices"], false);
        }
        assert!(builtin_billing_price_book("codex-auto-review").is_none());
        assert!(builtin_billing_price_book("gpt-image-2").is_none());
    }

    #[test]
    fn session_cookie_security_matches_the_configured_public_protocol() {
        let https = session_cookie(PrincipalKind::Admin, "secret", 60, true)
            .expect("HTTPS session cookie")
            .to_str()
            .expect("HTTPS cookie text")
            .to_owned();
        let http = session_cookie(PrincipalKind::Admin, "secret", 60, false)
            .expect("HTTP session cookie")
            .to_str()
            .expect("HTTP cookie text")
            .to_owned();
        assert!(https.contains("; Secure"));
        assert!(!http.contains("; Secure"));
        assert!(http.contains("; HttpOnly"));
        assert!(http.contains("; SameSite=Lax"));
    }

