    #[test]
    fn logical_usage_entries_group_only_matching_client_key_and_identity() {
        fn usage_entry(
            id: &str,
            identity_id: &str,
            api_key_id: &str,
            reference_id: &str,
            client_request_id: Option<&str>,
            created_at: &str,
            succeeded: bool,
        ) -> QuotaLedgerEntry {
            let tokens = i64::from(succeeded) * 5;
            QuotaLedgerEntry {
                id: id.to_owned(),
                identity_id: identity_id.to_owned(),
                kind: if succeeded { "usage" } else { "usage_failed" }.to_owned(),
                amount_tokens: -tokens,
                uncached_input: tokens.saturating_sub(1),
                cached_input: 0,
                cache_write: 0,
                output_tokens: i64::from(succeeded),
                uncovered_tokens: 0,
                raw_tokens: tokens,
                billed_tokens: tokens,
                multiplier_micros: 1_000_000,
                reference_id: reference_id.to_owned(),
                client_request_id: client_request_id.map(str::to_owned),
                description: if succeeded {
                    "API 请求".to_owned()
                } else {
                    "upstream_request_failed: 上游请求执行失败".to_owned()
                },
                protocol: "openai_responses".to_owned(),
                model: "gpt-test".to_owned(),
                requested_model: Some("gpt-test-fast".to_owned()),
                processing_tier: Some("fast".to_owned()),
                reasoning_effort: Some("high".to_owned()),
                api_key_id: Some(api_key_id.to_owned()),
                runner_id: Some("runner-test".to_owned()),
                previous_entry_hmac: String::new(),
                integrity_hmac: "test-hmac".to_owned(),
                created_at: created_at.to_owned(),
            }
        }

        let entries = vec![
            usage_entry(
                "ledger-failed-1",
                "identity-a",
                "key-a",
                "request-a1",
                Some("client-shared-001"),
                "2026-09-07T00:00:00.000Z",
                false,
            ),
            usage_entry(
                "ledger-failed-2",
                "identity-a",
                "key-a",
                "request-a2",
                Some("client-shared-001"),
                "2026-09-07T00:00:01.000Z",
                false,
            ),
            usage_entry(
                "ledger-success",
                "identity-a",
                "key-a",
                "request-a3",
                Some("client-shared-001"),
                "2026-09-07T00:00:02.000Z",
                true,
            ),
            usage_entry(
                "ledger-no-client-1",
                "identity-a",
                "key-a",
                "request-no-client-1",
                None,
                "2026-09-07T00:00:03.000Z",
                false,
            ),
            usage_entry(
                "ledger-no-client-2",
                "identity-a",
                "key-a",
                "request-no-client-2",
                None,
                "2026-09-07T00:00:04.000Z",
                false,
            ),
            usage_entry(
                "ledger-other-key",
                "identity-a",
                "key-b",
                "request-b1",
                Some("client-shared-001"),
                "2026-09-07T00:00:05.000Z",
                false,
            ),
            usage_entry(
                "ledger-other-identity",
                "identity-b",
                "key-a",
                "request-c1",
                Some("client-shared-001"),
                "2026-09-07T00:00:06.000Z",
                false,
            ),
        ];

        let logical = logical_usage_entries(entries).expect("group logical requests");
        assert_eq!(logical.len(), 5);
        let retried = logical
            .iter()
            .find(|entry| {
                entry.ledger.identity_id == "identity-a"
                    && entry.ledger.api_key_id.as_deref() == Some("key-a")
                    && entry.ledger.client_request_id.as_deref() == Some("client-shared-001")
            })
            .expect("retried logical request");
        assert_eq!(retried.attempt_count, 3);
        assert_eq!(retried.ledger.kind, "usage");
        assert_eq!(retried.ledger.raw_tokens, 5);
        assert_eq!(retried.ledger.reference_id, "request-a3");
    }

    #[cfg(any(feature = "sqlcipher", feature = "sqlite-dev"))]
    #[tokio::test]
    async fn quota_grant_reservation_and_usage_settlement_are_atomic_and_tamper_evident() {
        let directory = tempdir().expect("temp directory");
        let database_path = directory.path().join("customer.db");
        let auth = AuthCore::new(&[101_u8; 32], "installation-test-001").expect("auth core");
        let now = "2026-08-28T00:00:00.000Z".to_owned();
        let mut identity = IdentityRecord {
            id: "identity_quota".to_owned(),
            email: "quota@example.com".to_owned(),
            display_name: "Quota Member".to_owned(),
            password_hash: auth
                .hash_password(b"quota-password-strong")
                .expect("password hash"),
            role: "member".to_owned(),
            status: "active".to_owned(),
            can_consume_model: true,
            password_change_required: false,
            revision: 0,
            integrity_hmac: String::new(),
            created_at: now.clone(),
            updated_at: now.clone(),
        };
        identity.integrity_hmac = auth
            .identity_integrity_hmac(identity_integrity_input(&identity))
            .expect("identity integrity");
        let setup_state = ControlState::new("0.1.0", None).with_auth_core(auth.clone());
        let seat_value = encode_seat_registry(std::slice::from_ref(&identity.id));
        let seat_state = SecurityStateRecord {
            key: MEMBER_SEAT_REGISTRY_KEY.to_owned(),
            value: seat_value.clone(),
            revision: 0,
            mac: auth
                .security_state_integrity_hmac(SecurityStateIntegrityInput {
                    key: MEMBER_SEAT_REGISTRY_KEY,
                    value: &seat_value,
                    revision: 0,
                })
                .expect("seat state integrity")
                .into_bytes(),
            updated_at: now.clone(),
        };
        let initial_balance = setup_state
            .initial_balance_record(&identity.id, &now)
            .expect("initial balance");
        let mut store = aster_storage::SqlCipherStore::initialize(&database_path, &[100_u8; 32])
            .expect("initialize SQLCipher");
        assert_eq!(
            store
                .initialize_first_owner(&identity, &seat_state, &initial_balance)
                .expect("initialize identity"),
            IdentityInitializeOutcome::Created
        );
        let quota_test_secret = auth.issue_api_key().unwrap();
        let mut quota_test_key = ApiKeyRecord {
            id: "key_quota".to_owned(),
            identity_id: identity.id.clone(),
            name: "quota test".to_owned(),
            key_hash: quota_test_secret.digest().to_owned(),
            key_prefix: quota_test_secret.prefix().to_owned(),
            status: "active".to_owned(),
            revision: 0,
            integrity_hmac: String::new(),
            created_at: now.clone(),
            last_used_at: None,
        };
        quota_test_key.integrity_hmac = auth
            .api_key_integrity_hmac(api_key_integrity_input(&quota_test_key))
            .unwrap();
        store
            .insert_api_key_unchecked(&quota_test_key)
            .expect("insert API key");
        let state = setup_state
            .with_storage(ControlStorage::SqlCipher(Arc::new(StdMutex::new(store))))
            .with_now(datetime!(2026-08-28 0:00 UTC));

        state
            .grant_model_quota(&identity.id, "grant-001", 1_000, "initial grant")
            .await
            .expect("grant quota");
        assert!(matches!(
            state
                .grant_model_quota(&identity.id, "grant-001", 1_000, "duplicate grant")
                .await,
            Err(ControlError::QuotaGrantDuplicate)
        ));
        assert_eq!(
            ControlError::QuotaGrantDuplicate.descriptor().number,
            12_012
        );

        let mut reservation = state
            .reserve_mock_model_quota(&identity.id, "key_quota", "request-001", 700)
            .await
            .expect("reserve quota");
        reservation.client_request_id = Some("client-logical-success-001".to_owned());
        assert!(matches!(
            state
                .reserve_mock_model_quota(&identity.id, "key_quota", "request-002", 400)
                .await,
            Err(ControlError::InsufficientQuota)
        ));
        assert_eq!(ControlError::InsufficientQuota.descriptor().number, 34_001);
        let settlement = state
            .settle_model_quota(
                &reservation,
                &ModelUsage {
                    uncached_input: 300,
                    cached_input: 0,
                    cache_write: 0,
                    output_tokens: 100,
                    multiplier_micros: 1_500_000,
                    protocol: "openai".to_owned(),
                    model: "gpt-test".to_owned(),
                    requested_model: Some("gpt-test-fast-high".to_owned()),
                    processing_tier: Some("fast".to_owned()),
                    reasoning_effort: Some("high".to_owned()),
                    runner_id: "runner-01".to_owned(),
                },
            )
            .await
            .expect("settle usage");
        assert_eq!(settlement.charged_tokens, 600);
        assert_eq!(settlement.billed_tokens, 600);
        assert_eq!(settlement.uncovered_tokens, 0);
        let snapshot = state
            .verified_quota_snapshot(&identity.id)
            .await
            .expect("verified quota state");
        assert_eq!(snapshot.balance.balance_tokens, 400);
        assert_eq!(snapshot.balance.reserved_tokens, 0);
        assert_eq!(snapshot.balance.granted_tokens, 1_000);
        assert_eq!(snapshot.balance.consumed_tokens, 600);
        assert_eq!(snapshot.ledger_entries.len(), 2);
        let usage_entry = snapshot
            .ledger_entries
            .iter()
            .find(|entry| entry.kind == "usage")
            .expect("usage ledger entry");
        assert_eq!(usage_entry.model, "gpt-test");
        assert_eq!(
            usage_entry.requested_model.as_deref(),
            Some("gpt-test-fast-high")
        );
        assert_eq!(usage_entry.processing_tier.as_deref(), Some("fast"));
        assert_eq!(usage_entry.reasoning_effort.as_deref(), Some("high"));
        assert_eq!(
            usage_entry.client_request_id.as_deref(),
            Some("client-logical-success-001")
        );

        let mut failed_reservation = state
            .reserve_mock_model_quota(&identity.id, "key_quota", "request-failed", 100)
            .await
            .expect("reserve quota for failed request");
        failed_reservation.client_request_id = Some("client-logical-failure-001".to_owned());
        state
            .fail_model_request(
                &failed_reservation,
                &FailedModelRequest {
                    protocol: "openai_responses".to_owned(),
                    model: "gpt-test".to_owned(),
                    requested_model: Some("gpt-test-fast-high".to_owned()),
                    processing_tier: Some("fast".to_owned()),
                    reasoning_effort: Some("high".to_owned()),
                    runner_id: Some("runner-01".to_owned()),
                    description: "upstream_request_failed: 上游请求执行失败".to_owned(),
                },
            )
            .await
            .expect("record failed request without charge");
        let snapshot = state
            .verified_quota_snapshot(&identity.id)
            .await
            .expect("quota after failed request");
        assert_eq!(snapshot.balance.balance_tokens, 400);
        assert_eq!(snapshot.balance.consumed_tokens, 600);
        assert_eq!(snapshot.balance.reserved_tokens, 0);
        let failure_entry = snapshot
            .ledger_entries
            .iter()
            .find(|entry| entry.kind == "usage_failed")
            .expect("failed request ledger entry");
        assert_eq!(failure_entry.reference_id, "request-failed");
        assert_eq!(failure_entry.amount_tokens, 0);
        assert_eq!(failure_entry.raw_tokens, 0);
        assert_eq!(failure_entry.billed_tokens, 0);
        assert_eq!(failure_entry.processing_tier.as_deref(), Some("fast"));
        assert_eq!(failure_entry.reasoning_effort.as_deref(), Some("high"));
        assert_eq!(
            failure_entry.client_request_id.as_deref(),
            Some("client-logical-failure-001")
        );
        assert_eq!(
            filter_member_usage_entries_in_window(
                &snapshot.ledger_entries,
                None,
                None,
                None,
                false,
            )
            .expect("filter summary usage")
            .len(),
            1
        );
        assert_eq!(
            filter_member_usage_entries_in_window(
                &snapshot.ledger_entries,
                None,
                None,
                None,
                true,
            )
            .expect("filter consumption logs")
            .len(),
            2
        );

        let releasable = state
            .reserve_mock_model_quota(&identity.id, "key_quota", "request-003", 300)
            .await
            .expect("reserve releasable quota");
        state
            .release_model_quota(&releasable)
            .await
            .expect("release quota");
        assert_eq!(
            state
                .verified_quota_snapshot(&identity.id)
                .await
                .expect("quota after release")
                .balance
                .reserved_tokens,
            0
        );

        // Simulate an rc.1 reservation that already used a client tracking ID.
        let client_id = "01a06bea-7368-77b2-9503-677bc5b68235";
        let legacy = state
            .reserve_mock_model_quota(&identity.id, "key_quota", client_id, 1)
            .await
            .expect("legacy reservation");
        state
            .release_model_quota(&legacy)
            .await
            .expect("release legacy");
        for header in ["x-client-request-id", "x-request-id"] {
            let mut headers = HeaderMap::new();
            headers.insert(header, HeaderValue::from_static(client_id));
            let mut reservations = Vec::new();
            for _ in 0..2 {
                let request_id = gateway_request_id(&headers).expect("fresh gateway ID");
                let reservation = state
                    .reserve_mock_model_quota(&identity.id, "key_quota", &request_id, 1)
                    .await
                    .expect("reused client ID must allow independent active reservations");
                assert!(matches!(
                    state
                        .reserve_mock_model_quota(&identity.id, "key_quota", &request_id, 1)
                        .await,
                    Err(ControlError::DuplicateGatewayRequest)
                ));
                reservations.push(reservation);
            }
            let usage = ModelUsage {
                uncached_input: 0,
                cached_input: 0,
                cache_write: 0,
                output_tokens: 1,
                multiplier_micros: 1_000_000,
                protocol: "openai".to_owned(),
                model: "gpt-test".to_owned(),
                requested_model: None,
                processing_tier: None,
                reasoning_effort: None,
                runner_id: "runner-01".to_owned(),
            };
            for reservation in &reservations {
                state
                    .settle_model_quota(reservation, &usage)
                    .await
                    .expect("settle once");
                assert!(matches!(
                    state.settle_model_quota(reservation, &usage).await,
                    Err(ControlError::QuotaSettlementConflict)
                ));
                let committed = state.verified_quota_snapshot(&identity.id).await.unwrap();
                gateway::durable_settlement::complete(
                    &state,
                    reservation,
                    gateway::durable_settlement::Outcome::Usage(usage.clone()),
                )
                .await
                .expect("recover a lost acknowledgement from authenticated usage");
                assert_eq!(
                    state.verified_quota_snapshot(&identity.id).await.unwrap(),
                    committed
                );
            }
            let retry_id = gateway_request_id(&headers).expect("retry gateway ID");
            let retry = state
                .reserve_mock_model_quota(&identity.id, "key_quota", &retry_id, 1)
                .await
                .expect("client ID can be reused after settlement");
            state
                .release_model_quota(&retry)
                .await
                .expect("release retry");
        }
        let snapshot = state
            .verified_quota_snapshot(&identity.id)
            .await
            .expect("verified ledger");
        assert_eq!(snapshot.balance.balance_tokens, 396);
        assert_eq!(snapshot.balance.consumed_tokens, 604);
        assert_eq!(snapshot.balance.reserved_tokens, 0);
        assert_eq!(snapshot.ledger_entries.len(), 7);

        let tamper_connection =
            rusqlite::Connection::open(&database_path).expect("open database for tamper test");
        #[cfg(feature = "sqlcipher")]
        tamper_connection
            .execute_batch(&format!("PRAGMA key=\"x'{}'\";", "64".repeat(32)))
            .expect("unlock SQLCipher tamper test");
        tamper_connection
            .execute(
                "UPDATE ledger_entries SET description='forged' WHERE reference_id='grant-001'",
                [],
            )
            .expect("tamper ledger");
        assert!(matches!(
            state.verified_quota_snapshot(&identity.id).await,
            Err(ControlError::DataIntegrityInvalid)
        ));
    }

    #[cfg(any(feature = "sqlcipher", feature = "sqlite-dev"))]
    #[tokio::test]
    async fn credential_refresh_lease_is_per_instance_and_commit_is_revision_guarded() {
        let directory = tempdir().expect("temp directory");
        let store = aster_storage::SqlCipherStore::initialize(
            &directory.path().join("customer.db"),
            &[90_u8; 32],
        )
        .expect("initialize SQLCipher");
        store
            .insert_upstream_account_unchecked(
                "account_1",
                "openai",
                "subject_1",
                "owner@example.com",
                "2026-08-28T00:00:00.000Z",
            )
            .expect("insert account");
        let state = ControlState::new("0.1.0", None)
            .with_storage(ControlStorage::SqlCipher(Arc::new(StdMutex::new(store))))
            .with_credential_vault(
                CredentialVault::new(&[91_u8; 32], "installation-test-001")
                    .expect("credential vault"),
            )
            .with_now(datetime!(2026-08-28 0:00 UTC));
        let first_id = state
            .create_credential_instance(
                "account_1",
                b"refresh-token-a",
                br#"{"refresh_token":"refresh-token-a","access_token":"access-a"}"#,
                "2026-08-28T01:00:00.000Z",
            )
            .await
            .expect("create first credential");
        let second_id = state
            .create_credential_instance(
                "account_1",
                b"refresh-token-b",
                br#"{"refresh_token":"refresh-token-b","access_token":"access-b"}"#,
                "2026-08-28T01:00:00.000Z",
            )
            .await
            .expect("create second credential");

        let first_lease = state
            .begin_credential_refresh(&first_id)
            .await
            .expect("acquire first lease");
        assert!(matches!(
            state.begin_credential_refresh(&first_id).await,
            Err(ControlError::CredentialRefreshBusy)
        ));
        let second_lease = state
            .begin_credential_refresh(&second_id)
            .await
            .expect("a different credential instance can refresh concurrently");

        state
            .commit_credential_refresh(
                &first_id,
                first_lease.credential.credential_revision,
                first_lease.lease_token.as_str(),
                b"refresh-token-a-next",
                br#"{"refresh_token":"refresh-token-a-next","access_token":"access-a-next"}"#,
                "2026-08-28T02:00:00.000Z",
            )
            .await
            .expect("commit first refresh");
        assert!(matches!(
            state
                .commit_credential_refresh(
                    &first_id,
                    0,
                    first_lease.lease_token.as_str(),
                    b"refresh-token-a-stale",
                    br#"{"refresh_token":"refresh-token-a-stale"}"#,
                    "2026-08-28T03:00:00.000Z",
                )
                .await,
            Err(ControlError::CredentialRefreshConflict)
        ));
        let refreshed = state
            .decrypt_credential_instance(&first_id)
            .await
            .expect("decrypt refreshed credential");
        assert_eq!(refreshed.credential_revision, 1);
        assert_eq!(
            refreshed.plaintext_payload.as_slice(),
            br#"{"refresh_token":"refresh-token-a-next","access_token":"access-a-next"}"#
        );
        state
            .cancel_credential_refresh(&second_id, second_lease.lease_token.as_str())
            .await
            .expect("cancel independent second lease");
        assert!(matches!(
            state
                .cancel_credential_refresh(&second_id, second_lease.lease_token.as_str())
                .await,
            Err(ControlError::CredentialRefreshLeaseInvalid)
        ));

        let claims = encode_base64url(
            br#"{"https://api.openai.com/auth":{"chatgpt_account_id":"upstream-subject-3","chatgpt_plan_type":"team"},"email":"owner@example.com"}"#,
        );
        let old_access_token = format!("header.{claims}.signature");
        let initial_payload = serde_json::to_vec(&OpenAiCredentialPayload {
            schema: OPENAI_CREDENTIAL_SCHEMA.to_owned(),
            provider: "openai".to_owned(),
            access_token: old_access_token,
            refresh_token: "refresh-token-c".to_owned(),
            id_token: String::new(),
            expires_at: "2026-08-28T01:00:00.000Z".to_owned(),
            account_id: "upstream-subject-3".to_owned(),
            email: "owner@example.com".to_owned(),
            plan: "team".to_owned(),
        })
        .expect("encode final credential payload");
        let third_id = state
            .create_credential_instance(
                "account_1",
                b"refresh-token-c",
                &initial_payload,
                "2026-08-28T01:00:00.000Z",
            )
            .await
            .expect("create final-schema credential");
        let third_lease = state
            .begin_credential_refresh(&third_id)
            .await
            .expect("acquire final-schema credential lease");
        let next_access_token = format!("header.{claims}.next-signature");
        let response_body = serde_json::to_vec(&json!({
            "access_token": next_access_token,
            "refresh_token": "refresh-token-c-next",
            "expires_in": 7200
        }))
        .expect("encode upstream token response");
        state
            .commit_openai_refresh_result(
                &third_lease,
                decode_openai_credential(&third_lease.credential.plaintext_payload)
                    .expect("decode leased credential"),
                CredentialRefreshResult {
                    task_id: "task_refresh_credential_3".to_owned(),
                    credential_id: third_id.clone(),
                    expected_revision: 0,
                    status: 200,
                    credential_payload_base64url: encode_base64url(&response_body),
                },
            )
            .await
            .expect("validate and commit Runner refresh result");
        let third_refreshed = state
            .decrypt_credential_instance(&third_id)
            .await
            .expect("decrypt final-schema refreshed credential");
        let third_payload = decode_openai_credential(&third_refreshed.plaintext_payload)
            .expect("decode final-schema refreshed credential");
        assert_eq!(third_refreshed.credential_revision, 1);
        assert_eq!(third_payload.refresh_token, "refresh-token-c-next");
        assert_eq!(third_payload.expires_at, "2026-08-28T02:00:00.000Z");
    }

