    #[tokio::test]
    async fn dispatch_signs_routes_and_correlates_a_runner_task() {
        let directory = tempdir().expect("temp directory");
        let license = verified_license();
        let license_state = Arc::new(
            LicenseStateStore::new(directory.path().join("state.json"), &[51_u8; 32])
                .expect("create license state"),
        );
        license_state
            .initialize(&license, datetime!(2026-08-27 0:00 UTC))
            .expect("initialize license state");
        let signing_key = SigningKey::from_bytes(&[82_u8; 32]);
        let runner = RunnerRecord {
            id: "runner-dispatch-001".to_owned(),
            enabled: true,
            version: "0.1.0".to_owned(),
            protocol_version: RUNNER_PROTOCOL_VERSION,
            max_inflight: 4,
            inflight: 0,
            recent_request_count: 0,
            recent_error_count: 0,
            latency_ms: 10,
            last_seen_at: Some("2026-08-28T00:00:00.000Z".to_owned()),
        };
        let state = ControlState::new("0.1.0", Some(license))
            .with_test_runners(3, vec![runner.clone()])
            .with_license_state(license_state)
            .with_task_issuer(RunnerTaskIssuer::new(
                "runner-task-test-01",
                signing_key.clone(),
            ))
            .with_now(datetime!(2026-08-28 0:00:01 UTC));
        let (generation, mut outbound) = state.runner_hub.register(&runner.id).await;
        let payload = serde_json::to_vec(&UpstreamHttpRequest {
            method: "GET".to_owned(),
            url: OPENAI_CODEX_MODELS_ENDPOINT.to_owned(),
            headers: vec![],
            body_base64url: String::new(),
        })
        .unwrap();
        let mut handle = state
            .dispatch_runner_task(
                None,
                &RunnerTaskBinding::credential(
                    "openai",
                    "credential_00000000000000000000000000000001",
                    0,
                    "chatgpt.com",
                ),
                RunnerTaskAuthorization::DiscoverModels {
                    actor: None,
                    credential: &transport_credential_fixture(),
                },
                &payload,
            )
            .await
            .expect("dispatch task");
        assert_eq!(handle.runner_id, runner.id);
        let encoded = outbound.recv().await.expect("outbound task frame");
        let frame = decode_control_frame(&encoded).expect("decode task frame");
        let ControlToRunner::Task(frame) = frame else {
            panic!("expected task frame");
        };
        let ticket_json =
            decode_base64url(&frame.ticket_json_base64url).expect("decode task ticket");
        assert_eq!(
            decode_base64url(&frame.payload_base64url).expect("decode task payload"),
            payload
        );
        let mut keys = TrustedTaskKeys::new();
        keys.insert("runner-task-test-01", signing_key.verifying_key())
            .expect("insert task key");
        let verified = verify_task_ticket(
            &ticket_json,
            &keys,
            &runner.id,
            &payload,
            datetime!(2026-08-28 0:00:01 UTC),
        )
        .expect("verify dispatched ticket");
        assert_eq!(verified.claims().task_id, handle.task_id);

        state
            .runner_hub
            .publish(RunnerToControl::TaskAccepted(TaskLifecycle {
                task_id: handle.task_id.clone(),
            }))
            .await;
        assert!(matches!(
            handle.recv().await,
            Some(RunnerToControl::TaskAccepted(_))
        ));
        state.runner_hub.unregister(&runner.id, generation).await;
    }

    #[test]
    fn openai_response_stream_requires_a_completed_event_with_valid_usage() {
        let body = concat!(
            "event: response.output_text.delta\n",
            "data: {\"type\":\"response.output_text.delta\",\"delta\":\"hello\"}\n\n",
            "event: response.completed\n",
            "data: {\"type\":\"response.completed\",\"response\":{\"id\":\"resp_1\",",
            "\"model\":\"gpt-upstream\",\"usage\":{\"input_tokens\":100,",
            "\"output_tokens\":20,\"input_tokens_details\":{\"cached_tokens\":40,",
            "\"cache_write_tokens\":5}}}}\n\n"
        );
        let (response, usage) =
            parse_openai_response_stream(body.as_bytes()).expect("parse completed response");
        assert_eq!(response["id"], "resp_1");
        assert_eq!(usage.uncached_input, 55);
        assert_eq!(usage.cached_input, 40);
        assert_eq!(usage.cache_write, 5);
        assert_eq!(usage.output_tokens, 20);
        assert!(matches!(
            parse_openai_response_stream(
                b"data: {\"type\":\"response.completed\",\"response\":{}}\n\n"
            ),
            Err(ControlError::UpstreamUsageInvalid)
        ));
        let mut framed = body.as_bytes().to_vec();
        let first = take_sse_frame(&mut framed).expect("first SSE frame");
        assert!(!sse_frame_is_terminal(&first));
        let second = take_sse_frame(&mut framed).expect("completed SSE frame");
        assert!(sse_frame_is_terminal(&second));
    }

    #[test]
    fn chat_and_anthropic_protocols_convert_to_one_responses_shape() {
        let chat = vec![
            json!({"role":"system","content":"be precise"}),
            json!({"role":"user","content":[{"type":"text","text":"hello"}]}),
            json!({"role":"assistant","content":null,"tool_calls":[{"id":"call_1","type":"function","function":{"name":"lookup","arguments":"{\"id\":1}"}}]}),
            json!({"role":"tool","tool_call_id":"call_1","content":"done"}),
        ];
        let chat = gateway::chat::ChatProtocolAdapter::decode(
            &serde_json::to_vec(&json!({"model":"gpt","messages":chat})).unwrap(),
        )
        .expect("convert chat messages");
        let input = chat.canonical["input"].as_array().unwrap();
        assert_eq!(chat.canonical["instructions"], "be precise");
        assert_eq!(input[0]["role"], "user");
        assert_eq!(input[1]["type"], "function_call");
        assert_eq!(input[2]["type"], "function_call_output");

        let anthropic = vec![
            json!({"role":"user","content":[{"type":"text","text":"hello"}]}),
            json!({"role":"assistant","content":[{"type":"tool_use","id":"toolu_1","name":"lookup","input":{"id":1}}]}),
            json!({"role":"user","content":[{"type":"tool_result","tool_use_id":"toolu_1","content":"done"}]}),
        ];
        let anthropic = gateway::anthropic::AnthropicProtocolAdapter::decode(
            &serde_json::to_vec(&json!({"model":"gpt","max_tokens":100,"messages":anthropic}))
                .unwrap(),
        )
        .expect("convert Anthropic messages");
        let input = anthropic.canonical["input"].as_array().unwrap();
        assert_eq!(input[0]["role"], "user");
        assert_eq!(input[1]["type"], "function_call");
        assert_eq!(input[2]["type"], "function_call_output");

        let response = json!({
            "output":[
                {"type":"message","content":[{"type":"output_text","text":"answer"}]},
                {"type":"function_call","call_id":"call_2","name":"save","arguments":"{\"ok\":true}"}
            ]
        });
        let (text, calls) =
            gateway::protocol::canonical_output(&response).expect("convert canonical output");
        assert_eq!(text, "answer");
        assert_eq!(calls[0]["function"]["name"], "save");
    }

