    #[tokio::test]
    async fn runner_execution_switches_once_only_before_upstream_start() {
        let directory = tempdir().expect("temp directory");
        let license = verified_license();
        let license_state = Arc::new(
            LicenseStateStore::new(directory.path().join("state.json"), &[121_u8; 32])
                .expect("create license state"),
        );
        license_state
            .initialize(&license, datetime!(2026-08-27 0:00 UTC))
            .expect("initialize license state");
        let runner = |id: &str| RunnerRecord {
            id: id.to_owned(),
            enabled: true,
            version: "0.1.0".to_owned(),
            protocol_version: RUNNER_PROTOCOL_VERSION,
            max_inflight: 4,
            inflight: 0,
            recent_request_count: 0,
            recent_error_count: 0,
            latency_ms: 10,
            last_seen_at: Some("2026-08-28T00:00:00.000Z".to_owned()),
        };
        let first = runner("runner-failover-001");
        let second = runner("runner-failover-002");
        let state = ControlState::new("0.1.0", Some(license))
            .with_test_runners(1, vec![first.clone(), second.clone()])
            .with_license_state(license_state)
            .with_task_issuer(RunnerTaskIssuer::new(
                "runner-task-test-03",
                SigningKey::from_bytes(&[122_u8; 32]),
            ))
            .with_now(datetime!(2026-08-28 0:00:01 UTC));
        let (first_generation, mut first_outbound) = state.runner_hub.register(&first.id).await;
        let (second_generation, mut second_outbound) = state.runner_hub.register(&second.id).await;
        let request = UpstreamHttpRequest {
            method: "GET".to_owned(),
            url: OPENAI_CODEX_MODELS_ENDPOINT.to_owned(),
            headers: vec![],
            body_base64url: String::new(),
        };
        let executing_state = state.clone();
        let first_runner_id = first.id.clone();
        let execution = tokio::spawn(async move {
            let binding = RunnerTaskBinding::credential(
                "openai",
                "credential_00000000000000000000000000000001",
                0,
                "chatgpt.com",
            );
            executing_state
                .execute_runner_http_request_with_command(
                    Some(&first_runner_id),
                    &binding,
                    RunnerTaskAuthorization::DiscoverModels {
                        actor: None,
                        credential: &transport_credential_fixture(),
                    },
                    &request,
                )
                .await
        });
        let first_frame = first_outbound.recv().await.expect("first Runner task");
        let ControlToRunner::Task(first_frame) =
            decode_control_frame(&first_frame).expect("decode first task")
        else {
            panic!("expected first task");
        };
        let first_ticket: Value = serde_json::from_slice(
            &decode_base64url(&first_frame.ticket_json_base64url).expect("first ticket"),
        )
        .expect("first ticket JSON");
        let first_task_id = first_ticket["task_id"]
            .as_str()
            .expect("first task id")
            .to_owned();
        state
            .runner_hub
            .publish(RunnerToControl::TaskAccepted(TaskLifecycle {
                task_id: first_task_id.clone(),
            }))
            .await;
        state
            .runner_hub
            .publish(RunnerToControl::TaskFailed(
                aster_runner_protocol::TaskFailure {
                    task_id: first_task_id,
                    category: "runner_disconnected".to_owned(),
                    retryable_before_upstream: true,
                },
            ))
            .await;

        let second_frame = second_outbound.recv().await.expect("failover Runner task");
        let ControlToRunner::Task(second_frame) =
            decode_control_frame(&second_frame).expect("decode second task")
        else {
            panic!("expected second task");
        };
        let second_ticket: Value = serde_json::from_slice(
            &decode_base64url(&second_frame.ticket_json_base64url).expect("second ticket"),
        )
        .expect("second ticket JSON");
        let second_task_id = second_ticket["task_id"]
            .as_str()
            .expect("second task id")
            .to_owned();
        state
            .runner_hub
            .publish(RunnerToControl::TaskAccepted(TaskLifecycle {
                task_id: second_task_id.clone(),
            }))
            .await;
        state
            .runner_hub
            .publish(RunnerToControl::UpstreamStarted(TaskLifecycle {
                task_id: second_task_id.clone(),
            }))
            .await;
        state
            .runner_hub
            .publish(RunnerToControl::TaskResponseStarted(
                aster_runner_protocol::TaskResponseStarted {
                    task_id: second_task_id.clone(),
                    status: 200,
                    headers: vec![],
                },
            ))
            .await;
        state
            .runner_hub
            .publish(RunnerToControl::TaskChunk(
                aster_runner_protocol::TaskChunk {
                    task_id: second_task_id.clone(),
                    sequence: 0,
                    data_base64url: encode_base64url(b"ok"),
                },
            ))
            .await;
        state
            .runner_hub
            .publish(RunnerToControl::TaskFinished(
                aster_runner_protocol::TaskResult {
                    task_id: second_task_id,
                    status: 200,
                    usage_json: None,
                },
            ))
            .await;
        let response = execution
            .await
            .expect("execution join")
            .expect("failover response");
        assert_eq!(response.runner_id, second.id);
        assert_eq!(response.body, b"ok");
        let lost_state = state.clone();
        let lost_runner = first.id.clone();
        let lost_execution = tokio::spawn(async move {
            let binding = RunnerTaskBinding::credential(
                "openai",
                "credential_00000000000000000000000000000001",
                0,
                "chatgpt.com",
            );
            let request = UpstreamHttpRequest {
                method: "GET".into(),
                url: OPENAI_CODEX_MODELS_ENDPOINT.into(),
                headers: vec![],
                body_base64url: String::new(),
            };
            lost_state
                .execute_runner_http_request_with_command(
                    Some(&lost_runner),
                    &binding,
                    RunnerTaskAuthorization::DiscoverModels {
                        actor: None,
                        credential: &transport_credential_fixture(),
                    },
                    &request,
                )
                .await
        });
        first_outbound
            .recv()
            .await
            .expect("task before connection loss");
        state
            .runner_hub
            .unregister(&first.id, first_generation)
            .await;
        let lost_result = tokio::time::timeout(std::time::Duration::from_secs(2), lost_execution)
            .await
            .unwrap()
            .unwrap();
        assert!(matches!(
            lost_result,
            Err(ControlError::Routing(RoutingError::RetryForbidden))
        ));
        assert!(
            second_outbound.try_recv().is_err(),
            "uncertain execution must not fail over"
        );
        state
            .runner_hub
            .unregister(&first.id, first_generation)
            .await;
        state
            .runner_hub
            .unregister(&second.id, second_generation)
            .await;
    }

