    #[test]
    fn corrupt_activation_audit_does_not_hide_the_current_license() {
        let directory = tempdir().expect("temp directory");
        let profile = create_profile(
            "installation_corrupt_activation_audit",
            &RawMachineFactors {
                dmi_product_uuid: "machine-corrupt-activation-audit".to_owned(),
                machine_id: "machine-id-corrupt-activation-audit".to_owned(),
            },
        )
        .expect("create profile");
        let (active, keys) = signed_bound_license(&profile, 1, "2026-08-26T00:00:00.000Z");
        let mut claims = v2::verify(&active, &keys).unwrap().claims().clone();
        set_test_transfer_sequence(&mut claims, 2);
        claims.issued_at = "2026-08-27T00:00:00.000Z".to_owned();
        claims.validity.not_before = "2026-09-01T00:00:00.000Z".to_owned();
        let future =
            serde_json::to_vec(&v2::sign(claims, &SigningKey::from_bytes(&[32_u8; 32])).unwrap())
                .unwrap();
        let target = directory.path().join("license/license.json");
        let history_path = directory.path().join("license/state.json");
        let history =
            Arc::new(LicenseStateStore::new(&history_path, &[80_u8; 32]).expect("create history"));
        install_license(
            &active,
            &target,
            &keys,
            &profile,
            &history,
            "0.1.0",
            datetime!(2026-08-28 0:00 UTC),
        )
        .unwrap();
        install_or_stage_license(
            &future,
            &target,
            &keys,
            &profile,
            &history,
            "0.1.0",
            datetime!(2026-08-28 0:01 UTC),
        )
        .unwrap();
        std::fs::write(
            directory.path().join("license/state.json.activation"),
            b"corrupt activation audit",
        )
        .unwrap();

        let state = ControlState::new("0.1.0", None)
            .with_license_state(Arc::clone(&history))
            .with_license_installer(target.clone(), keys, profile)
            .with_now(datetime!(2026-09-01 0:00 UTC));
        assert_eq!(
            state
                .current_license()
                .unwrap()
                .unwrap()
                .as_ref()
                .transfer_sequence(),
            1
        );
        assert_eq!(std::fs::read(&target).unwrap(), active);
        assert!(history.read_staged_document(&target).unwrap().is_some());
    }

    #[tokio::test]
    async fn failed_activation_audit_flush_rearms_the_single_probe() {
        let directory = tempdir().expect("temp directory");
        let profile = create_profile(
            "installation_activation_audit_retry",
            &RawMachineFactors {
                dmi_product_uuid: "machine-activation-audit-retry".to_owned(),
                machine_id: "machine-id-activation-audit-retry".to_owned(),
            },
        )
        .unwrap();
        let (active, keys) = signed_bound_license(&profile, 1, "2026-08-26T00:00:00.000Z");
        let mut claims = v2::verify(&active, &keys).unwrap().claims().clone();
        set_test_transfer_sequence(&mut claims, 2);
        claims.issued_at = "2026-08-27T00:00:00.000Z".to_owned();
        claims.validity.not_before = claims.issued_at.clone();
        let next =
            serde_json::to_vec(&v2::sign(claims, &SigningKey::from_bytes(&[32_u8; 32])).unwrap())
                .unwrap();
        let next = verify_product_license(&next, &keys).unwrap();
        let target = directory.path().join("license.json");
        let history = Arc::new(
            LicenseStateStore::new(directory.path().join("state.json"), &[81_u8; 32]).unwrap(),
        );
        let current = install_license(
            &active,
            &target,
            &keys,
            &profile,
            &history,
            "0.1.0",
            datetime!(2026-08-28 0:00 UTC),
        )
        .unwrap();
        history
            .stage_document(&target, &next, datetime!(2026-08-28 0:00 UTC))
            .unwrap();
        history
            .activate_staged_document(&target, &next, datetime!(2026-08-28 0:00 UTC))
            .unwrap();
        let state = ControlState::new("0.1.0", Some(current))
            .with_license_state(Arc::clone(&history))
            .with_license_installer(target.clone(), keys, profile)
            .with_now(datetime!(2026-08-28 0:01 UTC));

        assert!(state.current_license().unwrap().is_some());
        for _ in 0..100 {
            if state
                .license_activation_audit_initial_probe
                .load(Ordering::Acquire)
            {
                break;
            }
            tokio::task::yield_now().await;
        }
        assert!(
            state
                .license_activation_audit_initial_probe
                .load(Ordering::Acquire)
        );
        assert_eq!(history.pending_activation_audits(&target).unwrap().len(), 1);
    }

    #[test]
    fn later_active_history_discards_a_superseded_staged_license() {
        let directory = tempdir().expect("temp directory");
        let profile = create_profile(
            "installation_superseded_stage",
            &RawMachineFactors {
                dmi_product_uuid: "machine-superseded-stage".to_owned(),
                machine_id: "machine-id-superseded-stage".to_owned(),
            },
        )
        .expect("create profile");
        let (active, keys) = signed_bound_license(&profile, 1, "2026-08-26T00:00:00.000Z");
        let mut future_claims = v2::verify(&active, &keys).unwrap().claims().clone();
        set_test_transfer_sequence(&mut future_claims, 2);
        future_claims.issued_at = "2026-08-27T00:00:00.000Z".to_owned();
        future_claims.validity.not_before = "2026-09-01T00:00:00.000Z".to_owned();
        let future = serde_json::to_vec(
            &v2::sign(future_claims, &SigningKey::from_bytes(&[32_u8; 32])).unwrap(),
        )
        .unwrap();
        let mut later_claims = v2::verify(&active, &keys).unwrap().claims().clone();
        set_test_transfer_sequence(&mut later_claims, 3);
        later_claims.issued_at = "2026-08-29T00:00:00.000Z".to_owned();
        later_claims.validity.not_before = later_claims.issued_at.clone();
        let later = serde_json::to_vec(
            &v2::sign(later_claims, &SigningKey::from_bytes(&[32_u8; 32])).unwrap(),
        )
        .unwrap();
        let target = directory.path().join("license.json");
        let history = Arc::new(
            LicenseStateStore::new(directory.path().join("state.json"), &[77_u8; 32])
                .expect("create history"),
        );
        let installed = install_license(
            &active,
            &target,
            &keys,
            &profile,
            &history,
            "0.1.0",
            datetime!(2026-08-26 0:01 UTC),
        )
        .expect("install active license");
        assert!(matches!(
            install_or_stage_license(
                &future,
                &target,
                &keys,
                &profile,
                &history,
                "0.1.0",
                datetime!(2026-08-28 0:00 UTC),
            ),
            Ok(LicenseInstallOutcome::Staged(_))
        ));
        install_license(
            &later,
            &target,
            &keys,
            &profile,
            &history,
            "0.1.0",
            datetime!(2026-08-30 0:00 UTC),
        )
        .expect("install later active license");

        let state = ControlState::new("0.1.0", Some(installed))
            .with_license_state(Arc::clone(&history))
            .with_license_installer(target.clone(), keys, profile)
            .with_now(datetime!(2026-09-01 0:00 UTC));
        assert_eq!(
            state
                .current_license()
                .expect("load later active license")
                .expect("active license remains")
                .as_ref()
                .transfer_sequence(),
            3
        );
        assert_eq!(history.read_staged_document(&target).unwrap(), None);
        assert_eq!(std::fs::read(target).unwrap(), later);
    }

    #[test]
    fn future_license_waits_for_its_minimum_product_version() {
        let directory = tempdir().expect("temp directory");
        let profile = create_profile(
            "installation_future_version",
            &RawMachineFactors {
                dmi_product_uuid: "machine-future-version".to_owned(),
                machine_id: "machine-id-future-version".to_owned(),
            },
        )
        .expect("create profile");
        let (template, keys) = signed_bound_license(&profile, 1, "2026-08-27T00:00:00.000Z");
        let mut claims = v2::verify(&template, &keys).unwrap().claims().clone();
        claims.minimum_version = "2.0.0".to_owned();
        claims.validity.not_before = "2026-09-01T00:00:00.000Z".to_owned();
        let future =
            serde_json::to_vec(&v2::sign(claims, &SigningKey::from_bytes(&[32_u8; 32])).unwrap())
                .unwrap();
        let target = directory.path().join("license.json");
        let history = Arc::new(
            LicenseStateStore::new(directory.path().join("state.json"), &[78_u8; 32])
                .expect("create history"),
        );
        assert!(matches!(
            install_or_stage_license(
                &future,
                &target,
                &keys,
                &profile,
                &history,
                "1.0.0",
                datetime!(2026-08-28 0:00 UTC),
            ),
            Ok(LicenseInstallOutcome::Staged(_))
        ));
        let mut state = ControlState::new("1.0.0", None)
            .with_license_state(Arc::clone(&history))
            .with_license_installer(target.clone(), keys, profile)
            .with_now(datetime!(2026-09-01 0:00 UTC));
        assert!(state.current_license().unwrap().is_none());
        assert_eq!(scheduled_license_view(&state).1, "version_too_old");
        assert!(history.read_staged_document(&target).unwrap().is_some());

        state.product_version = Arc::from("2.0.0");
        assert_eq!(
            state
                .current_license()
                .expect("activate after product upgrade")
                .expect("future license is active")
                .as_ref()
                .minimum_version(),
            "2.0.0"
        );
        assert_eq!(history.read_staged_document(&target).unwrap(), None);
        assert_eq!(std::fs::read(target).unwrap(), future);
    }

