    #[test]
    fn bundled_first_install_license_must_be_current_free_v2_and_unbound() {
        let profile = create_profile(
            "installation_bundled_free_test",
            &RawMachineFactors {
                dmi_product_uuid: "machine-bundled-free-test".to_owned(),
                machine_id: "machine-id-bundled-free-test".to_owned(),
            },
        )
        .expect("create profile");
        let now = datetime!(2026-09-02 0:00 UTC);

        let (free, free_keys) = signed_v2_license(0, None);
        let accepted = verify_bundled_free_license(&free, &free_keys, "1.2.3-test.1", now, now)
            .expect("accept current unbound free distribution");
        assert!(matches!(accepted, VerifiedProductLicense::V2(_)));

        let mut maximum = free.clone();
        maximum.resize(MAX_LICENSE_DOCUMENT_BYTES, b' ');
        verify_bundled_free_license(&maximum, &free_keys, "1.2.3-test.1", now, now)
            .expect("accept an exact 64 KiB signed JSON document");
        let mut oversized = maximum;
        oversized.push(b' ');
        assert!(matches!(
            verify_bundled_free_license(&oversized, &free_keys, "1.2.3-test.1", now, now),
            Err(ControlError::LicenseInvalid(_))
        ));

        let (commercial, commercial_keys) = signed_v2_license(2, Some(&profile));
        assert!(matches!(
            verify_bundled_free_license(&commercial, &commercial_keys, "1.2.3-test.1", now, now,),
            Err(ControlError::LicenseInvalid(_))
        ));

        let legacy_license = verified_license();
        let legacy = legacy_license.source();
        let mut legacy_keys = TrustedLicenseKeys::new();
        legacy_keys
            .insert(
                "license-test-01",
                SigningKey::from_bytes(&[31; 32]).verifying_key(),
            )
            .unwrap();
        assert!(matches!(
            verify_bundled_free_license(legacy, &legacy_keys, "1.2.3-test.1", now, now),
            Err(ControlError::LicenseInvalid(_))
        ));

        assert!(matches!(
            verify_bundled_free_license(
                &free,
                &free_keys,
                "1.2.3-test.1",
                datetime!(2027-09-02 0:00 UTC),
                datetime!(2027-09-02 0:00 UTC),
            ),
            Err(ControlError::Policy(PolicyError::Expired))
        ));
        assert!(matches!(
            verify_bundled_free_license(&free, &free_keys, "1.2.2", now, now),
            Err(ControlError::Policy(PolicyError::VersionTooOld))
        ));

        let mut near_expiry: v2::Document = serde_json::from_slice(&free).unwrap();
        near_expiry.claims.validity.expiry = v2::Expiry::Fixed {
            expires_at: "2026-09-02T00:10:00.000Z".to_owned(),
        };
        let near_expiry = serde_json::to_vec(
            &v2::sign(near_expiry.claims, &SigningKey::from_bytes(&[42_u8; 32])).unwrap(),
        )
        .unwrap();
        verify_bundled_free_license(
            &near_expiry,
            &free_keys,
            "1.2.3-test.1",
            now,
            now + time::Duration::minutes(5),
        )
        .expect("accept a license through its requested bootstrap window");
        assert!(matches!(
            verify_bundled_free_license(
                &near_expiry,
                &free_keys,
                "1.2.3-test.1",
                now,
                now + time::Duration::minutes(15),
            ),
            Err(ControlError::Policy(PolicyError::Expired))
        ));
    }

    #[test]
    fn rejected_v2_candidates_do_not_create_a_license_or_history_file() {
        let directory = tempdir().expect("temp directory");
        let profile = create_profile(
            "installation_v2_rejection_test",
            &RawMachineFactors {
                dmi_product_uuid: "machine-v2-rejection".to_owned(),
                machine_id: "machine-id-v2-rejection".to_owned(),
            },
        )
        .expect("create profile");
        let (free, free_keys) = signed_v2_license(0, None);
        let (commercial, _) = signed_v2_license(2, Some(&profile));
        let cases = [
            (
                "expired",
                free.as_slice(),
                &free_keys,
                "1.2.3-test.1",
                datetime!(2027-09-02 0:00 UTC),
            ),
            (
                "future",
                free.as_slice(),
                &free_keys,
                "1.2.3-test.1",
                datetime!(2026-08-31 0:00 UTC),
            ),
            (
                "minimum-version",
                free.as_slice(),
                &free_keys,
                "1.2.2",
                datetime!(2026-09-02 0:00 UTC),
            ),
            (
                "issuer-scope",
                commercial.as_slice(),
                &free_keys,
                "1.2.3-test.1",
                datetime!(2026-09-02 0:00 UTC),
            ),
        ];
        for (name, source, keys, product_version, now) in cases {
            let target = directory.path().join(name).join("license.json");
            let history_path = directory.path().join(name).join("state.json");
            let history = LicenseStateStore::new(&history_path, &[73_u8; 32]).unwrap();
            assert!(
                install_license(
                    source,
                    &target,
                    keys,
                    &profile,
                    &history,
                    product_version,
                    now,
                )
                .is_err(),
                "{name}"
            );
            assert!(!target.exists(), "{name} must not create a license file");
            assert!(!history_path.exists(), "{name} must not create history");
        }

        let target = directory.path().join("replacement/license.json");
        let history_path = directory.path().join("replacement/state.json");
        let pending_path = directory.path().join("replacement/state.json.pending");
        let history = LicenseStateStore::new(&history_path, &[74_u8; 32]).unwrap();
        install_license(
            &free,
            &target,
            &free_keys,
            &profile,
            &history,
            "1.2.3-test.1",
            datetime!(2026-09-02 0:00 UTC),
        )
        .unwrap();
        let mut expired: v2::Document = serde_json::from_slice(&free).unwrap();
        expired.claims.license_id = "test_free_expired_replacement".to_owned();
        expired.claims.validity.expiry = v2::Expiry::Fixed {
            expires_at: "2026-09-02T00:00:00.000Z".to_owned(),
        };
        let expired = serde_json::to_vec(
            &v2::sign(expired.claims, &SigningKey::from_bytes(&[42_u8; 32])).unwrap(),
        )
        .unwrap();
        let license_before = std::fs::read(&target).unwrap();
        let history_before = std::fs::read(&history_path).unwrap();
        let pending_before = std::fs::read(&pending_path).unwrap();
        assert!(matches!(
            install_license(
                &expired,
                &target,
                &free_keys,
                &profile,
                &history,
                "1.2.3-test.1",
                datetime!(2026-09-03 0:00 UTC),
            ),
            Err(ControlError::Policy(PolicyError::Expired))
        ));
        assert_eq!(std::fs::read(&target).unwrap(), license_before);
        assert_eq!(std::fs::read(&history_path).unwrap(), history_before);
        assert_eq!(std::fs::read(&pending_path).unwrap(), pending_before);
    }

    #[test]
    fn admin_license_view_is_stable_across_v1_and_v2_time_and_quota_modes() {
        let v1 = verified_license_with_seats(10);
        let v1_view = license_admin_view(&v1);
        assert_eq!(v1_view["protocol_schema"], LICENSE_SCHEMA);
        assert_eq!(v1_view["features"], json!(["gateway", "member", "runner"]));
        assert_eq!(v1_view["quotas"]["member_seats"], 10);
        assert_eq!(v1_view["quotas"]["runners"], Value::Null);
        assert_eq!(v1_view["binding"], "installation");

        let (free_fixed, free_fixed_keys) = signed_v2_license(0, None);
        let free_fixed = verify_product_license(&free_fixed, &free_fixed_keys).unwrap();
        let free_fixed_view = license_admin_view(&free_fixed);
        assert_eq!(free_fixed_view["protocol_schema"], v2::SCHEMA);
        assert_eq!(free_fixed_view["customer_ref"], Value::Null);
        assert_eq!(free_fixed_view["quotas"]["member_seats"], 3);
        assert_eq!(free_fixed_view["quotas"]["runners"], 1);
        assert_eq!(free_fixed_view["binding"], "unbound");
        assert_eq!(free_fixed_view["expires_at"], "2027-09-01T00:00:00.000Z");

        let (free_no_expiry, free_no_expiry_keys) = signed_v2_license(1, None);
        let free_no_expiry = verify_product_license(&free_no_expiry, &free_no_expiry_keys).unwrap();
        assert_eq!(
            license_admin_view(&free_no_expiry)["expires_at"],
            Value::Null
        );
    }

